(window.GIM_TS=window.GIM_TS||{})["Bava Kamma.1"]={"from":24,"a":[["\u0003ולא קבל עליו שמירת נזקיו,\u0004 שהתנה שלא יהא אחראי לנזקים שיזיק השור, ולפיכך חייב המשאיל לשלם לשואל, ואם היה השור תם — משלם חצי נזק.","ושואלים: \u0003אי הכי אימא סיפא\u0004 \u0005[אם כך\u0006 אתה מפרש, \u0005אמור\u0006 את \u0005סוף\u0006 הברייתא\u0005]:\u0006 \u0003נפרצה\u0004 הגדר \u0003בלילה או שפרצוה לסטים ויצתה והזיקה\u0004 — \u0003פטור,\u0004 נדייק מכאן: דווקא בלילה הוא פטור, \u0003הא\u0004 \u0005[הרי]\u0006 אם היה הדבר \u0003ביום\u0004 — יהא \u0003חייב,\u0004 ואולם כיצד אפשר לומר זאת? \u0003הא\u0004 \u0005[הרי]\u0006 לשיטתך מדובר במשנתנו במי ש\u0003לא קבל עליו\u0004 \u0003שמירת נזקיו\u0004!","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך\u0006 הוא \u0005אומר],\u0006 כך צריך לפרש את סוף הברייתא, שהוא דן במקרה אחר: \u0003אם קבל עליו שמירת נזקיו\u0004 — \u0003חייב,\u0004 ואולם אם \u0003נפרצה בלילה, או שפרצוה לסטים ויצתה והזיקה\u0004 — \u0003פטור.\u0004","על עצם שיטתו של ר' אלעזר, שחצר השותפים פטורים בה השותפים על נזקי השן והרגל, שואלים: \u0003איני\u0004 \u0005[\u0006וכי \u0005כן הוא]\u0006 וכי אפשר לומר כדברי ר' אלעזר? \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003רב יוסף\u0004 ברייתא זו: \u0003חצר השותפים והפונדק\u0004 — \u0003חייב בהן על השן ועל הרגל.\u0004 הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003ר' אלעזר!\u0004","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך ר' אלעזר:\u0004 \u0003ותסברא מתניתא מי לא פליגי\u0004 \u0005[וכי סבור אתה\u0006 ש\u0005הברייתות\u0006 עצמן \u0005אינן חלוקות]\u0006 בנושא זה? אפשר להראות שיש גם ברייתא החולקת על דעה זו, \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ארבעה כללות\u0004 (כללים) \u0003היה ר' שמעון בן אלעזר אומר\u0004 \u0003ב\u0004ענין המקומות שבהם היו ה\u0003נזקין\u0004 וחיוב המזיק עליהם: \u0003כל\u0004 מקום \u0003שהוא רשות לניזק ולא למזיק\u0004 — \u0003חייב\u0004 המזיק \u0003בכל.\u0004 מקום שהוא רשות של ה\u0003מזיק ולא לניזק\u0004 — \u0003פטור\u0004 המזיק \u0003מכל.\u0004","מקום שהוא רשות \u0003לזה ולזה, כגון חצר השותפים\u0004 א\u0003ו הבקעה\u0004 (שטח רחב השייך לציבור) — \u0003פטור בה על השן ועל הרגל,\u0004 ואילו \u0003על הנגיחה ועל הנגיפה ועל הנשיכה ועל הרביצה ועל הבעיטה\u0004 שכולן הן קרן ותולדותיה — \u0003תם משלם חצי נזק, ומועד משלם נזק שלם.\u0004","מקום שאינו שייך \u0003לא לזה ולא לזה, כגון חצר שאינו של שניהם\u0004 — \u0003חייב בו על השן ועל הרגל,\u0004 ואילו \u0003על הנגיחה ועל הנשיכה ועל הנגיפה ועל הרביצה ועל הבעיטה\u0004 שהן תולדות קרן — \u0003תם משלם חצי נזק, ומועד משלם נזק שלם.\u0004","\u0003קתני מיהת\u0004 \u0005[שנינו על כל פנים]:\u0006 \u0003חצר השותפין והבקעה\u0004 — \u0003פטור בה על השן ועל הרגל\u0004 וכדעת ר' אלעזר. ואם כן אין להקשות עליו מברייתא אחרת.","ושואלים: מכל מקום \u0003קשיא אהדדי\u0004 \u0005[קשות\u0006 הן הברייתות \u0005זו על זו]!\u0006","ומשיבים: \u0003כי תניא\u0004 \u0005[כאשר שנויה\u0006 ההלכה\u0005]\u0006 \u0003ההיא\u0004 בדברי ר' שמעון בן אלעזר, הרי זה \u0003בחצר\u0004 ה\u0003מיוחדת לזה ולזה,\u0004 כלומר, שבחצר זו מותר לשני השותפים להשתמש \u0003בין לפירות בין לשוורים,\u0004 ולכן אין המזיק חייב על נזק שן ורגל שגרם שורו לפירות חבירו. ואילו \u0003ההיא\u0004 \u0005[אותה\u0006 ברייתא\u0005]\u0006 ששנה \u0003רב יוסף\u0004 שחייב בה בחצר השותפים על נזקי שן ורגל — \u0003בחצר מיוחדת\u0004 לשותפות רק \u0003לפירות, ואינה מיוחדת לשוורים\u0004 שאין רשות להכניס בה שוורים. \u0003דלגבי\u0004 \u0005[שאצל]\u0006 נזקי \u0003שן,\u0004 כיון שאסור להכניס בה שוורים, \u0003הויא לה\u0004 \u0005[הרי היא]\u0006 כמו \u0003חצר הניזק\u0004 וחייב בעל השור.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 פירוש זה מלשון הברייתות, \u0003דקתני הכא\u0004 \u0005[ששנה כאן]\u0006 בברייתא ששנה רב יוסף, חצר השותפים \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003פונדק\u0004 שנשנה יחד עמה, שאינו מקום מיוחד להכניס שם שוורים אלא רק פירות, \u0003וקתני התם\u0004 \u0005[ושנה שם]\u0006 בברייתא של ר' שמעון בן אלעזר, חצר השותפין \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003בקעה\u0004 שהיא מקום הפתוח לכל וגם לשוורים, ואם כן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שתירוץ זה שתירצנו נכון הוא.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא: כיון\u0004 שבברייתא של רב יוסף מדובר שהחצר \u0003מיוחדת לפירות\u0004 עבור שני השותפים, מדוע חייב בעל השור בשן ורגל? \u0003הא\u0004 \u0005[הרי]\u0006 כדי לחייבו \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיתקיים הפסוק \u0003\"ובער בשדה אחר\"\u0004 (שמות כב, ד) \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 שהרי אין זה שדה של אחר, אלא שדה השייך לשניהם!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: כיון\u0004 ש\u0003אינה מיוחדת לשוורים\u0004 ואסור להכניס בה שור, \u0003\"שדה אחר\" קרינא ביה\u0004 \u0005[קוראים אנו בו]\u0006 לענין נזקים.","בעקבות דיון זה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדיפתי לרבינא: לימא\u0004 \u0005[האם לומר]\u0006 \u0003מדמתניתא לא פליגי, אמוראי נמי לא פליגי\u0004 \u0005[מ\u0006כיון \u0005שהברייתות אינן חלוקות, גם האמוראים\u0006 ר' אלעזר ורב חסדא \u0005אינם חלוקים]\u0006 ונאמר שר' אלעזר אמר דבריו במקרה אחד, ורב חסדא אמר במקרה אחר, ואינם חלוקים כלל?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן]\u0006 הוא הדבר. \u0003ואם תמצא לומר\u0004 בכל זאת כי \u0003פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005]\u0006 הרי \u0003בקושיא\u0004 שהקשה \u0003ר' זירא ובפירוקא\u0004 \u0005[ובתירוץ]\u0006 של \u0003אביי פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 האם שדה שותפים שאין רשות להכניס לתוכה שוורים אף שמותר להניח שם פירות — הריהי בכלל \"שדה אחר\", או לא.","כיון שהוזכרה התוספתא שבה הובאו הכללים שקבע ר' שמעון בן אלעזר, דנים בה. \u0003גופא\u0004 \u0005[לעצמה]:\u0006 \u0003ארבעה כללות היה ר' שמעון בן אלעזר אומר בנזקין,\u0004 והכלל הראשון: \u0003כל\u0004 מקום \u0003שהוא רשות לניזק ולא למזיק\u0004 — \u0003חייב בכל.\u0004","ומדייקים: \u0003\"על הכל\" לא קתני\u0004 \u0005[שנה],\u0006 כלומר, לא היתה כוונה לומר שחייב על כל מיני אבות הנזיקין, \u0003אלא \"חייב בכל\"\u0004 — לומר שחייב לשלם \u0003בכולי\u0004 \u0005[בכל]\u0006 ה\u0003נזק,\u0004 כלומר, תשלום מלא.","\u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 הלכה זו — כשיטת \u0003ר' טרפון היא,\u0004 ש\u0003אמר\u0004 כלל: \u0003משונה\u0004 דין \u0003קרן בחצר הניזק,\u0004 ש\u0003נזק שלם משלם\u0004 ואפילו היה זה שור תם. שכיון שנכנס לחצר הניזק שלא ברשות אין אנו מקילים בתם יותר מבמועד, כפי שהוא ברשות הרבים.","ואולם \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף\u0006 הברייתא\u0005]\u0006 ונראה אם אמנם אפשר לפרש כן, שהרי שנינו שם: חצר שאינה מיוחדת \u0003לא לזה ולא לזה, כגון חצר שאינו של שניהם\u0004 — \u0003חייב בה על השן ועל הרגל.\u0004","ויש לברר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא לזה ולא לזה\"? אילימא\u0004 \u0005[אם תאמר]\u0006 שאינה רשות \u0003לא לזה ולא לזה כלל, אלא\u0004 של אדם \u0003אחר\u0004 — \u0003והא בעינא\u0004 \u0005[והרי צריכים אנו]\u0006 שיתקיים \u0003\"ובער בשדה אחר\"\u0004 כדי לחייבו, \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 שהרי אין זה שדהו של הניזק!","\u0003אלא\u0004 \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שיש לפרש: \u0003לא לזה ולא לזה אלא דחד\u0004 \u0005[של\u0006 \u0005אחד\u0006 מהם\u0005],\u0006 של הניזק, \u0003וקתני סיפא\u0004 \u0005[ושנינו בסופה\u0006 של הברייתא\u0005]\u0006 שבמקרה כזה \u0003תם משלם חצי נזק ומועד משלם נזק שלם.\u0004","אם כן \u0003אתאן\u0004 \u0005[באנו]\u0006 \u0003ל\u0004שיטת \u0003רבנן דאמרי\u0004 \u0005[חכמים, שאומרים]:\u0006 \u0003משונה\u0004 דין \u0003קרן\u0004 שמזיק \u0003בחצר הניזק,\u0004 שכיון שהוא משונה ובלתי רגיל, תם \u0003חצי נזק הוא\u0004 ש\u0003משלם.\u0004","וכי \u0003רישא\u0004 \u0005[ראשה]\u0006 של הברייתא כדעת \u0003ר' טרפון וסיפא רבנן\u0004 \u0005[וסופה כ\u0006דעת \u0005חכמים]?\u0006","ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 כך הוא. \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב יהודה: שיננא\u0004 \u0005[גדול השיניים],\u0006 \u0003שבוק מתניתין ותא אבתראי\u0004 \u0005[עזוב\u0006 את \u0005משנתנו ובוא אחרי],\u0006 כלומר, אל תתקשה בלשון הברייתא ובמשנה ותנסה להביאן לידי אחדות פנימית, אלא לך לפי הכרעה שאומר לך, שהיא מסקנת ההלכה, כי ברייתא זו אינה אחידה, אלא \u0003רישא\u0004 \u0005[ראשה]\u0006 \u0003ר' טרפון, וסיפא רבנן\u0004 \u0005[וסופה חכמים].\u0006","\u0003רבינא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר:\u0004 כל הברייתא \u0003כולה\u0004 כשיטת \u0003ר' טרפון היא, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 חצר שאינה מיוחדת \u0003לא לזה ולא לזה,\u0004 כוונתו — אינה מיוחדת \u0003לא לזה ולא לזה לפירות, אלא דחד\u0004 \u0005[של אחד\u0006 מהם\u0005]\u0006 הניזק, \u0003ולזה ולזה\u0004 מיוחדת היא \u0003לשוורים.\u0004","\u0003דלגבי\u0004 \u0005[שאצל]\u0006 \u0003שן הויא לה\u0004 \u0005[הרי היא]\u0006 \u0003חצר הניזק, ולגבי\u0004 \u0005[ואצל]\u0006 \u0003קרן הויא לה\u0004 \u0005[הרי היא]\u0006 \u0003רשות הרבים.\u0004","ואומרים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 מדוע \u0003ארבעה\u0004 כללים הם? הרי \u0003שלשה הוו\u0004 \u0005[הם],\u0006 שיש כאן רק שלוש הלכות עקרוניות: רשות הניזק — שחייב בה על הכל, רשות המזיק — שפטור בה על הכל, ורשות משותפת — שחייב בה על הקרן ולא על השן. ואין המקרה הרביעי אלא צירוף של העקרונות הקודמים — חיוב שן בחצר הניזק, וחיוב קרן ברשות משותפת!","\u0003אמר רב נחמן בר יצחק:\u0004"],["\u0003שלשה כללות\u0004 שלושה דינים נבדלים \u0003בארבע מקומות\u0004 השונים זה מזה בהגדרתם. שאף שאין כאן ארבעה דינים שונים, מכל מקום כיון שמדובר בארבעה מקומות שונים בדינם, מחשיבים אותם כארבעה כללות.","כיצד נגבים הנזקים? — \u0003שום\u0004 (הערכת) \u0003כסף,\u0004 ב\u0003שוה כסף, בפני בית דין. ו\u0004נזקין גובים \u0003על פי עדים\u0004 שהם \u0003בני חורין\u0004 ולא עבדים, \u0003בני ברית\u0004 (יהודים) ולא גוים. \u0003והנשים בכלל הנזק,\u0004 הן בשעה שהן מזיקות והן כשהן ניזוקות, שאין דין שונה לגברים ולנשים בזה. \u0003והניזק והמזיק\u0004 לעתים משתתפים \u0003בתשלומין.\u0004","משנה זו שלשונה קצרה ביותר צריכה תחילה לפירוש עצם המילים והמושגים שבה. ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שום כסף\"\u0004 השנוי במשנה?","\u0003אמר רב יהודה: שום\u0004 (הערכה) \u0003זה\u0004 \u0003לא יהא אלא בכסף,\u0004 שצריך לקבוע ערך כספי מדוייק לנזק, שלא יעשוהו בקירוב ובהשוואה לדברים אחרים.","ומעירים: אם כן \u0003תנינא להא דתנו רבנן\u0004 \u0005[שנינו\u0006 במשנה \u0005את\u0006 ההלכה \u0005הזו ששנו חכמים\u0006 בברייתא הבאה\u0005]:\u0006 \u0003פרה שהזיקה טלית,\u0004 וכגון שדרסה עליה וקרעתה, \u0003וטלית שהזיקה פרה\u0004 שהסתבכה רגל הפרה בטלית זו ונשברה, \u0003אין אומרים: תצא פרה בטלית וטלית בפרה,\u0004 מתוך הנחה שהנזק הוא שווה בערכו, \u0003אלא שמין אותה בדמים\u0004 גם את הטלית וגם את הנזק שנגרם לפרה, ואם יש עודף משלם החייב את ההפרש הזה.","וממשיכים בפירוש המשנה: \u0003\"שוה כסף\"\u0004 מהו?","\u0003דתנו רבנן\u0004 \u0005[ששנו חכמים\u0006 בפירוש הדברים\u0005]:\u0006 \u0003\"שוה כסף\"\u0004 — הרי זה \u0003מלמד שאין בית דין\u0004 עצמם \u0003נזקקין\u0004 לגבות מן המזיק \u0003אלא לנכסים שיש להן אחריות,\u0004 כלומר, קרקעות. \u0003אבל אם קדם ניזק ותפס מטלטלין\u0004 של המזיק לפרעון נזקו — \u0003בית דין גובין לו מהן.\u0004","ומבררים את הדברים: \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"שוה כסף\"\u0004 — \u0003מלמד שאין בית דין נזקקין אלא לנכסים שיש להן אחריות.\u0004 ושואלים: \u0003מאי משמע\u0004 \u0005[מה המשמעות],\u0006 כיצד נשמע מובן דבר זה מהלשון \"שווה כסף\", שנפרעים בית דין דווקא מקרקעות?","\u0003אמר רבה בר עולא,\u0004 משמעות הדברים היא: \u0003דבר השוה כל כסף, מאי ניהו\u0004 \u0005[\u0006ו\u0005מה הוא]\u0006 — \u0003דבר שאין לו אונאה,\u0004 כי אין דין אונאה בקרקעות, והמשלם יותר מערכה של הקרקע לא נחשב כמי שרימוהו במיקח. ומקשים: הלא \u0003עבדים ושטרות נמי\u0004 \u0005[גם כן]\u0006 \u0003אין להן אונאה,\u0004 ומהם אין נפרעים בית דין לנזקים! ונמצא שאין הסבר זה מתאים.","\u0003אלא אמר רבה בר עולא:\u0004 \"שווה כסף\" כוונתו: \u0003דבר הנקנה בכסף,\u0004 והרי זה דווקא קרקעות, כי מיטלטלים אינם נקנים אלא במשיכה. וגם על הסבר זה מקשים כמקודם: \u0003עבדים ושטרות נמי\u0004 \u0005[גם כן]\u0006 \u0003נקנין בכסף!\u0004","\u0003אלא אמר רב אשי:\u0004 יש להבין את המשנה כמתייחסת לקרקעות במובן: \u0003\"שוה כסף\"\u0004 — \u0003ולא כסף, והני כולהו\u0004 \u0005[ואלו כולם]\u0006 מיטלטלים, ואף עבדים ושטרות — \u0003כסף נינהו\u0004 \u0005[הם],\u0006 שכל הדברים המיטלטלים שיש להם ערך, כיון שאפשר להעבירם מיד ליד אפשר לקרוא להם \"כסף\", מה שאין כן קרקעות, שאינן כסף.","ובענין זה \u0003רמי ליה\u0004 \u0005[השליך לו,\u0006 הראה לו סתירה\u0005]\u0006 \u0003רב יהודה בר חיננא לרב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא זו: \u0003\"שוה כסף\"\u0004 — \u0003מלמד שאין בית דין נזקקין אלא לנכסים שיש להן אחריות,\u0004 כלומר, דווקא קרקעות. \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא אחרת\u0005]\u0006 על האמור בתשלום נזקים: \"כסף \u0003ישיב\u0004 לבעליו\" (שמות כא, לד) — \u0003לרבות שוה כסף,\u0004 שניתן לשלם לנזקים מכל דבר \u0003ואפילו סובין.\u0004 משמע שגובים ממזיק אפילו ממיטלטלים!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 בברייתא לפיה אין גובים אלא מקרקעות — \u0003ביתמי\u0004 \u0005[ביתומים],\u0006 שאביהם (או ממונו) הזיק ומת האב ונשארו יתומים, שמהם אין בית דין גובה אלא קרקעות, ולא מיטלטלים.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 אתה מפרש שכאן עוסקים \u0003ביתמי\u0004 \u0005[ביתומים],\u0006 \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של הברייתא: \u0003אם קדם ניזק ותפס מטלטלין\u0004 — \u0003בית דין גובין לו מהן. אי ביתמי\u0004 \u0005[אם ביתומים]\u0006 מדובר, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003בית דין גובין לו מהן?\u0004 והרי מיטלטלים של יתומים אין משתעבדים לחוב של אביהם!","ומשיבים: יש להסביר דבר זה \u0003כדאמר\u0004 \u0005[כפי\u0006 \u0005שאמר]\u0006 \u0003רבא אמר רב נחמן\u0004 שמועילה תפיסה של בעל חוב בנכסי אדם שמת, במקרה \u0003שתפס\u0004 בעל החוב \u0003מחיים\u0004 (בחיי האב). \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש לפרש \u0003שתפס מחיים\u0004 את המיטלטלים, ובינתיים מת המזיק, שגובה מן המיטלטלים שתפס, אף שכעת אין המזיק בחיים, אלא יתומיו.","עוד שנינו במשנה: \u0003בפני בית דין.\u0004","ומסבירים, הדגשה זו באה ללמדנו: \u0003פרט ל\u0004מקרה שהמזיק \u0003מוכר נכסיו ואחר כך הולך לבית דין,\u0004 ואין להם עתה ממה לגבות ממנו, שאין בית דין גובה מן הנכסים שנמכרו.","ותוהים: \u0003שמע מינה\u0004 \u0005[\u0006האם \u0005תלמד מכאן]\u0006 שאם אדם \u0003לוה\u0004 כסף \u0003ומכר נכסיו ואחר כך בא\u0004 המלוה \u0003לבית דין, אין בית דין גובין לו מהן?\u0004 הרי כמה וכמה הלכות יש בענין זה, שכל הקרקעות השייכות ללווה משתעבדות לחוב בעליהן וגובים מהן בעלי החוב את חובם!","\u0003אלא\u0004 יש לחזור מהסבר זה ולומר: \"בפני בית דין\" באה ללמד: \u0003פרט לבית דין הדיוטות,\u0004 שדיני קנסות שבנזקין ניתן לגבות רק בבית דין של מומחים, שלמדו וקיבלו רשות להורות, ולא בבית דין של הדיוטות.","עוד שנינו במשנה: \u0003על פי עדים.\u0004","ומסבירים, הדגשה זו באה ללמדנו: \u0003פרט ל\u0004מי שהיה \u0003מודה בקנס,\u0004 כלומר, מודה מעצמו בעבירה שחייב עליה קנס קצוב מן התורה \u0003ואחר כך באו עדים\u0004 והעידו שעשה דבר זה, \u0003שהוא פטור.\u0004","ושואלים: \u0003הניחא\u0004 \u0005[\u0006דבר \u0005זה נוח]\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]:\u0006 \u0003מודה בקנס ואחר כך באו עדים\u0004 — \u0003פטור. אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]:\u0006 \u0003מודה בקנס ואחר כך באו עדים\u0004 — \u0003חייב, מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 בהסבר הדגשה זו של המשנה?","ומשיבים: לפי שיטה זו \"על פי עדים\" באמת לא נצרך להיאמר לעצמו, אלא \u0003סיפא אצטריך ליה\u0004 \u0005[סופו\u0006 המשכו של המשפט \u0005הוצרך לו]\u0006 כדי להגדיר מי הם העדים הכשרים לחייב על פיהם בדיני נזיקין:"],["שיהיו העדים \u0003בני חורין ובני ברית, בני חורין\u0004 — \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003עבדים, בני ברית\u0004 — \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003גוים.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו שני המיעוטים הללו; \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 במשנה רק את מיעוטו של \u0003עבד\u0004 הייתי אומר: דווקא עבד אינו כשר לעדות נזיקין \u0003משום\u0004 ש\u0003אין לו יחס,\u0004 שעבד אינו מתייחס אחר משפחתו, ואין לו קשרי משפחה מוכרים בהלכה, והרי הוא לענין זה כבהמה, \u0003אבל גוי\u0004 ש\u0003יש לו יחס\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 שדינו \u0003לא\u0004 כעבד, ויהיה הגוי רשאי להעיד בעדות נזיקין. ולהיפך: \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק את המיעוט של \u0003גוי\u0004 שפסול להעיד, היינו אומרים: דווקא גוי פסול \u0003משום\u0004 ש\u0003לא שייך במצו‍ת\u0004 כלל, \u0003אבל עבד\u0004 ש\u0003שייך במצו‍ת,\u0004 שהרי הוא חייב בכל המצוות שאשה חייבת בהן, \u0003אימא\u0004 \u0005[אמור]\u0006 שדינו \u0003לא\u0004 כגוי, ויהיה כשר לעדות, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שניהם.","עוד שנינו במשנה: \u0003והנשים בכלל הנזק.\u0004 ומבררים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]?\u0006","\u0003אמר רב יהודה אמר רב, וכן תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל,\u0004 \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 המחייב להשיב גזילה וחומשה ולהביא קרבן אשם לכפרה: \u0003\"איש או אשה כי יעשו מכל חטאת\u0004 האדם\u0003\"\u0004 (במדבר ה, ו), למדנו מכאן ש\u0003השוה הכתוב אשה לאיש לכל עונשין שבתורה,\u0004 שהרי גם האשה צריכה כפרה.","\u0003דבי\u0004 \u0005[\u0006החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' אלעזר תנא\u0004 \u0005[שנה]\u0006 דרשה אחרת מניין נלמדה הלכה זו: נאמר בפתיחה לפרשת משפטים \u0003\"ואלה המשפטים אשר תשים לפניהם\"\u0004 (שמות כא, א) שנאמר בלשון רבים, לכלול גברים ונשים, הרי \u0003השוה הכתוב\u0004 בפסוק זה \u0003אשה לאיש לכל דינין\u0004 (של ממונות) \u0003שבתורה\u0004 שהם המפורשים באותה פרשה.","\u0003דבי\u0004 \u0005[\u0006החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה ו\u0004כן החכם מבית מדרשו של \u0003ר' יוסי הגלילי תנא\u0004 \u0005[שנה]\u0006 דרשה אחרת, \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדין שור הנוגח: \u0003\"והמית איש או אשה\"\u0004 (שמות, כט) — \u0003השוה הכתוב אשה לאיש לכל מיתות שבתורה,\u0004 שהדין החל על ההורג איש חל גם על הורג אשה, ואם נהרגה בידי שור, בעליו משלמים כופר ליורשיה.","מעירים: \u0003וצריכי\u0004 \u0005[וצריכים]\u0006 את כל שלושת הכתובים הללו ללמוד מהם להשוות דיני נשים לאנשים. \u0003דאי אשמעינן קמייתא\u0004 \u0005[שאם היה משמיע לנו\u0006 רק את הלימוד \u0005הראשון]\u0006 שאף האשה מביאה קרבן על חטאתה, הייתי אומר: דווקא \u0003התם\u0004 \u0005[שם]\u0006 כך \u0003הוא\u0004 הדין, משום ש\u0003חס רחמנא עלה\u0004 \u0005[הכתוב עליה],\u0006 \u0003כי היכי דתהוי\u0004 \u0005[כדי שתהיה]\u0006 \u0003לה כפרה\u0004 על עוונה, \u0003אבל\u0004 בענייני \u0003דינין\u0004 של ממונות הייתי אומר: \u0003איש דבר\u0004 \u0005[שבן]\u0006 \u0003משא ומתן\u0004 הוא, שהוא כרגיל הנושא והנותן — \u0003אין\u0004 \u0005[כן]\u0006 שייך בזה, ואולם \u0003אשה\u0004 — \u0003לא.\u0004","ולהיפך, \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק את הלימוד ב\u0003דינין\u0004 שבהם שווה אשה לאיש, הייתי אומר: דווקא שם כך הוא הדין, \u0003כי היכי דתיהוי\u0004 \u0005[כדי שתהיה]\u0006 \u0003לה חיותא\u0004 \u0005[חיות]\u0006 שתוכל להתעסק בפרנסה למחייתה. שאם אינה בכלל הדינים — לא יעסקו איתה בכל עסק. \u0003אבל\u0004 לענין \u0003כפרה\u0004 על חטאיה, \u0003איש דבר\u0004 \u0005[שבן]\u0006 \u0003מצוה,\u0004 כלומר, שחייב בכל המצוות — \u0003אין\u0004 \u0005[כן],\u0006 אבל \u0003אשה דלאו\u0004 \u0005[שלא]\u0006 \u0003בת מצוה\u0004 היא, שאינה חייבת בכל המצוות — \u0003לא.\u0004","\u0003ואי אשמעינן הני תרתי\u0004 \u0005[ואם היה משמיע לנו\u0006 רק את \u0005שני אלה],\u0006 הייתי אומר: \u0003הכא\u0004 \u0005[כאן]\u0006 בקרבנות שווה אשה לאיש \u0003משום כפרה, והכא\u0004 \u0005[וכאן]\u0006 בדינים שווה אשה לאיש \u0003משום חיותא\u0004 \u0005[חיים],\u0006 \u0003אבל לענין קטלא\u0004 \u0005[מיתה]\u0006 לחייב תשלום כופר ליורשי מי שנהרג על ידי שור, \u0003איש דבר\u0004 \u0005[שבן]\u0006 \u0003מצוה\u0004 הוא בכלל, חייב בעל השור \u0003לשלם\u0004 עבורו \u0003כופר,\u0004 אבל \u0003אשה\u0004 — \u0003לא.\u0004","\u0003ואי אשמעינן\u0004 \u0005[ואילו היה משמיע לנו]\u0006 רק בדין \u0003כופר,\u0004 הייתי אומר שבזה שווה דין אשה לדין איש — \u0003משום דאיכא\u0004 \u0005[שיש]\u0006 כאן \u0003איבוד נשמה\u0004 ודבר חמור הוא ביותר ולכן חייב לשלם גם עבור אשה. \u0003אבל הני תרתי דליכא\u0004 \u0005[אלה השניים,\u0006 עונשים ודינים, \u0005שאין\u0006 בהם\u0005]\u0006 \u0003איבוד נשמה\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יהיה הדין כן, ואין האשה שווה לאיש, לכן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו כל שלושת הכתובים.","שנינו במשנה: \u0003הניזק והמזיק בתשלומין.\u0004","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שחלקו אמוראים בבעיה הבאה: \u0003פלגא נזקא\u0004 \u0005[\u0006תשלום \u0005חצי נזק]\u0006 שנגבה משור תם שנגח, מהי הגדרתו מבחינה משפטית? \u0003רב פפא אמר:\u0004 הרי זה כשאר תשלום וחיוב \u0003ממונא\u0004 \u0005[ממון]\u0006 הוא, כלומר, שנחשב תשלום פיצוי לניזק עבור הנזק שנגרם לו. ו\u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר:\u0004 תשלום זה \u0003קנסא\u0004 \u0005[קנס]\u0006 הוא, שקנסה התורה את המזיק, ולא מן הדין, ואינו תשלום פיצוי לניזק עבור הנזק.","ומבארים את השיטות: \u0003רב פפא\u0004 ש\u0003אמר\u0004 תשלום חצי נזק שמשלם התם חיוב \u0003ממונא\u0004 \u0005[ממון]\u0006 הוא, \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 \u0003סתם שוורים לאו\u0004 \u0005[לא]\u0006 \u0003בחזקת שימור קיימן\u0004 \u0005[עומדים],\u0006 וכל שור נחשב כעומד להזיק, \u0003ו\u0004משום כך \u0003בדין הוא\u0004 \u0003דבעי לשלומי כוליה\u0004 \u0005[ש\u0006היה \u0005צריך\u0006 המזיק \u0005לשלם\u0006 את הנזק \u0005כולו]\u0006 שהזיק שורו, \u0003ורחמנא\u0004 \u0005[והכתוב]\u0006 \u0003הוא\u0004 ש\u0003חס עליה\u0004 \u0005[עליו]\u0006 שישלם רק מחצית, וזאת משום \u0003דאכתי\u0004 \u0005[שעדיין]\u0006 \u0003לא אייעד תוריה\u0004 \u0005[הועד שורו]\u0006 בבית דין, שלא היתה הוכחה ואזהרה על ידי עדים לכך, אבל בעצם מה שמשלם הוא תשלום שחייב היה לשלם.","ואילו \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004 ש\u0003אמר\u0004 שתשלום חצי נזק \u0003קנסא\u0004 \u0005[קנס]\u0006 הוא, \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003סתם שוורים בחזקת שימור קיימי\u0004 \u0005[עומדים]\u0006 ואין להניח בסתם כי שור ילך ויזיק, \u0003ובדין הוא\u0004 ש\u0003לא לשלם\u0004 \u0005[ישלם]\u0006 המזיק \u0003כלל\u0004 עבור שור תם שלו שהזיק, שהרי לא היה צריך להביא בחשבון שיזיק השור, \u0003ורחמנא הוא דקנסיה, כי היכי דלנטריה לתוריה\u0004 \u0005[והתורה היא שקנסתו, כדי שישמור את שורו]\u0006 מכאן ולהבא, ותשלום זה הוא איפוא קנס ולא ממון. ומעתה מנסים להביא ראיות מן המקורות לכל אחת מן השיטות הללו.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003הניזק והמזיק בתשלומין.\u0004 ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי \u0003פלגא נזקא ממונא\u0004 \u0005[חצי נזק ממון\u0006 הוא\u0005]\u0006 — \u0003היינו\u0004 \u0005[הרי זה]\u0006 מסביר כיצד \u0003שייך ניזק בתשלומין,\u0004 שהרי לשיטה זו מן הדין היה הניזק צריך לקבל את כל הנזק, ואילו בפועל הוא מקבל רק מחצית, ונמצא שגם הניזק משתתף בתשלומין. \u0003אלא למאן דאמר פלגא נזקא קנסא\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר\u0006 כי \u0005חצי נזק קנס\u0006 הוא\u0005]\u0006 ומן הדין לא היה צריך המזיק לשלם לניזק כלל, \u0003השתא דלאו דידיה שקיל\u0004 \u0005[עכשיו\u0006 הרי אפילו את מה \u0005שאינו שלו מקבל\u0006 הניזק\u0005]\u0006 וכי אפשר לומר ש\u0003בתשלומין איתיה\u0004 \u0005[ישנו]?!\u0006","ודוחים: דברי המשנה הללו אינם מתייחסים לחצי נזק, \u0003לא נצרכא\u0004 \u0005[נצרכה]\u0006 פיסקה זו במשנה \u0003אלא לפחת נבילה\u0004 מה שפוחת ערכה של נבלת השור שהומת עד זמן התשלום. ונמצא שאף הניזק משתתף בתשלום, שהרי הוא מפסיד פחת זה מממונו.","ומקשים: \u0003פחת נבילה, הא תנא ליה רישא\u0004 \u0005[הרי שנה אותו\u0006 כבר ב\u0005ראשה\u0006 של המשנה\u0005],\u0006 ששנינו שם: \u0003תשלומי נזק,\u0004 ודייקו בברייתא: \u0003מלמד שהבעלים מטפלין\u0004 (מתעסקים) \u0003בנבילה,\u0004 ופירוש הדברים שם הוא לפחת נבילה!","ומשיבים: \u0003חדא\u0004 \u0005[\u0006במקום \u0005אחד]\u0006 מדובר \u0003ב\u0004שור \u0003תם, וחדא\u0004 \u0005[ו\u0006במקום \u0005אחד]\u0006 מדובר \u0003ב\u0004שור \u0003מועד.\u0004","\u0003וצריכא\u0004 \u0005[ונצרכה]\u0006 הלכה זו להיאמר פעמיים, ומדוע — \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 בשור \u0003תם\u0004 בלבד הייתי אומר: דווקא כאן נוהגת הלכה זו \u0003משום דאכתי\u0004 \u0005[שעדיין]\u0006 \u0003לא אייעד\u0004 \u0005[הועד]\u0006 לכן אין המזיק צריך לשלם את פחת הנבילה, \u0003אבל\u0004 בשור \u0003מועד אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 כך הוא הדין, ויצטרך המזיק לשלמו, על כן השמיע לנו במועד. \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק ב\u0003מועד\u0004 שהבעלים מטפלים בנבילה, הייתי אומר: דווקא כאן \u0003משום דקא משלם כוליה\u0004 \u0005[שהוא משלם\u0006 את הנזק \u0005כולו]\u0006 אין מחייבים אותו לשלם דבר מועט של פחת נבילה, \u0003אבל תם\u0004 שמשלם רק חצי נזק \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 כך הוא הדין, ויצטרך לשלם את פחת הנבילה, על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 להיאמר גם במקרה זה.","מכאן לא הוכחנו איפוא לענין המחלוקת, ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממקום אחר, ששנינו במשנה להלן: \u0003מה בין תם למועד? שהתם משלם חצי נזק\u0004 שהזיק \u0003מגופו\u0004 שגובים את התשלום מגופו של השור המזיק, \u0003ומועד משלם נזק שלם מן העלייה\u0004 כלומר, מהמעולה שבנכסי המזיק.","\u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לומר שחצי נזק הוא קנס, \u0003ליתני נמי הא\u0004 \u0005[שישנה גם כן\u0006 חלוקה \u0005זו]\u0006 ש\u0003תם אינו משלם\u0004 חצי נזק \u0003על פי עצמו\u0004 שיהא דינו ככל הקנסות שאין החייב בהם משלם על פי הודאתו בלבד, ו\u0003מועד משלם על פי עצמו\u0004 ככל המודה בממון שחייב בו!","ומשיבים: אכן, כן הוא באמת הדין, אלא \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003ושייר\u0004 ולא מנה את כל ההבדלים. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 עוד \u0003שייר\u0004 שאתה אומר \u0003דהאי\u0004 \u0005[ש\u0006גם את \u0005זה]\u0006 \u0003שייר?\u0004","ומשיבים: \u0003שייר חצי כופר,\u0004 שהתם אינו משלם אפילו חצי כופר אם הרג אדם, והמועד משלם הכל.","תשובה זו דוחים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום חצי כופר,\u0004 דבר זה \u0003לאו שיורא\u0004 \u0005[לא שיור]\u0006 \u0003הוא,\u0004 כי יכול אתה לומר: \u0003הא מני\u0004 \u0005[\u0006משנתנו \u0005זו\u0006 כשיטת \u0005מי\u0006 היא\u0005]\u0006 — כשיטת \u0003ר' יוסי הגלילי היא,\u0004 ש\u0003אמר: תם\u0004 \u0003משלם חצי כופר,\u0004 ולשיטה זו הרי זה בכלל האמור שתם משלם חצי נזק ומועד נזק שלם. ואם כן, אין להוכיח מכאן למחלוקת האמוראים.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במקור אחר:"],["מי שאמר \u0003\"המית שורי את פלוני\", או\u0004 \u0003\"\u0004המית שורי את \u0003שורו של פלוני\"\u0004 — \u0003הרי זה משלם\u0004 את תשלומי שורו שהזיק \u0003על פי\u0004 הודאת \u0003עצמו.\u0004","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר בכל שור אפילו \u0003ב\u0004שור \u0003תם?\u0004 ואם משלם על פי עצמו — משמע שאין תשלום חצי נזק קנס אלא ממון, שהרי קנס משלמים על פי עדים והמודה בקנס פטור!","ומשיבים: \u0003לא,\u0004 מדובר כאן דווקא \u0003במועד.\u0004 ושואלים: אם כן, \u0003אבל תם מאי\u0004 \u0005[מה\u0006 יהא דינו\u0005]\u0006 — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003אין משלם על פי עצמו? אי הכי\u0004 \u0005[אם כך]\u0006 שיש לחלק בזה, \u0003אדתני סיפא\u0004 \u0005[עד ש\u0006הוא \u0005שונה\u0006 ב\u0005סופה\u0006 של אותה הלכה\u0005]\u0006 שמי שאמר \u0003\"המית שורי את עבדו של פלוני\"\u0004 — \u0003אין משלם על פי עצמו,\u0004 כיון שהתשלום עבור העבד קנס הוא, והמודה בקנס פטור — מדוע הרחיקו לאותה דוגמה? \u0003לפלוג וליתני בדידיה\u0004 \u0005[שיחלק וישנה ב\u0006אותו ענין \u0005עצמו],\u0006 בשור שהרג שור, חלוקה אחרת:","\u0003במה דברים אמורים\u0004 שמשלם על פי עצמו — \u0003במועד, אבל בתם\u0004 — \u0003אינו משלם על פי עצמו.\u0004 ומתוך שלא שנה כך משמע שלדעתו אין חילוק זה קיים, שכן חצי נזק ממון הוא!","ודוחים: אין מקום לשאלה זו משום ש\u0003כולה,\u0004 כל אותה משנה, \u0003במועד קמיירי\u0004 \u0005[\u0006היא \u0005עוסקת]\u0006 ולכן היא מפרטת את חילוקי הדינים שיש במועד, ואינה דנה כלל בשור תם. ואם כן אף מכאן אין להוכיח.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במקור אחר: \u0003זה הכלל, כל המשלם יותר על מה שהזיק\u0004 — \u0003אינו משלם על פי עצמו,\u0004 כי כל תשלום כזה הוא קנס, ומודה בקנס פטור. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 נוכל לדייק כי דווקא נקט \"יותר על מה שהזיק\" ללמדנו: \u0003הא\u0004 \u0005[הרי]\u0006 אם משלם \u0003פחות ממה שהזיק\u0004 — \u0003משלם\u0004 על פי עצמו, שאין זה קנס? ומכאן משמע שתשלום חצי נזק ממון הוא, ולא קנס!","ודוחים: \u0003לא,\u0004 לא כך יש לדייק, אלא כך: \u0003הא\u0004 \u0005[הרי]\u0006 אם משלם בדיוק \u0003כמה שהזיק\u0004 — \u0003משלם\u0004 על פי עצמו, שזהו תשלום ממון.","ותוהים: \u0003אבל פחות\u0004 ממה שהזיק, \u0003מאי\u0004 \u0005[מה\u0006 יהיה דינו\u0005]\u0006 — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 ש\u0003לא משלם\u0004 על פי עצמו? \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אדתני\u0004 \u0005[עד ש\u0006הוא \u0005שונה]:\u0006 \u0003זה הכלל כל המשלם יותר על מה שהזיק\u0004 — \u0003אינו משלם על פי עצמו, ליתני\u0004 \u0005[שישנה]:\u0006 \u0003זה הכלל כל שאינו משלם כמה שהזיק\u0004 — אינו משלם על פי עצמו, ש\u0003משמע פחות ומשמע יותר.\u0004 ואם אינו אומר כך משמע שכוונתו שרק המשלם יותר הרי זה קנס, ואילו המשלם פחות — אינו קנס, ואם כן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא לדעת האומר שחצי נזק קנס הוא!","ואומרים: \u0003והלכתא\u0004 \u0005[וההלכה\u0006 היא\u0005]\u0006 \u0003פלגא נזקא\u0004 \u0005[חצי נזק]\u0006 — \u0003קנסא\u0004 \u0005[קנס\u0006 הוא\u0005].\u0006","ותוהים: \u0003תיובתא והלכתא\u0004 \u0005[\u0006גם \u0005קושיה חמורה\u0006 כנגדו שלא היה לה תירוץ \u0005ו\u0006גם \u0005הלכה\u0006 כמותו\u0005]?!\u0006","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 שיש לקושיה חמורה זו תירוץ; \u0003טעמא מאי הויא תיובתא\u0004 \u0005[מה טעם הריהי קושיה]\u0006 \u0003משום\u0004 ש\u0003לא קתני\u0004 \u0005[שנה]\u0006 \"כל שאינו משלם \u0003כמו שהזיק\u0004 — אינו משלם על פי עצמו\".","אבל יש טעם שלא שנה בלשון זו כאן, שכן \u0003לא פסיקא ליה\u0004 \u0005[פסוקה,\u0006 מוחלטת, \u0005לו],\u0006 ואין כלל זה נכון בכל מקרה. כי \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 מקרה של תשלום \u0003חצי נזק\u0004 שמשלם עבור \u0003צרורות\u0004 שנתזו מרגלי בהמתו והזיקו, \u0003דהלכתא גמירא לה\u0004 \u0005[שהלכה למודה\u0006 במסורת \u0005היא]\u0006 בענין זה \u0003דממונא\u0004 \u0005[שממון]\u0006 \u0003הוא\u0004 ואינו קנס, \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003לא קתני\u0004 \u0005[שנה]\u0006 הלכה זו בלשון \"משלם כמה שהזיק\", אלא שנה לשון \"יותר על מה שהזיק\" שכלל זה הינו מוחלט.","ומעירים: \u0003והשתא דאמרת פלגא נזקא קנסא\u0004 \u0005[ועכשיו שאומר אתה\u0006 ש\u0005חצי נזק קנס\u0006 הוא\u0005],\u0006 על כן \u0003האי כלבא דאכל אימרי\u0004 \u0005[כלב זה שאכל טלאים]\u0006 \u0003ושונרא דאכלה תרנגולא\u0004 \u0005[וחתול שאכל תרנגול]\u0006 — \u0003משונה הוא,\u0004 שכיון שאין דרכם לאכול בעלי חיים גדולים כאלה — אין זה נחשב נזק רגיל של אכילה, כתולדה של אב הנזיקין שן, אלא כעין נזק של קרן, שמשלמים עליו חצי נזק בתם, \u0003ו\u0004לכן \u0003לא מגבינן\u0004 \u0005[אין אנו גובים]\u0006 אותו \u0003בבבל,\u0004 לפי שאין דנים דיני קנסות בבבל.","\u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים דווקא \u0003ב\u0004שאכלו אלה תרנגולים או כבשים \u0003רברבי\u0004 \u0005[גדולים],\u0006 \u0003אבל בזוטרי\u0004 \u0005[בקטנים]\u0006 — \u0003אורחיה\u0004 \u0005[דרכו]\u0006 \u0003הוא\u0004 לטרוף, ואינו משונה, והרי זה ככל נזקי שן שמשלם נזק שלם וגובים אותו אף בבבל, כיון שהוא תשלום ממון.","\u0003ו\u0004אף שאכלו בעלי חיים גדולים, שהוא קנס ואין גובים בבבל — \u0003אי\u0004 \u0005[אם]\u0006 \u0003תפס\u0004 הניזק מנכסיו של המזיק כדי הנזק — \u0003לא מפקינן מיניה\u0004 \u0005[אין אנו מוציאים ממנו],\u0006 שהרי לעצם הענין צודק הוא.","\u0003ו\u0004כן \u0003אי\u0004 \u0005[אם]\u0006 \u0003אמר\u0004 הניזק בבית הדין: \u0003קבעו לי זימנא\u0004 \u0005[זמן]\u0006 \u0003דאזלינא לארעא דישראל\u0004 \u0005[כי הולך אני לארץ ישראל]\u0006 ושם דנים דיני קנסות, ואתבענו שם — \u0003קבעינן ליה\u0004 \u0005[קובעים אנו לו]\u0006 זמן, ויתחייב הנתבע ללכת לשם. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא אזיל\u0004 \u0005[ילך]\u0006 לארץ ישראל — \u0003משמתינן ליה\u0004 \u0005[מנדים אנו אותו]\u0006 על שאיננו מציית לבית הדין.","\u0003ובין כך ובין כך,\u0004 בין שתבעו או שתפס ממנו, ובין שלא עשה כן, \u0003משמתינן ליה\u0004 \u0005[מנדים אנו אותו]\u0006 \u0003עד דמסלק הזיקא\u0004 \u0005[שיסלק את ההיזק\u0006 המזיק שברשותו\u0005].\u0006","ודבר זה נעשה \u0003מ\u0004שום דברי \u0003ר' נתן. דתניא\u0004 [\u0005שכן שנינו\u0006 בברייתא], \u0003ר' נתן אומר: מניין שלא יגדל אדם כלב רע\u0004 הנושך אחרים \u0003בתוך ביתו,\u0004 \u0003ואל יעמיד\u0004 אדם \u0003סולם רעוע בתוך ביתו\u0004 — \u0003תלמוד לומר: \"\u0004ו\u0003לא תשים דמים בביתך\"\u0004 (דברים כב, ח), שאסור לאדם להניח בביתו דבר שיש בו סכנה, וכל מי שיש ברשותו דבר המזיק לאחרים חובתו היא לסלק אותו, ולפיכך אם אינו עושה כן בית הדין כופה אותו על ידי נידוי לעשות כן.","\u0003חמשה תמין וחמשה מועדין\u0004 הם. כיצד?","\u0003הבהמה אינה מועדת לא ליגח\u0004 בקרניה, \u0003ולא ליגוף\u0004 (לדחוף בגופה), \u0003ולא לשוך, ולא לרבוץ\u0004 על חפצים ולשוברם, \u0003ולא לבעוט\u0004 בכוונה בהם. אלה הן חמש פעולות שאם עשתה אותן הבהמה והזיקה — הבעלים משלמים רק מחצית הנזק עד שינהגו בכך שלוש פעמים. ואלה הם חמישה תמים.","חמישה מועדים: \u0003השן מועדת\u0004 לעולם \u0003לאכול את הראוי לה. ו\u0004כן \u0003הרגל מועדת לשבור בדרך הילוכה. ושור המועד\u0004 שכבר העידו בו שנגח כמה פעמים הרי זה מועד. \u0003ו\u0004כן \u0003שור המזיק ברשות הניזק\u0004 דינו כמועד. \u0003והאדם\u0004 שהזיק דינו תמיד כמועד. הרי אלה חמישה מועדים, שדינם אף בפעם הראשונה שהזיקו לשלם את מלוא תשלום הנזק.","ואף \u0003הזאב והארי והדוב והנמר והברדלס והנחש\u0004 שהם חיות פרא \u0003הרי אלו מועדין\u0004 מתחילה, ואם הזיקו לבעלי חיים או לבני אדם אף בפעם הראשונה משלם הכל. \u0003ר' אלעזר אומר: בזמן שהן בני תרבות\u0004 שגידלם אדם בביתו — \u0003אינן מועדין\u0004 מתחילתם, אלא אם כן כבר הועדו שהם מזיקים. \u0003ו\u0004הכל מודים ש\u0003הנחש מועד לעולם.\u0004","ומבררים את משנתנו, \u0003מדקתני\u0004 \u0005[מ\u0006מה \u0005ששנה]\u0006 במשנתנו: \u0003השן מועדת לאכול\u0004 — \u0003מכלל\u0004 הדברים נלמד ש\u0003בחצר הניזק עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שהרי ברשות הרבים פטורים על נזקי שן. \u0003וקתני\u0004 \u0005[ושנה]\u0006 בנזקי קרן: \u0003בהמה אינה מועדת\u0004 ליגח וכיוצא בו, משמע שאף שאין המזיק חייב \u0003לשלם\u0004 את הנזק \u0003כוליה\u0004 \u0005[כולו],\u0006 \u0003אבל חצי נזק משלמת\u0004 כדין התם, ואם כן משנתנו","\u0003מני\u0004 \u0005[\u0006כדעת \u0005מי היא]?\u0006 כדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא, דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]\u0006 \u0003משונה קרן\u0004 שאפילו \u0003בחצר הניזק, חצי נזק הוא\u0004 ש\u0003משלם\u0004 ולא יותר.","ואולם \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005]\u0006 שנאמר בה: \u0003שור המועד ושור המזיק ברשות הניזק, והאדם,\u0004 דינם כמועדים ומשלמים נזק שלם. משמע ששור ברשות הניזק משלם את הכל, \u0003אתאן\u0004 \u0005[הגענו]\u0006 איפוא \u0003ל\u0004דעת \u0003ר' טרפון,\u0004 ש\u0003אמר: משונה קרן בחצר הניזק, נזק שלם הוא\u0004 ש\u0003משלם.\u0004","ואם כן האם נאמר שמשנתנו אינה אחידה, \u0003רישא\u0004 \u0005[תחילתה]\u0006 כדעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003וסיפא\u0004 \u0005[וסופה]\u0006 \u0003ר' טרפון?\u0004","ומשיבים: אף שתמוה הדבר \u0003אין\u0004 \u0005[כן\u0006 הוא\u0005],\u0006 \u0003דהאמר ליה\u0004 \u0005[שהרי אמר לו]\u0006 \u0003שמואל לרב יהודה: שיננא\u0004 \u0005[גדול השיניים],\u0006 \u0003שבוק מתניתין ותא אבתראי\u0004 \u0005[עזוב\u0006 את \u0005משנתנו\u0006 לתרץ אותה כשיטת חכם אחד, \u0005ולך אחרי]\u0006 לפי מה שאני מפרש לך אותה, כי \u0003רישא רבנן וסיפא\u0004 \u0005[תחילתה\u0006 כדעת \u0005חכמים וסופה]\u0006 כדעת \u0003ר' טרפון,\u0004 ומשום כך אין הלכה כמשנה זו בשלמותה. זו היתה שיטת שמואל.","ואילו \u0003ר' אלעזר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אמר:\u0004"],["כל משנתנו זו \u0003כולה\u0004 כדעת \u0003ר' טרפון היא, רישא\u0004 \u0005[תחילת\u0006 המשנה\u0005]\u0006 מדברת \u0003בחצר\u0004 השייכת לשני שותפים, \u0003המיוחדת לפירות\u0004 רק \u0003לאחד מהן\u0004 מן השותפים, שרק הוא רשאי להכניס שם פירות, \u0003ולזה ולזה,\u0004 לשני השותפים, היא מיוחדת \u0003ל\u0004הכניס \u0003שורים\u0004 שלהם, \u0003דלגבי\u0004 \u0005[שאצל]\u0006 נזקי \u0003שן הויא לה\u0004 \u0005[הרי היא]\u0006 נחשבת \u0003חצר הניזק,\u0004 שהרי לענין הפירות החצר מיוחדת רק לו, ולכן המזיק חייב בכל נזקי שן בחצר הניזק. \u0003ולגבי\u0004 \u0005[ואצל]\u0006 נזקי \u0003קרן הויא\u0004 \u0005[הרי היא]\u0006 נחשבת \u0003רשות הרבים,\u0004 ולכן דינו כדין קרן ברשות הרבים (שאף לדעת ר' טרפון יש בה הבדל בין תם למועד).","\u0003אמר רב כהנא: אמריתה לשמעתא קמיה\u0004 \u0005[אמרתי את השמועה,\u0006 הדיון, \u0005הזו לפני]\u0006 \u0003רב זביד מנהרדעא,\u0004 \u0003ואמר לי: מי מצית מוקמת לה\u0004 \u0005[האם יכול אתה להעמיד,\u0006 להסביר, \u0005אותה]\u0006 את המשנה \u0003כולה כ\u0004שיטת \u0003ר' טרפון?\u0004 \u0003הקתני\u0004 \u0005[הרי שנה\u0006 במשנה\u0005]:\u0006 \u0003השן מועדת לאכול את הראוי לה,\u0004 ונדייק: דווקא \u0003ראוי לה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 דינה כמועד לשלם נזק שלם, אבל אכלה את \u0003שאין ראוי לה\u0004 — \u0003לא,\u0004 אינה מועדת, ואינו משלם נזק שלם כמועד, אלא חצי נזק כתם.","\u0003ואי\u0004 \u0005[ואם]\u0006 סבור אתה כי משנתנו כולה \u0003כ\u0004שיטת \u0003ר' טרפון\u0004 היא — קשה הדבר, שכן \u0003האמר\u0004 \u0005[הרי אמר]\u0006 ר' טרפון: \u0003משונה קרן בחצר הניזק\u0004 ש\u0003נזק שלם\u0004 הוא \u0003משלם.\u0004 ולפי שיטה זו, כל מה שמזיקה הבהמה בחצר הניזק גם אם הוא נזק משונה כגון שבהמה אוכלת את שאינו ראוי לה — אף על פי כן חייב לשלם הכל!","\u0003אלא,\u0004 יש לדחות את מה שאמרנו, ואם רצוננו לפרש את המשנה כולה לפי שיטה אחת צריך לומר כי \u0003לעולם\u0004 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא,\u0004 \u0003וחסורי מחסרא והכי קתני\u0004 \u0005[וחסרה\u0006 היא המשנה \u0005וכך יש לשנותה]:\u0006 \u0003חמשה תמים הן, ואם הועדו\u0004 — \u0003חמשתן מועדין\u0004 והם דיני הנגיחה והנגיפה וכו' שהם הקרן ותולדותיה, ואלו חייבים חצי נזק אם הזיקו ברשות הרבים.","עד כאן הלכה אחת, \u0003ו\u0004מכאן מתחילה הלכה נוספת: \u0003שן ורגל מועדין מתחילתן. והיכן העדתן,\u0004 כלומר, באיזה מקום אומרים אנו שהם מועדים ומשלמים נזק שלם — הרי זה \u0003בחצר הניזק.\u0004 שאין להבין את עניין \"ושור המזיק ברשות הניזק\" כענין לעצמו, אלא כהשלמת התיאור של השן והרגל.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על הסבר זה \u0003רבינא: הא קתני לקמן\u0004 \u0005[הרי שנה לפנינו]\u0006 במשנה להלן: \u0003שור המזיק ברשות הניזק כיצד,\u0004 ושם מדובר בקרן ברשות הניזק. ומעתה \u0003אי אמרת בשלמא איירי\u0004 \u0005[נניח אם אתה אומר\u0006 שכבר \u0005מדובר]\u0006 \u0003בה,\u0004 בהלכה זו, בקיצור במשנה שלנו, \u0003משום הכי\u0004 \u0003קתני\u0004 \u0005[כך שנה]\u0006 \u0003\"כיצד\",\u0004 שלשון \"כיצד\" משמעה שבא עתה לבאר דברים שנאמרו קודם בקיצור, ועתה הוא בא לפרטם. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003לא איירי\u0004 \u0005[דובר]\u0006 \u0003בה,\u0004 בהלכה זו, כלל, אם כן \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הלשון \u0003\"כיצד\"?\u0004 הלא לא הזכיר הלכה זו כלל במשנה קודמת!","\u0003אלא,\u0004 יש לדחות את מה שאמרנו, \u0003אמר רבינא: חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 היא המשנה \u0005וכך יש לשנותה]:\u0006 \u0003חמשה תמים הן, ואם הועדו\u0004 — \u0003חמשתן מועדין.\u0004","\u0003ושן ורגל מועדין\u0004 הן \u0003מתחילתן. וזהו שור המועד\u0004 לדעת הכל. \u0003ו\u0004אילו לגבי \u0003שור המזיק ברשות הניזק\u0004 — \u0003מחלוקת ר' טרפון ורבנן\u0004 היא אם נחשב כמועד. \u0003ויש מועדין אחרים כיוצא באלו\u0004 שהם מועדים מתחילתם, והם: \u0003הזאב, והארי, והדוב, והברדלס, והנמר, והנחש,\u0004 שגם בהם יש מחלוקת ר' אלעזר וחכמים.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 כפי שהסביר רבינא את הדברים: \u0003חמשה תמים הן, ואם הועדו\u0004 — \u0003חמשתן מועדין. ושן ורגל מועדין מתחילתן. וזהו שור המועד. ושור המזיק ברשות הניזק\u0004 — \u0003מחלוקת ר' טרפון ורבנן. ויש מועדין אחרים כיוצא באלו: הזאב, והארי,\u0004 ו\u0003הדוב, והנמר, והברדלס, והנחש.\u0004","\u0003איכא דרמו לה מירמא\u0004 \u0005[יש שהיו משליכים זאת,\u0006 מראים סתירה\u0005],\u0006 שהגיעו לאותה מסקנה פרשנית על ידי תירוץ של סתירה שבדברים, ובאופן זה: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 בתחילתה: \u0003חמשה תמים וחמשה מועדים.\u0004 ויש לשאול: \u0003ותו ליכא\u0004 \u0005[ועוד\u0006 מועדים \u0005אין]?\u0006 \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003הזאב,\u0004 ו\u0003הארי, והדוב, והנמר, והברדלס, והנחש\u0004 שהוזכרו במשנתנו!","\u0003ומשני\u0004 \u0005[ומתרץ]\u0006 קושיה זו, \u0003אמר רבינא: חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 היא המשנה \u0005וכך יש לשנותה]:\u0006 \u0003חמשה תמים הן, ואם הועדו\u0004 — \u0003חמשתן מועדין. ושן ורגל מועדין מתחילתן. וזהו שור המועד. ושור המזיק ברשות הניזק\u0004 — \u0003מחלוקת ר' טרפון ורבנן. ויש מועדין אחרים כיוצא באלו: הזאב, והארי, הדוב, והנמר, והברדלס, והנחש.\u0004","\u0003ו\u0004עוד שנינו במשנה שהבהמה \u0003לא\u0004 מועדת \u0003לרבוץ. אמר ר' אלעזר: לא שנו אלא\u0004 לרבוץ על גבי \u0003פכין\u0004 (כלים) \u0003גדולים, אבל\u0004 לרבוץ על \u0003פכין קטנים\u0004 — \u0003אורחיה\u0004 \u0005[דרכו]\u0006 \u0003הוא.\u0004","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם לומר\u0006 שאפשר \u0005לסייע לו]\u0006 מן הברייתא ששנינו בה: \u0003הבהמה מועדת להלך כדרכה ולשבר ולמעך את האדם ואת הבהמה ואת הכלים,\u0004 משמע שהיא מועדת למעך כלים ברביצתה. ואם כן נדייק מכאן שבסוג מיוחד של כלים — כלים קטנים, דרכה בכך.","ומשיבים: זו אינה הוכחה, \u0003דלמא\u0004 \u0005[שמא]\u0006 היתה הכוונה שדרכה לשבר כלים \u0003מן הצד,\u0004 ששוברת כלים הנמצאים בצדה בדרך הליכתה, אבל אין זה מדרכה לרבוץ עליהם.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 דיון זה בגירסה אחרת, \u0003אמר ר' אלעזר: לא תימא\u0004 \u0005[אל תאמר]\u0006 דווקא \u0003פכין גדולים הוא\u0004 שאינה מועדת להם, משום \u0003דלאו אורחיה\u0004 \u0005[שאין דרכו]\u0006 של השור לרבוץ עליהם, \u0003אבל פכין קטנים אורחיה\u0004 \u0005[דרכו]\u0006 \u0003הוא\u0004 ויהא מועד עליהם. \u0003אלא אפילו פכין קטנים נמי לאו אורחיה הוא\u0004 \u0005[גם כן אין זה דרכו].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]:\u0006 והרי שנינו שהבהמה מועדת \u0003למעך את האדם ואת הבהמה ואת הכלים!\u0004","\u0003אמר ר' אלעזר: דלמא\u0004 \u0005[שמא]\u0006 מדובר שם \u0003מן הצד.\u0004","\u0003איכא דרמי לה מירמא\u0004 \u0005[יש שהיו משליכים זאת,\u0006 מראים סתירה\u0005],\u0006 שהגיעו למסקנה להלכה שאמר ר' אלעזר על ידי שהביאו סתירה ותירצוה. \u0003תנן\u0004 \u0005[שנינו]\u0006 במשנתנו שאין הבהמה מועדת \u0003לרבוץ,\u0004 ויש לשאול שכן \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ולמעך את האדם ואת הבהמה ואת הכלים!\u0004 על כך \u0003אמר ר' אלעזר: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 במשנתנו מדובר \u0003בפכין גדולים\u0004 שאין זה דרכה לרבוץ עליה, \u0003כאן\u0004 בברייתא מדובר \u0003בפכין קטנים\u0004 שדרכה לרבוץ עליהם.","במשנתנו שנינו רשימה של חיות שהן מועדות מתחילתן, \u0003הזאב, והארי,\u0004 והדוב, והנמר, והברדלס. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 טיבה\u0005]\u0006 של חיה זו ששמה \u0003ברדלס? אמר רב יהודה:\u0004 זו החיה הקרויה \u0003נפרזא.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003נפרזא\u0004 זו? \u0003אמר רב יוסף: אפא\u0004 \u0005[צבוע].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 והלא מצאנו בברייתא כתוספת לרשימה שבמשנתנו, \u0003ר' מאיר אומר: אף הצבוע, ר' אלעזר אומר: אף הנחש. ואמר רב יוסף: צבוע זו אפא.\u0004 וכיצד הוא אומר כאן שאפא הוא ברדלס!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 גם במשנה וגם בברייתא מדובר על אפא = צבוע, \u0003כאן\u0004 — \u0003בצבוע זכר, כאן\u0004 — \u0003בצבוע נקיבה.\u0004","ומנין לנו שצבוע זכר הוא דבר לעצמו — \u0003דתניא\u0004 \u0005[ששנוייה\u0006 ברייתא\u0005]:\u0006 \u0003צבוע זכר לאחר שבע שנים נעשה עטלף, עטלף לאחר שבע שנים נעשה ערפד, ערפד לאחר שבע שנים נעשה קימוש\u0004 (עשב רע), \u0003קימוש לאחר שבע שנים נעשה חוח\u0004 (קוץ), \u0003חוח לאחר שבע שנים נעשה שד.\u0004 ו\u0003שדרו של אדם\u0004 שמת — \u0003לאחר שבע שנים נעשה נחש.\u0004 ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים באדם ש\u0003לא כרע ב\"מודים\"\u0004 שבתפילת עמידה, שאז הופכת שדרתו להיות נחש. ואם כן, מכיון שיש הבדל בין צבוע זכר לצבוע נקבה אפשר לומר שמשנתנו מדברת בצבוע נקבה, ובא ר' מאיר להוסיף אף את הזכר.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא, \u0003ר' מאיר אומר: אף הצבוע\u0004"],["\u0003ר' אלעזר אומר: אף הנחש,\u0004 ומשמע שגם הוא מסכים ששאר החיות מועדות הן, אלא שמוסיף עליהן את הנחש. ומקשים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו]\u0006 במשנתנו: \u0003ר' אלעזר אומר בזמן שהן בני תרבות אינן מועדים, והנחש מועד לעולם,\u0004 הרי שלדעת ר' אלעזר שאר החיות אינן מועדות!","ומתרצים: \u0003תני\u0004 \u0005[שנה]\u0006 כך, ר' אלעזר אומר: \u0003נחש,\u0004 כלומר, רק הנחש, הוא המועד לעולם.","ובקשר לאמור במשנתנו כי הארי הריהו מועד מתחילתו, \u0003אמר שמואל: ארי\u0004 השייך לאדם מסויים, שהזיק בהיותו \u0003ברשות הרבים,\u0004 אם היה זה באופן ש\u0003דרס ואכל,\u0004 כלומר, שהמם תחילה את הבהמה במכה, ואחר כך נשך ממנה ואכלה — \u0003פטור\u0004 הבעלים. אולם אם תחילה \u0003טרף\u0004 אותה בשיניו והרגה \u0003ו\u0004אחר כך \u0003אכל\u0004 אותה — \u0003חייב.\u0004","ומסבירים: אם \u0003דרס ואכל\u0004 — \u0003פטור, כיון דאורחיה למידרס\u0004 \u0005[שדרכו לדרוס]\u0006 \u0003הוה ליה\u0004 \u0005[הרי הוא]\u0006 \u0003כמו\u0004 בהמה \u0003שאכלה פירות וירקות, דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 נזק \u0003שן ברשות הרבים, ופטור.\u0004 ואילו \u0003טרף\u0004 — \u0003לאו אורחיה\u0004 \u0005[לא דרכו]\u0006 \u0003הוא\u0004 זה, ונזק בלתי רגיל שעושה בעל חיים מדעתו — קרן הוא וברשות הרבים חייב.","ושואלים: \u0003למימרא\u0004 \u0005[האם\u0006 ניתן \u0005לומר]\u0006 מכאן ש\u0003טריפה לאו אורחיה הוא\u0004 \u0005[אין זה דרכו]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"אריה טרף בדי גרותיו\"\u0004 (נחום ב, יג), משמע שארי טורף! ומשיבים: הכוונה היא \u0003בשביל גורותיו,\u0004 ובשבילם הוא הורג תחילה ומביא את הטרף. ומקשים: והלא נאמר \u0003\"ומחנק ללבאתיו\"\u0004 (נחום ב, יג)! ומסבירים: הכוונה היא גם כן \u0003בשביל לבאותיו\u0004 הוא עושה כן, שחונק את טרפו, אבל אין זה דרכו לעצמו. ומקשים: והלא נאמר שם \u0003\"וימלא טרף חריו\"!\u0004 ומשמע שמביא טריפה שהרג עבור עצמו! ומשיבים: הכוונה היא — \u0003בשביל חוריו,\u0004 כלומר, בשביל גוריו הנמצאים שם. ומקשים: והרי נאמר שם \u0003\"ומענתיו טרפה\",\u0004 כלומר, שמביאו למעונו טריפה, שהרגה קודם! ומסבירים: אף כאן כוונת הכתוב היא שטורף רק \u0003בשביל מעונותיו\u0004 להביא לגוריו.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 בקשר לנזקי שן: \u0003וכן חיה שנכנסה לחצר הניזק,\u0004 אם \u0003טרפה בהמה ואכלה בשר\u0004 — \u0003משלם נזק שלם,\u0004 ומשמע אם כן שדרכה לטרוף ולאכול, ולכן חייב בתשלום נזק שלם, ככל שן!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — באופן \u0003שטרפה\u0004 והרגה כדי \u0003להניח\u0004 את הטרף לאחר מכן, ודבר זה הוא דרכה של חיה, ולכן דינו כדין שן. ומקשים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003\"אכלה\" קתני\u0004 \u0005[שנה]\u0006 ולא שהניחה! ומשיבים: \u0003בשנמלכה ואכלה,\u0004 שמתחילה טרפה כדי להניח, ואחר כך נמלכה ואכלה ממנו.","ושואלים: \u0003מנא ידעינן\u0004 \u0005[מניין אנו יודעים]\u0006 שאכן נמלכה החיה ומשום כך אנו מחייבין את בעליה בתשלום הנזק? \u0003ועוד,\u0004 בהלכה זו של \u0003שמואל נמי\u0004 \u0005[גם כן],\u0006 \u0003דלמא הכי\u0004 \u0005[שמא כך]\u0006 \u0003הוא\u0004 שהארי טרף על מנת להניח ונמלך לאחר מכן ואכל, ואם כן מדוע נחייבו ברשות הרבים כדין קרן?","\u0003אמר רב נחמן בר יצחק: לצדדין קתני\u0004 \u0005[שנה].\u0006 כלומר, את הברייתא יש להבין לא כהמשך אחד, אלא כפסק הלכה הנחלק לשני צדדים שונים, וכך יש לשנות: בהמה \u0003שטרפה להניח, או דרסה ואכלה\u0004 — \u0003משלמת נזק שלם.\u0004","\u0003רבינא אמר: כי קא אמר\u0004 \u0005[כאשר אומר]\u0006 \u0003שמואל\u0004 שארי שטרף אין זו דרכו, הרי זה \u0003בארי תרבות\u0004 שגודל בין בני אדם, \u0003ואליבא\u0004 \u0005[ועל פי שיטתו]\u0006 של \u0003ר' אלעזר,\u0004 ש\u0003אמר\u0004 שארי כזה \u0003לאו אורחיה\u0004 \u0005[אין\u0006 זה \u0005דרכו]\u0006 לטרוף.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמדובר בארי תרבות שאינו מועד כלל לתקוף, אם כן \u0003אפילו\u0004 אם \u0003דרסה נמי ליחייב\u0004 \u0005[גם כן שיתחייב]\u0006 עליה ברשות הרבים, שהרי אין זו דרכו, ואין לכך דין שן אלא דין קרן!","\u0003אלא\u0004 הסברו של \u0003רבינא לאו\u0004 \u0005[לא]\u0006 על דברי \u0003שמואל אתמר\u0004 \u0005[נאמר],\u0006 \u0003אלא אמתניתא\u0004 \u0005[על הברייתא].\u0006 וכך יש להבין: \u0003כי תני מתניתא\u0004 \u0005[כאשר שנה\u0006 את ה\u0005ברייתא]\u0006 בחיה שנכנסה לחצר הניזק שמשלם נזק שלם, אין זה משום שדרכה לטרוף, אלא מדובר \u0003בארי תרבות, ואליבא\u0004 \u0005[ולפי שיטתו]\u0006 של \u0003ר' אלעזר\u0004 ש\u0003אמר: לאו אורחיה\u0004 \u0005[אין זה דרכו].\u0006","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאין זה דרכו, רק \u0003חצי נזק בעי לשלומי\u0004 \u0005[יצטרך לשלם]\u0006 כדין קרן, ולא נזק שלם! ומשיבים: מדובר כאן בבעל חיים \u0003דאייעד\u0004 \u0005[שנעשה מועד]\u0006 לכך.","ושואלים: \u0003אי הכי, מאי האי דקתני לה\u0004 \u0005[אם כך, מה זה ששנה אותה,\u0006 את ההלכה הזו\u0005]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003תולדה\u0004 של \u0003שן\u0004 שהיא מועדת לעולם? שהרי לפי הסבר זה \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003תולדה\u0004 של \u0003קרן בעי למיתנייה\u0004 \u0005[צריך\u0006 היה \u0005לשנות אותה]!\u0006 ומעירים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר לפי פירוש זה.","\u0003מה בין\u0004 תשלומי נזקי שור \u0003תם ל\u0004תשלום נזקי \u0003מועד?\u0004","— \u0003אלא שהתם משלם חצי נזק מגופו\u0004 של השור, \u0003ו\u0004אילו ה\u0003מועד משלם נזק שלם מן העלייה,\u0004 מנכסיו של בעל השור.","ומבררים את המשנה: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עלייה\"? אמר ר' אלעזר:\u0004 הכוונה היא \u0003במעולה שבנכסיו,\u0004 כלומר, משלם מן העידית שבנכסיו.","\u0003וכן הוא אומר: \"וישכב יחזקיהו עם אבתיו ויקברהו במעלה קברי בני דויד\"\u0004 (דברי הימים ב לב, לג), \u0003ואמר ר' אלעזר:\u0004 מה פירוש \u0003\"במעלה\"\u0004 — \u0003אצל מעולים שבמשפחה, ומאן נינהו\u0004 \u0005[ומי הם]\u0006 — \u0003דוד ושלמה.\u0004","כיון שהזכרנו דברים אלה ביחס לקברי בני דוד, מביאים פסוק דומה לו, שנאמר בקבורת המלך אסא: \u0003\"ויקברהו בקברתיו אשר כרה לו בעיר דויד וישכיבהו במשכב אשר מלא בשמים וזנים\"\u0004 (דברי הימים ב טז, יד), \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בשמים וזנים\"? ר' אלעזר אמר:\u0004 כוונתו \u0003זיני זיני\u0004 \u0005[מינים מינים],\u0006 סוגים שונים של בשמים, \u0003ר' שמואל בר נחמני אמר:\u0004 כוונתו \u0003בשמים\u0004 כאלה \u0003שכל המריח בהן בא לידי זימה\u0004 (זנות), ולכן נקראים \"זנים\". כיון שהוזכרה מחלוקת בין ר' אלעזר ור' שמואל בר נחמני בפירוש המקראות, מביאים עוד מחלוקת דומה ביניהם.","נאמר בדברי ירמיה הנביא, כאשר ביקש מה' לענוש את רודפיו \u0003\"כי כרו שוחה ללכדני ופחים טמנו לרגלי\"\u0004 (ירמיה יח, כב), ונחלקו מהו עניינה של מלכודת זו, \u0003ר' אלעזר אמר:\u0004 כוונתו \u0003שחשדוהו מזונה, ר' שמואל בר נחמני אמר: שחשדוהו מאשת איש.\u0004","ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 \u0003שחשדוהו מזונה\u0004 — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"כי שוחה עמקה זונה\"\u0004 (משלי כג, כז) שכן \"שוחה\" הוא כינוי לזונה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003שחשדוהו מאשת איש, מאי\u0004 \u0005[מה\u0006 לשון\u0005]\u0006 \u0003\"שוחה\"\u0004 שנאמרה כאן? ומשיבים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003אשת איש\u0004 המזנה עם זר \u0003מי נפקא\u0004 \u0005[האם\u0006 היא \u0005יוצאת]\u0006 \u0003מכלל זונה?\u0004","ושואלים מצד אחר: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 \u0003שחשדוהו מאשת איש\u0004 — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"ואתה ה' ידעת את כל עצתם עלי למות\"\u0004 (ירמיה יח, כג), כלומר, שזממו עליו דברים שחייבים עליהם מיתה, שהחשידוהו שבא על אשת איש, ועונשו של זה מיתה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003שחשדוהו מזונה\u0004 — \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"למות\"?\u0004 הלא על זונה אין חייבים עונש מיתה! ומשיבים: הכוונה היא כפשוטו \u0003שהשליכוהו לבאר טיט.\u0004","\u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 באותו ענין \u0003\"\u0004ו\u0003יהיו מכשלים לפניך בעת אפך עשה בהם\"\u0004 (ירמיה יח, כג)? — כוונתו: \u0003אמר ירמיה לפני הקדוש ברוך הוא: רבונו של עולם, אפילו בשעה שעושין צדקה\u0004 — \u0003הכשילם בבני אדם שאינן מהוגנים\u0004 שהם רמאים ואינם צריכים לצדקה, \u0003כדי שלא יקבלו עליהן שכר\u0004 על הצדקה שעשו, שיתברר שאף מצוות צדקה לא היתה בכך. ושוב לענין קבורתו של המלך חזקיהו.","נאמר בענין זה \u0003\"וכבוד עשו לו במותו\"\u0004 (דברי הימים ב לב, לג) — \u0003מלמד שהושיבו ישיבה על קברו\u0004 שיעסקו שם בתורה לכבודו.","\u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003ר' נתן ורבנן\u0004 \u0005[חכמים]\u0006 כיצד היה הדבר, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 \u0003שלשה\u0004 ימים ישבו,"],["\u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 \u0003שבעה\u0004 ימים ישבו, \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003שלשים\u0004 ימים ישבו ועסקו בתורה לכבודו. ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003\"וכבוד עשו לו במותו\"\u0004 — \u0003זה חזקיה מלך יהודה,\u0004 ומה היה אותו הכבוד? \u0003שיצאו לפניו\u0004 לפני מיטתו בקבורתו \u0003שלשים וששה\u0004 (כמנין \"לו\") \u0003אלף\u0004 אנשים \u0003חלוצי כתף,\u0004 כלומר, שהורידו את הטלית מכתף אחת שלהם לסימן אבילות, שכל אלה היו מלוויו ומכבדיו, אלו \u0003דברי ר' יהודה.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' נחמיה: והלא לפני אחאב עשו כן\u0004 שהוא כבוד שעושים לכל מלך, ואינו מיוחד לאדם גדול וצדיק כחזקיה!","","","\u0003אלא\u0004 כבוד זה היה: \u0003שהניחו ספר תורה על מטתו, ואמרו: קיים זה,\u0004 חזקיה, כל \u0003מה שכתוב\u0004 \u0003בזה\u0004 בספר התורה.","ושואלים: \u0003והאידנא נמי עבדינן הכי\u0004 \u0005[והרי עכשיו גם כן עושים כך]\u0006 לתלמיד חכם שנפטר, ומה ייחודו של הכבוד שעשו לחזקיה! ומשיבים: עכשיו \u0003אפוקי מפקינן, אנוחי לא מנחינן\u0004 \u0005[להוציא\u0006 ספר תורה \u0005מוציאים\u0006 אנו, אבל \u0005להניחו\u0006 על מטתו \u0005אין אנו מניחים].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003אנוחי נמי מנחינן\u0004 \u0005[להניח\u0006 ספר תורה על מטתו \u0005גם כן מניחים אנו]\u0006 כפי שעשו אצל חזקיה, ואולם \u0003\"קיים\u0004 זה מה שכתוב בזה \u0003\"\u0004\u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 עתה.","מסופר, \u0003אמר רבה בר בר חנה: הוה אזילנא בהדיה\u0004 \u0005[הייתי הולך עם]\u0006 \u0003ר' יוחנן למשאל שמעתא\u0004 \u0005[לשאול\u0006 בענין \u0005שמועה,\u0006 סוגיה זו\u0005],\u0006 \u0003כי הוה עייל\u0004 \u0005[כאשר היה נכנס]\u0006 \u0003לבית הכסא והוה בעינא מיניה מלתא\u0004 \u0005[והיינו שואלים אותו דבר]\u0006 כשיצא, \u0003לא פשיט לן\u0004 \u0005[היה פותר לנו]\u0006 השאלה מייד, אלא המתין \u0003עד דמשי ידיה\u0004 \u0005[שהיה רוחץ ידיו]\u0006 \u0003ומנח\u0004 \u0005[ומניח]\u0006 \u0003תפילין ומברך, והדר אמר לן\u0004 \u0005[ואחר כך היה אומר לנו],\u0006 וכך אמר לנו בענין זה: \u0003אפילו \"קיים\" אמרינן\u0004 \u0005[אומרים אנו]\u0006 עכשיו על מיתתו של אדם חשוב, אבל \u0003\"לימד\u0004 זה מה שכתוב בזה \u0003\"\u0004\u0003לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 ודבר זה אמרו רק על חזקיה.","ושואלים: \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 \u0003גדול תלמוד תורה שהתלמוד מביא לידי מעשה,\u0004 משמע שמעשה עדיף מלימוד, ואם אומרים אנו על אדם שקיים תורה — הרי בכלל זה גם שלימד אותה! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — \u0003למיגמר\u0004 \u0005[ללמוד],\u0006 אז גדול המעשה מן הלימוד, \u0003הא\u0004 \u0005[זה]\u0006 — \u0003לאגמורי\u0004 \u0005[ללמד]\u0006 תורה לאחרים — גדולה הוראת התורה יותר מקיומה. כתוב שהובא לענין הלכה בראש הפרק (לעיל בבא קמא ב,ב), מסיימים בו את הפרק בדרכי מוסר. \u0003אמר ר' יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בן יוחאי: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"אשריכם זרעי על כל מים משלחי רגל השור והחמור\"\u0004 (ישעיה לב, כ)? ללמדנו ש\u0003כל העוסק בתורה ובגמילות חסדים זוכה לנחלת שני שבטים.\u0004 ומבארים את הדרשה: מניין שמדובר בעוסקים בתורה ובגמילות חסדים — \u0003שנאמר: \"אשריכם זרעי\", ואין\u0004 הכוונה בלשון \u0003\"זריעה\" אלא\u0004 ל\u0003צדקה, שנאמר: \"זרעו לכם לצדקה (ו)קצרו לפי חסד\"\u0004 (הושע י, יב) \u0003ואין מים אלא תורה, שנאמר: \"הוי כל צמא לכו למים\"\u0004 (ישעיה נה, א), משמע ש\"זורעי על כל מים\" הכוונה לעושי גמילות חסדים ולומדי תורה.","","","\u0003וזוכה לנחלת שני שבטים\u0004 כוונתו: \u0003זוכה לכילה\u0004 (אפריון של כבוד שנושאים אותו בו) — \u0003כיוסף,\u0004 שנאמר בו: \u0003\"בן פרת יוסף\u0004 בן פורת עלי עין \u0003בנות צעדה עלי שור\"\u0004 (בראשית מט, כב), והוא נמשל לשור (\"בכור שורו הדר לו\". דברים לג, יז). \u0003וזוכה ל\u0004נחלה משובחת כ\u0003נחלת יששכר\u0004 שנמשל לחמור, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"יששכר חמר גרם\"\u0004 (בראשית מט, יד) וזה נרמז במלים \"משלחי רגל השור והחמור\".","\u0003אית דאמרי\u0004 \u0005[יש שאומרים]\u0006 כך דורשים את הדברים: \u0003אויביו נופלים לפניו\u0004 — \u0003כיוסף, דכתיב\u0004 \u0005[שנאמר]\u0006 בברכת משה לשבט יוסף: \"בכור שורו הדר לו וקרני ראם קרניו \u0003בהם עמים ינגח יחדו אפסי ארץ\"\u0004 (דברים לג, יז), \u0003וזוכה לבינה\u0004 — \u0003כיששכר\u0004 (שנמשל בברכת יעקב לחמור), שנאמר \u0003\"ומבני יששכר יודעי בינה לעתים לדעת מה יעשה ישראל\"\u0004 (דברי הימים א יב, לג), וזה נרמז במילים \"משלחי רגל השור והחמור\".","","כהמשך לדברי המשנה בפרק הקודם שהרגל מועדת לעולם, מסבירים: \u0003כיצד הרגל מועדת\u0004 — \u0003לשבר\u0004 דברים \u0003בדרך הלוכה.\u0004 ש\u0003הבהמה מועדת להלך כדרכה ולשבר,\u0004 דברים אגב כך.","ואולם אם \u0003היתה\u0004 הבהמה \u0003מבעטת\u0004 תוך כדי הילוך, \u0003או שהיו צרורות\u0004 (אבנים קטנות) \u0003מנתזין\u0004 (קופצים) \u0003מתחת רגליה ו\u0004על ידם כך \u0003שברה את הכלים\u0004 — דבר זה אינו בדיוק הדין של רגל, אלא \u0003משלם\u0004 בעל הבהמה \u0003חצי נזק\u0004 על הנזק שגרמה. אם \u0003דרסה\u0004 הבהמה \u0003על הכלי ושברתו, ונפל\u0004 כלי זה \u0003על כלי\u0004 אחר \u0003ושברו\u0004 — \u0003על הראשון משלם נזק שלם,\u0004 שהוא בכלל נזקי רגל, \u0003ועל האחרון משלם חצי נזק,\u0004 שהרי נשבר מחמת \"צרורות\".","וכן \u0003התרנגולין מועדין להלך כדרכן ולשבר,\u0004 ועל כל מה ששברו בהילוכם משלם הבעלים נזק שלם. ואם \u0003היה דליל\u0004 (חוט העשוי לסימן) \u0003קשור ברגליו\u0004 ונכרך בכלי ושברו, \u0003או שהיה\u0004 התרנגול \u0003מהדס\u0004 (מקפץ) \u0003ומשבר את הכלים,\u0004 כיון שאין אלה כדרכו — \u0003משלם\u0004 עליהם הבעלים רק \u0003חצי נזק.\u0004"],["ומבררים את האמור במשנה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרבא: היינו\u0004 \u0005[זוהי]\u0006 \u0003רגל היינו\u0004 \u0005[זוהי]\u0006 \u0003בהמה,\u0004 ומדוע נשנה במשנה אותו דין פעמיים, גם בלשון רגל (\"הרגל מועדת\" וכו') גם בלשון בהמה (\"הבהמה מועדת\" וכו')? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא בתשובה: \u0003תנא\u0004 \u0005[שנה]\u0006 תחילה \u0003אבות\u0004 נזיקין, את אב הנזיקין של רגל שמפורש בתורה, \u0003וקתני\u0004 \u0005[ושנה]\u0006 אחר כך את ה\u0003תולדות\u0004 שיש בדין זה, שבהמה מועדת לשבר כדרכה לא רק ברגל.","המשיך רבינא והקשה: \u0003אלא מעתה, סיפא\u0004 \u0005[\u0006ב\u0005סוף],\u0006 כלומר, במשנה הבאה, \u0003דקתני\u0004 \u0005[ששנה\u0006 בה\u0005]\u0006 בדומה למשנתנו \u0003\"השן מועדת... הבהמה מועדת\",\u0004 שם \u0003מאי\u0004 \u0005[מה]\u0006 \u0003אבות ומאי\u0004 \u0005[ומה]\u0006 \u0003תולדות איכא\u0004 \u0005[יש\u0006 בדבר\u0005]?\u0006 שהרי שם אינו מונה כל תולדות של שן! \u0003הוה קמהדר ליה בבדיחותא\u0004 \u0005[החזיר לו\u0006 רבא לרבינא \u0005בבדיחות\u0006 הדעת\u0005]\u0006 \u0003ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא שנאי חדא, ואת שני חדא\u0004 \u0005[אני תירצתי\u0006 משנה \u0005אחת, ואתה תרץ\u0006 משנה \u0005אחת\u0006\u0005].\u0006","ושואלים: \u0003ו\u0004באמת \u0003טעמא מאי\u0004 \u0005[מה הטעם]\u0006 באותה משנה לחזרה פעמיים על אותה הלכה? \u0003אמר רב אשי:\u0004 תחילה \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003שן\u0004 שהוא כולל גם \u0003חיה,\u0004 וחזר \u0003וקתני\u0004 \u0005[ושנה]\u0006 \u0003שן\u0004 של \u0003בהמה.\u0004 ומדוע צריך היה לשנות את שניהם, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003\"ושלח את בעירה\"\u0004 (שמות כב, ד) \u0003כתיב\u0004 \u0005[נאמר],\u0006 ו\"בעירה\" משמע בהמה דווקא, ונלמד: \u0003בהמה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003חיה\u0004 — \u0003לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003חיה בכלל בהמה\u0004 היא ואף על שן של כל חיה חייב.","ומקשים: \u0003אי הכי, הא מבעי ליה למיתני ברישא\u0004 \u0005[אם כך,\u0006 דבר \u0005זה היה לו לשנות בתחילה]\u0006 קודם בהמה, ואחר כך שן של חיה שהוא פרט ותוספת לכך! ומשיבים: להיפך, \u0003האי דאתיא ליה מדרשא חביבא ליה\u0004 \u0005[\u0006הלכה \u0005זו שבאה לו מן הדרשה חביבה לו]\u0006 להקדימה, ולכן מזכיר הלכה מחודשת זו לפני שדן בדברים פשוטים.","ושואלים: \u0003אי הכי רישא נמי ליתני ההיא דלא כתיבא ברישא\u0004 \u0005[אם כך,\u0006 ב\u0005תחילה,\u0006 במשנתנו, \u0005גם כן שישנה אותה שאינה כתובה\u0006 במפורש \u0005בתחילה]\u0006 מתוך חביבות! ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בשן, \u0003אידי ואידי\u0004 \u0005[זו וזו],\u0006 שן חיה ושן בהמה, \u0003אבות\u0004 נזיקין \u0003נינהו\u0004 \u0005[הן],\u0006 ולכן \u0003הך דאתיא ליה מדרשא חביבא ליה\u0004 \u0005[זו\u0006 שן החיה \u0005שבאה,\u0006 נלמדת, \u0005לו בדרך דרשה\u0006 \u0005חביבה לו]\u0006 והקדימה. ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 בדין רגל, וכי \u0003שביק\u0004 \u0005[\u0006\u0005יעזוב,\u0006 יניח\u0005]\u0006 מלשנות תחילה \u0003אב\u0004 שהוא רגל, \u0003ותני\u0004 \u0005[וישנה]\u0006 תחילה \u0003תולדה?!\u0004","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 באופן אחר לפרש את סדר הדברים במשנה שלנו: \u0003איידי דסליק\u0004 \u0005[מתוך שעלה,\u0006 יצא\u0005]\u0006 \u0003מרגל\u0004 בסוף הפרק הקודם (\"הרגל מועדת לשבור\"), \u0003פתח ברגל\u0004 במשנתנו זו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בהמה מועדת להלך כדרכה ולשבר, כיצד? בהמה שנכנסה לחצר הניזק והזיקה בגופה\u0004 ב\u0003דרך הלוכה,\u0004 \u0003ו\u0004כן \u0003בשערה\u0004 ב\u0003דרך הלוכה,\u0004 או \u0003באוכף שעליה, ו\u0004כן \u0003בשליף\u0004 (בצרור המשא) \u0003שעליה, ובפרומביא\u0004 (רסן) \u0003שבפיה, ו\u0004כן \u0003בזוג\u0004 (פעמון) \u0003שבצוארה, ו\u0004כן \u0003חמור במשאו\u0004 — \u0003משלם נזק שלם. סומכוס אומר: צרורות\u0004 שהתיזה בהמה והזיקו, \u0003וחזיר שהיה נובר\u0004 (מחטט) \u0003באשפה והזיק\u0004 תוך כדי כך — \u0003משלם נזק שלם.\u0004","תחילה דנים בפרט האחרון, העוסק בחזיר, לגופו, ותוהים: \u0003הזיק פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכן הוא, שמשלם נזק שלם! \u0003אלא אימא\u0004 \u0005[אמור\u0006 ותקן כך\u0005]:\u0006 \u0003התיז\u0004 צרורות \u0003והזיק\u0004 — \u0003משלם נזק שלם.\u0004","ולעצם דברי סומכוס שואלים: \u0003צרורות\u0004 שהזכיר סומכוס \u0003מאן דכר שמיהו\u0004 \u0005[מי הזכיר\u0006 את \u0005שמם],\u0006 כלומר, הרי לא נדונו כלל קודם, ומדוע לפתע מזכירם סומכוס? ומשיבים: \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 היא הברייתא \u0005וכך\u0006 יש \u0005לשנותה]:\u0006 \u0003צרורות\u0004 שנתזו \u0003כי אורחייהו\u0004 \u0005[כדרכם]\u0006 — משלם \u0003חצי נזק, וחזיר שהיה נובר באשפה והתיז והזיק\u0004 — \u0003משלם חצי נזק. סומכוס אומר:\u0004 בין \u0003צרורות, ו\u0004בין \u0003חזיר שהיה נובר באשפה והתיז והזיק\u0004 — \u0003משלם נזק שלם.\u0004 שאינו מקבל את ההלכה בענין צרורות שמשלם רק חצי נזק, וסבור כי כיון שזו היא דרכה של הבהמה — משלם נזק שלם.","וכיוצא בזה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003תרנגולין שהיו מפריחין\u0004 (מתעופפים) \u0003ממקום למקום ושברו כלים בכנפיהן\u0004 — \u0003משלם נזק שלם\u0004 עליהם, והוא נזקי רגל. אם שברו \u0003ברוח שבכנפיהן\u0004 — \u0003משלמין חצי נזק,\u0004 כדין צרורות. \u0003סומכוס אומר:\u0004 אף כאן משלם \u0003נזק שלם. תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 שאף בה נחלקו חכמים וסומכוס במחלוקת כעין זו: \u0003תרנגולין שהיו מהדסין\u0004 (מקפצים) \u0003על גבי עיסה\u0004 של בצק \u0003ו\u0004כן \u0003על גבי פירות, וטינפו\u0004 ברגליהם את המאכל, \u0003או ניקרו\u0004 בו — \u0003משלם נזק שלם\u0004 על מה שעשו. \u0003העלו עפר או צרורות\u0004 תוך כדי קפיצתם והזיקו — \u0003משלמין חצי נזק, סומכוס אומר: נזק שלם.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003תרנגול שהיה מפריח ממקום למקום, ויצתה רוח מתחת כנפיו ושיברה את הכלים\u0004 — \u0003משלם חצי נזק.\u0004 ומעירים: \u0003סתמא כרבנן\u0004 \u0005[סתם\u0006 ברייתא זו \u0005כ\u0006שיטת \u0005חכמים]\u0006 החולקים על סומכוס, שנזקי רוח של כנפים הריהם כצרורות, ומשלם חצי נזק.","בבירור השיטות \u0003אמר רבא: בשלמא\u0004 \u0005[נניח]\u0006 \u0003סומכוס,\u0004 שיטתו מובנת, כי \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 ש\u0003כחו כגופו דמי\u0004 \u0005[נחשב]\u0006 ואינו מחלק בין מה שמזיק בעל חיים בגופו ובין נזק שנגרם כתוצאה מכוחו בלבד, ועל שניהם משלם נזק שלם. \u0003אלא\u0004 על שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 יש לתהות: \u0003אי\u0004 \u0005[אם]\u0006 סבורים הם שכוחו \u0003כגופו דמי\u0004 \u0005[נחשב]\u0006 — \u0003כוליה\u0004 \u0005[כל]\u0006 ה\u0003נזק\u0004 הוא \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003לשלם\u0004 כסומכוס, \u0003ואי\u0004 \u0005[ואם]\u0006 כוחו \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כגופו דמי\u0004 \u0005[נחשב]\u0006 אלא כדבר חיצוני שאינו קשור למזיק, אם כן \u0003חצי נזק נמי\u0004 \u0005[גם כן]\u0006 \u0003לא לשלם!\u0004","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר רבא\u0004 וסיכם: \u0003לעולם\u0004 כוחו \u0003כגופו דמי\u0004 \u0005[נחשב],\u0006 \u0003ו\u0004זה שמשלם רק \u0003חצי נזק\u0004 ב\u0003צרורות\u0004 ולא נזק שלם — \u0003הלכתא גמירי לה\u0004 \u0005[הלכה\u0006 מיוחדת לעצמה \u0005לומדים אותה]\u0006 שהיא יוצאת מן הכלל, שאינו משלם על כך נזק שלם.","ועוד בענין זה \u0003אמר רבא\u0004 כלל: \u0003כל שבזב טמא,\u0004 כלומר, כל סוג של מגע והזזה, שאם הזב נוגע בדבר או מזיז אותו הריהו מטמא אותו — כיוצא בזה \u0003ב\u0004פעולה שגרמה \u0003נזקין משלם\u0004 עליו \u0003נזק שלם, כל שבזב טהור\u0004 שאין זה נחשב למגע ישיר — \u0003בנזקין משלם חצי נזק.\u0004","ושואלים: \u0003ורבא,\u0004 וכי דין \u0003צרורות אתא לאשמועינן\u0004 \u0005[בא להשמיענו]?!\u0006 שלכאורה כלל זה שקבע רבא משמעו בפועל שעל דברים שגרם בעל חיים בגופו — משלם נזק שלם, ועל מה שנעשה מכוחו בלבד (\"צרורות\") משלם חצי נזק, והרי זה דין צרורות הידוע. ומשיבים: \u0003לא, רבא\u0004 בענין \u0003עגלה מושכת בקרון קא משמע לן\u0004 \u0005[השמיע לנו],\u0006 שכיון שמזיזה אותו בעצמה נחשב הדבר כמו מגע ישיר בגופה, וכשם שהסטה כזו מטמאה בזב, שאם ישב הזב בקרון ועלה הקרון על כלים, הריהם טמאים משום מדרס הזב — כך היא נחשבת לפעולה ישירה לענין נזיקין, ולא כדין צרורות, ואם עלה הקרון על גבי כלים ושברם הרי זה כנזק שנעשה בגופה ולא כצרורות.","ומעירים: \u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא: בהמה מועדת לשבר בדרך הלוכה. כיצד? בהמה שנכנסה לחצר הניזק והזיקה בגופה דרך הלוכה, ובשערה דרך הלוכה, באוכף שעליה, ובשליף שעליה, ובפרומביא שבפיה, ובזוג שבצוארה, וחמור במשאו ועגלה מושכת בקרון\u0004 — הרי זה \u0003משלם נזק שלם.\u0004 הרי מפורש שבעל החיים המזיז בעצמו את העגלה נחשב כעושה דברים בגופו, ומשלם נזק שלם ולא חצי נזק.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003תרנגולים שהיו מחטטין\u0004 ומנקרים \u0003בחבל דלי, ונפסק\u0004 (נקרע) על ידי כך \u0003החבל, ונשבר הדלי\u0004 — \u0003משלמין נזק שלם.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא\u0004 שאלה זו: בהמה ש\u0003דרסה על כלי ולא שברתו, ונתגלגל\u0004 הכלי \u0003למקום אחר ונשבר, מהו\u0004 הדין? האם \u0003בתר מעיקרא אזלינא וגופיה\u0004 \u0005[אחר ההתחלה אנו הולכים\u0006 בקביעת חיוב התשלומים \u0005וגופו]\u0006 \u0003הוא,\u0004 שכיון שהבהמה עצמה היא שדחפה את הכלי, ויהא דינו כשאר נזקי רגל, וישלם נזק שלם, \u0003או דלמא בתר תבר מנא אזלינא\u0004 \u0005[שמא אחר שבירת הכלי הולכים אנו],\u0006 \u0003וצרורות נינהו\u0004 \u0005[הם],\u0006 שהרי השבירה לא נעשתה במישרין על ידי הבהמה גופה אלא מכוחה, וישלם רק חצי נזק?","ומציעים: \u0003תפשוט ליה\u0004 \u0005[תפתור לו]\u0006 את השאלה \u0003מ\u0004מה שאמר \u0003רבה\u0004 במקום אחר. ש\u0003אמר רבה: זרק כלי מראש הגג ובא אחר ושברו במקל\u0004 תוך כדי נפילתו — \u0003פטור\u0004 אותו אדם ששבר, משום \u0003דאמרינן ליה\u0004 \u0005[שאומרים אנו לו]:\u0006 \u0003מנא תבירא תבר\u0004 \u0005[כלי שבור שבר],\u0006 שכיון שהכלי היה עשוי לשבירה משעת הפלתו, לכן מה ששברו אותו באמצע נפילתו — אינו מעלה ואינו מוריד. משמע שהגורם הראשון שהשליך את הכלי הוא האחראי לשבירתו. ואם כן לענין בהמה שדחפה כלי נאמר גם כן שאחר ההתחלה אנו הולכים. ודוחים: \u0003לרבה פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 פתרון השאלה, ואילו \u0003לרבא מבעיא ליה\u0004 \u0005[היה מסופק בעיניו],\u0006 ואין מוכיחים מדברי אמורא אחד על שיטתו של אמורא אחר.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בברייתא: \u0003הידוס\u0004 (קיפוץ) של תרנגולים \u0003אינו מועד, ויש אומרים: הרי זה מועד.\u0004","ושואלים: \u0003הידוס סלקא דעתך\u0004 \u0005[יעלה על דעתך]?!\u0006 כיצד אפשר להגיד שהידוס לא ייחשב כמועד? הרי זה דרכם של התרנגולים! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003הידוס והתיז, ובהא קמפלגי\u0004 \u0005[וב\u0006עיקרון \u0005זה נחלקו]:\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 \"יש אומרים\", \u0005סבור]:\u0006 \u0003בתר מעיקרא אזלינן\u0004 \u0005[אחר ההתחלה אנו הולכים],\u0006 וכיון שדרכו של תרנגול להדס, אף הנזקים שגרם בהתזה באחריותו הם. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 שאמר שאינו מועד, \u0005סבור]:\u0006 \u0003בתר תבר מנא אזלינן\u0004 \u0005[אחר שבירת הכלי אנו הולכים]\u0006 וכיון ששבירת הכלי נעשתה על ידי גורם נוסף אינו חייב על כך?","ודוחים: \u0003לא,\u0004 אפשר את לפרש המחלוקת שבברייתא בדרך אחרת."],["כאן המחלוקת היא \u0003ב\u0004מקרה ש\u0003התיז צרורות\u0004 אגב הידוס, \u0003ובפלוגתא\u0004 \u0005[ובמחלוקת]\u0006 של \u0003סומכוס ורבנן\u0004 \u0005[וחכמים]\u0006 שהוזכרה מקודם \u0003קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005]\u0006 אם בכלל דנים כוחו כגופו או לא.","ומציעים פתרון נוסף, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003תרנגולין שהיו מחטטין בחבל דלי, ונפסק החבל ונשבר הדלי\u0004 — בעליהם \u0003משלמין נזק שלם. שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003בתר מעיקרא אזלינן\u0004 \u0005[אחר ההתחלה אנו הולכים]\u0006 לענין חיוב תשלומים! ודוחים: אין להוכיח מכאן, \u0003תרגמא\u0004 \u0005[תרגם],\u0006 הסבר את הענין כמתייחס אל ה\u0003חבל,\u0004 שעל החבל משלמין נזק שלם, ולא על הדלי, שנזקו הוא בכלל צרורות.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 אכילת \u0003חבל\u0004 דבר \u0003משונה הוא\u0004 שאינו דרכו של תרנגול, ואין דינו כשן אלא כקרן, ומדוע שישלם נזק שלם? ומשיבים: כאן מדובר בחבל שהיה \u0003מאוס\u0004 (מלוכלך) \u0003בלישה\u0004 של בצק, ודרך התרנגול לנקר בו. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"נשבר דלי\" קתני\u0004 \u0005[שנה]\u0006 משמע שביחס לדלי המחלוקת! \u0003אלא,\u0004 יש לומר כי ברייתא זו כשיטת \u0003סומכוס היא דאמר\u0004 \u0005[שאומר]\u0006 כי \u0003צרורות\u0004 — \u0003נזק שלם משלם.\u0004","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 כדעת \u0003סומכוס,\u0004 \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף\u0006 הברייתא\u0005]\u0006 שנאמר שם: \u0003ניתז ממנו שבר ונפל על כלי אחר ושברה, על הראשון\u0004 — \u0003משלם נזק שלם, ועל האחרון\u0004 — \u0003משלם חצי נזק. ואי\u0004 \u0005[ואם]\u0006 לשיטת \u0003סומכוס\u0004 היא הברייתא, \u0003מי אית ליה\u0004 \u0005[האם יש לו,\u0006 האם הוא סובר\u0005]\u0006 כלל את דין תשלום \u0003חצי נזק\u0004 על נזקי צרורות של רגל?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003שאני ליה\u0004 \u0005[שונה לו]\u0006 \u0003לסומכוס\u0004 \u0003בין נזק\u0004 שגרם \u0003כחו,\u0004 שמכוחו, באופן ישיר, הועף דבר והזיק, \u0003ל\u0004בין נזק שנגרם על ידי \u0003כח כחו,\u0004 והשבר שנפל מן הדלי הוא כח כוחו, ובזה מודה סומכוס שמשלם רק חצי נזק — \u0003ואלא הא דבעי\u0004 \u0005[\u0006שאלה \u0005זו ששאל]\u0006 \u0003רב אשי: כח כחו לסומכוס,\u0004 האם \u0003ככחו דמי\u0004 \u0005[נחשב],\u0006 \u0003או לאו\u0004 \u0005[לא]\u0006 \u0003ככחו דמי\u0004 \u0005[נחשב]?\u0006","\u0003תפשוט ליה\u0004 \u0005[תפתור לו]\u0006 מכאן \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003ככחו דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 וכיון שלא פתר רב אשי שאלה זו, משמע שאין לה פתרון!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא\u0004 ברייתא זו, \u0003ו\u0004אם כן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003בתר מעיקרא אזלינן\u0004 \u0005[אחר\u0006 הפעולה של \u0005ההתחלה אנו הולכים]\u0006 ומשום כך כל מה שנעשה מכוחו של בעל החיים המזיק כדרכו — משלם עליו, ולכן משלם גם עבור הדלי נזק שלם!","\u0003אמר רב ביבי בר אביי:\u0004 אפשר לדחות ולומר שמדובר במקרה \u0003דקאזיל מיניה מיניה\u0004 \u0005[שהולך ממנו\u0006 ו\u0005ממנו]\u0006 כלומר, שהתרנגול היה מגלגל את הדלי, ובתוך כך נשבר, ולכן חייב עליו. ואין לדעת מכאן מה יהא הדין כאשר לאחר שיתגלגל מכוחו יישבר. ואם כן נשארה השאלה פתוחה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא\u0004 שאלה זו: \u0003חצי נזק צרורות\u0004 האם \u0003מגופו\u0004 של המזיק \u0003משלם\u0004 כדרך שמשלם חצי נזק בנזקי קרן של שור תם, \u0003או מעלייה משלם\u0004 כדרך שמשלם בשאר נזקים? וצדדי השאלה: \u0003מגופו משלם\u0004 שכן \u0003לא אשכחן\u0004 \u0005[מצאנו]\u0006 \u0003חצי נזק\u0004 ש\u0003משלם מעלייה, או דלמא\u0004 \u0005[שמא]\u0006 \u0003מעלייה משלם\u0004 שכן \u0003לא אשכחן\u0004 \u0005[מצאנו]\u0006 מזיק \u0003כאורחיה\u0004 \u0005[כדרכו]\u0006 ש\u0003משלם מגופיה\u0004 \u0005[מגופו]?\u0006","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה ששנינו בברייתא: \u0003הידוס\u0004 (קיפוץ) \u0003אינו מועד, ויש אומרים: הרי זה מועד.\u0004 ומתחילה יש לתקן את הלשון: \u0003הידוס סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר שנחלקו בו? הרי ודאי הוא מועד ככל נזקי רגל, שהרי זו דרכו! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא \u0003הידוס והתיז\u0004 צרורות,","\u0003ובהא קמיפלגי\u0004 \u0005[וב\u0006נושא \u0005זה נחלקו]:\u0006 \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003אינו מועד קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 כי \u0003מגופו משלם, ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003מועד\u0004 — \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 כי \u0003מעלייה משלם,\u0004 ונמצא שמחלוקת תנאים היא מהיכן משלם חצי נזק צרורות.","ודוחים: \u0003לא,\u0004 אפשר לומר כי \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003סומכוס ורבנן קמיפלגי\u0004 \u0005[וחכמים חלוקים\u0006 הם\u0005]\u0006 אם כוחו כגופו או לא.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון ממה ששנינו במקור אחר: \u0003הכלב שנטל חררה\u0004 (עוגה הנאפית על גחלים) ואגב כך נטל עימו גחלת \u0003והלך לגדיש\u0004 לאוכלה, \u0003ואכל\u0004 את \u0003החררה\u0004 \u0003והדליק את הגדיש, על החררה\u0004 שאכל — \u0003משלם נזק שלם\u0004 כדין שן, \u0003ועל הגדיש\u0004 שנשרף — \u0003משלם חצי נזק,\u0004 ור' אלעזר אומר שאף על הגדיש שנשרף משלם נזק שלם.","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר שלדעת התנא קמא משלם חצי נזק על הגדיש, \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 שנזק זה \u0003הויא להו\u0004 \u0005[הריהו\u0006 נחשב\u0005]\u0006 \u0003צרורות?\u0004 שהגחלת נפלה מפיו וגרמה לנזק, \u0003ותני עלה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005עליה]:\u0006 שמה שאמרו ש\u0003משלם חצי נזק\u0004 — הכוונה היא \u0003מגופו,\u0004 נמצא שתשלום חצי נזק צרורות הוא מגופו!","ודוחים: \u0003ותסברא\u0004 \u0005[וכי סבור אתה]\u0006 שאפשר לפרש כך? שהרי לפי זה סבור ר' אלעזר שמשלם גם נזק שלם מגופו, וכי \u0003לר' אלעזר נזק שלם מגופיה מי אשכחן\u0004 \u0005[האם מצאנו]?\u0006","\u0003אלא\u0004 מדובר \u0003כגון דשני בהא\u0004 \u0005[ששינה בזו]\u0006 \u0003בגחלת,\u0004 שהכלב עצמו השליך אותה על הגדיש, \u0003ור' אלעזר סבר לה\u0004 \u0005[סבור]\u0006 \u0003כר' טרפון\u0004 ש\u0003אמר: משונה קרן בחצר הניזק,\u0004 ש\u0003נזק שלם משלם,\u0004 שכל דבר שגורם נזק באופן משונה שלא כדרכו, אם היה זה בחצר הניזק — משלם נזק שלם, ומגופו.","ואת ההשוואה הזו דוחים: \u0003ולא היא,\u0004 אין הדבר כך, שכן \u0003מאי טעמא מוקמת לה\u0004 \u0005[מה טעם מעמיד אתה את\u0006 הברייתא ה\u0005זו]\u0006 \u0003כר' טרפון\u0004 — \u0003משום נזק שלם\u0004 שאמרנו שמשלם מגופו לדעת ר' אלעזר.","ואולם אפשר להסביר הלכה זו באופן אחר, כי \u0003ר' אלעזר סבר כסומכוס\u0004 ש\u0003אמר: צרורות\u0004 — \u0003נזק שלם משלם, וסבר לה\u0004 \u0005[וסבור]\u0006 מצד אחר \u0003כר' יהודה\u0004 ש\u0003אמר\u0004 שגם בשור מועד \u0003צד תמות במקומה עומדת,\u0004 שחצי נזק שהיה חייב כשור תם נשאר גם כשנהיה שור מועד, ומשלם חצי נזק מגופו (כתם) וחצי אחר מנכסי הבעלים כמועד. \u0003וכי קתני\u0004 \u0005[וכאשר שנינו]\u0006 שמשלם \u0003מגופו\u0004 — הרי זה מתייחס רק \u0003אצד\u0004 \u0005[על צד]\u0006 \u0003תמות,\u0004 אף שהוא משלם נזק שלם על צרורות, כמועד.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב סמא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אשי לרבינא: אימור דשמעת ליה\u0004 \u0005[אמור ששמעת לו]\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה,\u0004 שצד תמות עומד במקומו, \u0003ב\u0004נזקי קרן, שמתחילה היה \u0003תם ונעשה\u0004 לאחר מכן \u0003מועד,\u0004 ואולם \u0003ב\u0004נזקי צרורות שהם נזקי רגל, ולגביהם הוא \u0003מועד מתחילתו\u0004"],["\u0003מי\u0004 \u0005[האם]\u0006 \u0003שמעת ליה\u0004 \u0005[אותו]\u0006 שיחלק בדבר? והרי בצרורות אין תמות כלל!","\u0003אלא\u0004 כך יש לומר: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' אלעזר\u0004 שמשלם \u0003נזק שלם\u0004 בצרורות, מדובר \u0003כגון דאייעד\u0004 \u0005[שנעשה מועד]\u0006 בדבר, \u0003ובהא קמיפלגי\u0004 \u0005[וב\u0006נושא \u0005זה נחלקו];\u0006 \u0003מר סבר\u0004 \u0005[חכם\u0006 \u0005זה,\u0006 ר' אלעזר, \u0005סבור]:\u0006 \u0003יש העדאה לצרורות,\u0004 שאם העידו לפני בית דין שדרכו של אותו בעל חיים להתיז צרורות, הרי הוא נעשה מועד לכך, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים החולקים עליו, \u0005סבור]\u0006 כי \u0003אין העדאה לצרורות,\u0004 ואפילו העידו שעשה כן כמה פעמים עדיין אינו נקרא מועד לנזק זה, לשלם נזק שלם. ומכל מקום נלמד מכאן כי תשלום צרורות משתלם מגופו.","ושואלים: אם כן, \u0003אלא הא דבעי\u0004 \u0005[זו ששאל]\u0006 \u0003רבא:\u0004 האם \u0003יש העדאה לצרורות או אין העדאה לצרורות,\u0004 תיפתר מכאן בעייתו, ובאופן זה: \u0003אי לרבנן\u0004 \u0005[אם ל\u0006שיטת \u0005חכמים],\u0006 \u0003אין העדאה לצרורות,\u0004 שהם מחייבים רק חצי נזק, \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004דעת \u0003ר' אלעזר\u0004 — \u0003יש העדאה לצרורות\u0004 ונפתרה איפוא הבעיה לגמרי!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רבא:\u0004 אין מכאן פתרון לשאלתי, שכן \u0003כי מיבעיא\u0004 \u0005[כאשר נסתפק]\u0006 \u0003לי לדידי\u0004 \u0005[עצמי]\u0006 הדבר, הרי זה דווקא \u0003אליבא דרבנן דפליגי עליה\u0004 \u0005[לפי שיטת חכמים החולקים עליו]\u0006 על \u0003סומכוס,\u0004 וסבורים שמשלם על צרורות חצי נזק, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בברייתא זו — \u0003בין לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 שבברייתא, \u0003בין ל\u0004דעת \u0003ר' אלעזר,\u0004 שניהם \u0003כסומכוס סבירא להו\u0004 \u0005[סבורים הם]\u0006 ש\u0003אמר\u0004 כי על \u0003צרורות\u0004 — \u0003נזק שלם משלם. ו\u0004אם תשאל:","\u0003טעמא מאי אמור רבנן\u0004 \u0005[מה טעם אמרו חכמים]\u0006 שעל צרורות משלם \u0003חצי נזק\u0004 — משום שמדובר במקרה \u0003דשני\u0004 \u0005[ששינה]\u0006 בדבר \u0003ו\u0004עדיין \u0003לא אייעד\u0004 \u0005[נעשה מועד\u0006 בו\u0005],\u0006 \u0003ו\u0004בברייתא זו \u0003בפלוגתא\u0004 \u0005[במחלוקתם]\u0006 של \u0003ר' טרפון ורבנן קמיפלגי\u0004 \u0005[וחכמים חלוקים\u0006 הם\u0005],\u0006 שלדעת ר' טרפון משלם נזק שלם על כל נזק שהזיק בחצר הניזק, ואף נזק משונה כקרן, וחכמים חולקים.","ודוחים: האם אפשר להעמיד את הדברים כדברי ר' טרפון? \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003שמעת ליה\u0004 \u0005[לו]\u0006 את \u0003ר' טרפון\u0004 שאומר שמשלם ברשות הניזק \u0003נזק שלם,\u0004 ואולם לשלם נזק שלם \u0003מגופו מי\u0004 \u0005[האם]\u0006 \u0003שמעת\u0004 אותו שהוא סבור כן?","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 ר' טרפון סבור שמשלם מגופו, כי \u0003מהיכא מייתי לה\u0004 \u0005[מהיכן מביא,\u0006 לומד הוא \u0005אותה\u0006 הלכה\u0005]\u0006 של קרן ברשות הניזק שמשלם נזק שלם — בקל וחומר \u0003מקרן מרשות הרבים,\u0004 ואולם","\u0003דיו לבא מן הדין להיות כנדון,\u0004 שאי אפשר להחמיר בדבר הנלמד מקל וחומר יותר מן הדבר שממנו למדים, וכיון שעל נזקי קרן ברשות הרבים משלם מגופו, אף בחצר הניזק מגופו משלם.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' טרפון לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 שיטה זו במדרש ההלכה האומרת כי \u0003\"דיו\u0004 לבא מן הדין להיות כנדון\u0003\",\u0004 שאם כן צריך היה לשלם רק חצי נזק!","ומשיבים: \u0003כי לית ליה\u0004 \u0005[כאשר אין לו]\u0006 שיטה זו של \u0003\"דיו\"\u0004 הרי זה \u0003היכא\u0004 \u0005[במקום]\u0006 שעל ידי כך \u0003מפריך\u0004 \u0005[נשבר]\u0006 ה\u0003קל וחומר,\u0004 שאם אני מקבל את ההגבלה של \"דיו\" שוב לא יהיה כאן קל וחומר כלל, ואולם \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003לא מפריך\u0004 \u0005[נשבר]\u0006 ה\u0003קל וחומר\u0004 — \u0003אית ליה\u0004 \u0005[יש\u0006 גם \u0005לו\u0006 לשיטתו\u0005]\u0006 דין \u0003\"דיו\",\u0004 ולכן כאן, שמן הקל וחומר למדים שמשלם נזק שלם ברשות הניזק, יש לומר שיועיל ה\"דיו\" לשלם מגופו.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של אותה בעיה שכבר הוזכרה, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 \u0003יש העדאה לצרורות\u0004 לשלם נזק שלם לאחר שהועד שלוש פעמים, \u0003או אין העדאה לצרורות.\u0004 וצדדי השאלה: האם את נזק הצרורות \u0003לקרן מדמינן ליה\u0004 \u0005[מדמים אנו אותו]\u0006 וכמו בקרן אף בצרורות יש הבדל בין תם למועד, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003תולדה\u0004 של \u0003רגל הוא\u0004 ולכן בצרורות הוא מועד מתחילתו כמו ברגל?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו מממה ששנינו בברייתא: נזק שנגרם על ידי \u0003הידוס\u0004 (קיפוץ) של תרנגול \u0003אינו מועד. ויש אומרים: הרי זה מועד.\u0004 ותחילה יש לתקן לשון הברייתא, וכי במקרה של סתם \u0003הידוס סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 שיאמרו שאינו מועד ככל נזקי רגל? \u0003אלא\u0004 הכוונה היא \u0003הידוס והתיז,\u0004 כלומר, דין צרורות,","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003כגון דעבד תלתא זימני\u0004 \u0005[שעשה\u0006 כך \u0005שלוש פעמים]\u0006 שהיה מקפץ ומתיז צרורות ומזיק, \u0003ובהא קמיפלגי\u0004 \u0005[וב\u0006בעיה \u0005זו נחלקו]:\u0006 \u0003מר\u0004 \u0005[חכם זה],\u0006 הסבור שהידוס הוא מועד לאחר שעשה כן שלוש פעמים, \u0003סבר\u0004 \u0005[סבור]\u0006 כי \u0003יש העדאה\u0004 לצרורות. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 שאמר שאינו מועד, \u0005סבור]\u0006 כי \u0003אין העדאה\u0004 לצרורות לשלם נזק שלם אחר שלוש פעמים, שהריהו מועד מתחילתו? ואם כן, נמצא שבשאלת רבא נחלקו בברייתא. ודוחים את הפתרון: \u0003לא,\u0004 אפשר לפרש שכאן מדובר \u0003בחד זימנא\u0004 \u0005[בפעם אחת]\u0006 בלבד, \u0003ובפלוגתא\u0004 \u0005[ובמחלוקת]\u0006 של \u0003סומכוס ורבנן\u0004 \u0005[וחכמים]\u0006 לגבי נזק צרורות עצמו, אם משלם מחצית או הכל, \u0003קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005]\u0006 בברייתא זו גם כן.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת משאלה שנחלקו בה אמוראים: \u0003בהמה שהטילה גללים לעיסה,\u0004 וקילקלה את העיסה בכך, \u0003רב יהודה אומר: משלם\u0004 על כך \u0003נזק שלם, ור' אלעזר אומר: חצי נזק. מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003כגון דעבד תלתא זימני\u0004 \u0005[שעשתה\u0006 כך \u0005שלוש פעמים]\u0006 והיא כמועדת בדבר, \u0003ו\u0004אם כן \u0003בהא קמיפלגי\u0004 \u0005[ב\u0006נושא \u0005זה חלוקים\u0006 הם\u0005]:\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רב יהודה, \u0005סבור]\u0006 ש\u0003יש העדאה\u0004 לצרורות, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' אלעזר, \u0005סבור]\u0006 ש\u0003אין העדאה\u0004 לצרורות?","ודוחים: \u0003לא,\u0004 אפשר לפרש שמדובר \u0003ב\u0004מקרה שעשתה כן \u0003חד זימנא\u0004 \u0005[בפעם אחת]\u0006 \u0003ובפלוגתא\u0004 \u0005[ובמחלוקת]\u0006 של \u0003סומכוס ורבנן קמיפלגי\u0004 \u0005[וחכמים חלוקים\u0006 הם\u0005]\u0006 בענין תשלום נזק צרורות אם הוא נזק שלם או חצי נזק. ותוהים: \u0003והא\u0004 \u0005[והרי]\u0006 גרימת נזק בדרך זו נזק \u0003משונה\u0004 \u0003הוא,\u0004 וכל נזק משונה הוא בגדר קרן, ואין עליו תשלום נזק שלם! ומשיבים: מדובר במקרה \u0003דדחיק ליה עלמא\u0004 \u0005[שהיה צפוף לה המקום]\u0006 ולא יכלה להטיל גללים אלא באותו מקום, והרי זה כדרכה.","ושואלים: אם במחלוקת תנאים נחלקו, מדוע לא נחלקו בכך במפורש? \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 \u0003רב יהודה\u0004 רק: \u0003הלכה כסומכוס, ולימא\u0004 \u0005[ושיאמר]\u0006 \u0003ר' אלעזר: הלכה כרבנן\u0004 \u0005[כחכמים],\u0006 ולא היו צריכים להביא מקרה פרטי זה של הטלת גללים! ומשיבים: ענין \u0003גללים אצטריכא ליה\u0004 \u0005[הוצרך להם],\u0006 לומר, כי יש בכך חידוש: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003הואיל ובתר גופיה גרירין\u0004 \u0005[ואחר גופה\u0006 הם \u0005נגררים]\u0006 — הרי \u0003כגופיה דמי\u0004 \u0005[כגופה\u0006 הם \u0005נחשבים],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שדינם כצרורות. ומכל מקום בעיקרו של דבר נחלקו בדין צרורות עצמו, אם לפסוק כסומכוס או כחכמים.","ומציעים עוד ראיה לדבר, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רמי בר יחזקאל\u0004 בברייתא: \u0003תרנגול שהושיט ראשו לאויר\u0004 (לתוך חלל) של \u0003כלי זכוכית ותקע\u0004 (קרא, השמיע קול) \u0003בו ושברו\u0004 על ידי קולו — הרי זה \u0003משלם נזק שלם\u0004 על כך. \u0003ו\u0004לעומת זאת \u0003אמר רב יוסף: אמרי בי\u0004 \u0005[אומרים\u0006 החכמים \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003רב: סוס שצנף\u0004 (השמיע קול) \u0003וחמור שנער\u0004 בקולו \u0003ושיבר את הכלים\u0004 של זכוכית מכוח קולו — \u0003משלם חצי נזק.\u0004 הרי שנחלקו חכמים בדבר.","ומעתה נלמד מהם לענייננו, \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003כגון דעבד\u0004 \u0005[שעשה]\u0006 אותו בעל חיים דבר זה כבר \u0003תלתא זימני\u0004 \u0005[שלוש פעמים],\u0006"],["\u0003ובהא קמיפלגי\u0004 \u0005[וב\u0006נושא \u0005זה נחלקו]:\u0006 \u0003מר סבר\u0004 \u0005[חכם זה\u0006 בברייתא שהביא רמי בר יחזקאל \u0005סבור]\u0006 \u0003יש העדאה\u0004 לצרורות, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמי בית מדרשו של רב \u0005סבורים]:\u0006 \u0003אין העדאה?\u0004","ודוחים: \u0003לא,\u0004 כאן מדובר שעשה זאת \u0003בחד זמנא\u0004 \u0005[בפעם אחת\u0006 בלבד\u0005],\u0006 \u0003ובפלוגתא\u0004 \u0005[ובמחלוקת]\u0006 של \u0003סומכוס ורבנן קמיפלגי\u0004 \u0005[\u0006הם \u0005חלוקים]\u0006 כמה משלם על צרורות. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003משונה הוא\u0004 שיכניס התרנגול צוארו לכלי וישמיע קול שיגרום לשבירתו של הכלי! ומשיבים: מדובר כאן \u0003דאית ביה בזרני\u0004 \u0005[שיש בו,\u0006 בכלי, \u0005זרעונים]\u0006 ומובן מדוע הכניס התרנגול ראשו לשם.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי\u0004 שאלה נוספת בנושא זה: האם \u0003יש שנוי לצרורות ל\u0004ענין \u0003רביע נזק,\u0004 שבמקרה שעשה נזק על ידי צרורות שלא כדרכו, ישלם עליו, לא חצי נזק כדרך שמשלם כרגיל, אלא מחצית התשלום הרגיל, שהוא רביע נזק, \u0003או אין שנוי לצרורות ל\u0004ענין \u0003רביע נזק,\u0004 ואף אם היה הדבר בשינוי משלם חצי נזק, ככל נזק צרורות?","ומשיבים: \u0003תפשוט ליה\u0004 \u0005[תפתור לו]\u0006 את בעייתו של רב אשי \u0003מ\u0004בעייתו של \u0003רבא,\u0004 \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003רבא: יש העדאה לצרורות\u0004 ומשלם נזק שלם אם עשה כן שלוש פעמים, \u0003או אין העדאה לצרורות,\u0004 ו\u0003מכלל\u0004 הדברים נשמע ש\u0003אין שנוי.\u0004 שהרי אם יש שינוי ומשלם רביע נזק — נמצא שתשלום של העדאה בצרורות הוא רק חצי נזק.","ודוחים: מדברי רבא אין להוכיח, \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003רבא\u0004 בדרך \u0003\"אם תמצי\u0004 \u0005[תוכל,\u0006 תרצה\u0005]\u0006 \u0003לומר\" קאמר\u0004 \u0005[אומר],\u0006 שלא העמיד את הבעיה באופן חד משמעי, אלא אפילו ביסודותיה של הבעיה היה לו ספק. וכך יש להסביר את שאלתו: \u0003אם תמצי\u0004 \u0005[תוכל,\u0006 תרצה\u0005]\u0006 \u0003לומר\u0004 ש\u0003אין\u0004 דין \u0003שנוי\u0004 בצרורות, ובכל מקרה משלם חצי נזק, תישאל השאלה: האם \u0003יש העדאה\u0004 שהמועד לצרורות ישלם נזק שלם, \u0003או אין העדאה?\u0004 לבעייתו של רב אשי לא נמצא פתרון, ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","ועוד \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי\u0004 בענין צרורות: \u0003כח כחו,\u0004 כגון צרור שניתז והתיז דבר אחר, והדבר השני הוא שהזיק, \u0003ל\u0004דעת \u0003סומכוס,\u0004 האם \u0003ככחו דמי\u0004 \u0005[נחשב],\u0006 \u0003או לא?\u0004","וצדדי השאלה: \u0003מי גמיר\u0004 \u0005[האם למד,\u0006 קיבל\u0005]\u0006 סומכוס מרבותיו \u0003הלכה\u0004 למשה מסיני זו של נזק צרורות שמשלם חצי נזק, \u0003ומוקי לה\u0004 \u0005[ומעמיד אותה]\u0006 את ההלכה הזו, לא בצרורות הבאים מכוחו אלא \u0003בכח כחו,\u0004 ואילו צרורות הבאים מכוחו ישלם נזק שלם ככל רגל. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003לא גמיר\u0004 \u0005[למד],\u0006 שלא קיבל \u0003הלכה\u0004 זו \u0003כלל\u0004 ולדעתו נזק צרורות הוא פרט בנזקי רגל, ומשלם תמיד נזק שלם, בין שבא מכוחו בין שבא מכח כוחו? אף בעיה זו לא נמצא לה פתרון ולכך אף היא \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ושוב חוזרים לפירושה של המשנה. שנינו שם שאם \u0003היתה\u0004 הבהמה \u0003מבעטת, או שהיו צרורות מנתזין מתחת רגליה ושברה את הכלים\u0004 — \u0003משלם חצי נזק. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003היכי קאמר\u0004 \u0005[כיצד\u0006 בדיוק \u0005הוא אומר],\u0006 כיצד יש להבין את משנתנו?","האם כוונתו: \u0003היתה\u0004 הבהמה \u0003מבעטת והזיקה\u0004 במישרין \u0003בביעוטה,\u0004 והרי זה תולדה לקרן, \u0003או\u0004 מקרה נוסף שהתיזה \u0003צרורות כאורחייהו\u0004 \u0005[כדרכם]\u0006 בדרך הילוכה — \u0003משלם\u0004 על כך \u0003חצי נזק, ו\u0004אם כן משנתנו כדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא\u0004 שמשלם על צרורות חצי נזק. \u0003או דלמא\u0004 \u0005[שמא]\u0006 כך יש להבין את משנתנו: \u0003היתה מבעטת והזיקה\u0004 במישרין \u0003בביעוטה, או\u0004 התיזה \u0003צרורות מחמת ביעוט\u0004 ואותם צרורות הם שהזיקו — \u0003משלם חצי נזק.\u0004 ונדייק מכאן: \u0003הא כי אורחיה\u0004 \u0005[הרי\u0006 אם היו הצרורות \u0005כדרכה]\u0006 — \u0003משלם נזק שלם, ומני\u0004 \u0005[ו\u0006כשיטת \u0005מי היא]\u0006 — שיטת \u0003סומכוס היא?\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון \u0003מסיפא\u0004 \u0005[מסוף\u0006 המשנה\u0005]:\u0006 \u0003דרסה על הכלי ושברתו, ונפל השבר על כלי אחר ושברו\u0004 — \u0003על הראשון משלם נזק שלם, ועל האחרון חצי נזק. ואי\u0004 \u0005[ואם]\u0006 כשיטת \u0003סומכוס\u0004 היא, \u0003מי אית ליה\u0004 \u0005[האם יש לו]\u0006 כלל תשלום \u0003חצי נזק\u0004 צרורות?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 מה ששנינו \u0003\"ראשון\"\u0004 כוונתו \u0003ראשון להתזה,\u0004 כלומר, הראשון שנפגע מן הצרורות, דהיינו הכלי השני, \u0003ו\"שני\"\u0004 הוא \u0003שני להתזה,\u0004 כלומר, כלי שלישי, \u0003ושאני ליה\u0004 \u0005[ושונה לו]\u0006 \u0003לסומכוס\u0004 הדין \u0003בין\u0004 נזק שנגרם מ\u0003כחו\u0004 שמשלם הכל, \u0003ל\u0004בין נזק שנגרם על ידי \u0003כח כחו\u0004 שמשלם רק חצי, אם כן,","\u0003אלא הא דבעי\u0004 \u0005[זו ששאל]\u0006 \u0003רב אשי: כח כחו לסומכוס,\u0004 האם \u0003ככחו דמי\u0004 \u0005[נחשב]\u0006 \u0003או לאו\u0004 \u0005[לא]\u0006 \u0003ככחו דמי\u0004 \u0005[נחשב],\u0006 \u0003תפשוט ליה\u0004 \u0005[לו]\u0006 מכאן \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003ככחו דמי\u0004 \u0005[נחשב]!\u0006","ומשיבים: משם אי אפשר היה לפתור, כי \u0003רב אשי כרבנן מוקי לה\u0004 \u0005[כ\u0006דעת \u0005חכמים\u0006 הוא \u0005מעמיד אותה]\u0006 את המשנה, \u0003ובעי לה הכי\u0004 \u0005[ושואל אותה כך]:\u0006 מהי כוונת משנתנו? \u0003היתה מבעטת והזיקה בביעוטה, או\u0004 התיזה \u0003צרורות כאורחייהו\u0004 \u0005[כדרכם]\u0006 — משלם \u0003חצי נזק.\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם התיזה צרורות \u0003מחמת ביעוט\u0004 — אינו משלם אלא \u0003רביע נזק, ו\u0004אם כן \u0003יש שנוי\u0004 לצרורות, ולכן משלם חצי מחיובו הרגיל של צרורות.","\u0003או דלמא\u0004 \u0005[שמא]\u0006 כך יש להבין: \u0003היתה מבעטת והזיקה בביעוטה, או\u0004 שהתיזה \u0003צרורות מחמת ביעוט\u0004 — משלם \u0003חצי נזק, ואין שנוי\u0004 בנזקים אלה. ושאלה זו לא נפתרה ולכך \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ועוד בעיה בדיני צרורות, \u0003בעי מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' אבא בר ממל מר' אמי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ששאל זאת \u0003מר' חייא בר אבא: היתה\u0004 הבהמה \u0003מהלכת במקום שאי אפשר לה\u0004 להלך \u0003אלא אם כן\u0004 היא \u0003מנתזת, ובעטה והתיזה\u0004 צרורות \u0003והזיקה, מהו?\u0004 וצדדי השאלה: \u0003כיון\u0004 ש\u0003אי אפשר לה\u0004 אלא אם כן תתיז צרורות — \u0003אורחיה\u0004 \u0005[דרכה]\u0006 \u0003הוא\u0004 שינתזו הצרורות ודינו כדין צרורות רגיל, \u0003או דלמא השתא מיהא\u0004 \u0005[או שמא עכשיו על כל פנים]\u0006 \u0003מחמת ביעוט קמנתזה\u0004 \u0005[היא מתיזה]\u0006 \u0003צרורות\u0004 ואין זה ככל צרורות. לשאלה זו לא נמצא פתרון, ולכך \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' ירמיה מר' זירא: היתה\u0004 בהמה \u0003מהלכת ברשות הרבים ובעטה והתיזה והזיקה, מהו\u0004 דינה? וצדדי השאלה: האם \u0003לקרן מדמינן ליה\u0004 \u0005[מדמים אנו אותה]\u0006 \u0003וחייבת,\u0004 שכיון שמזיקה בזדון הרי היא חייבת גם ברשות הרבים, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003תולדה\u0004 של \u0003רגל הוא, ופטורה,\u0004 שאין חייבים על נזקי רגל ברשות הרבים? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 כי זו \u0003תולדה\u0004 של \u0003רגל הוא,\u0004 ולכן אין חייבים עליה ברשות הרבים.","ועוד הוסיף ר' ירמיה ושאל את ר' זירא בדיני צרורות: \u0003התיזה\u0004 הבהמה צרור \u0003ברשות הרבים והזיקה ברשות היחיד מהו? אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא בתשובה בשימוש לשון של דיני שבת: אם \u0003עקירה אין כאן, הנחה יש כאן?!\u0004 כלומר, כיון שבזמן שנעקר החפץ ממקומו היתה פטורה על כך, אם כן העובדה שנח והזיק במקום אחר — אינה משנה את דינו.","ועל תשובתו הראשונה של ר' זירא, שעל צרורות ברשות הרבים פטור, כרגל, \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ר' ירמיה ממה ששנינו בברייתא: \u0003היתה מהלכת בדרך והתיזה, בין ברשות היחיד בין ברשות הרבים\u0004 — \u0003חייב. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה שמדובר כאן במקרה ש\u0003התיזה ברשות הרבים והזיקה ברשות הרבים?\u0004 אמר לו ר' זירא: \u0003לא,\u0004 יש לפרש שמדובר כאן במקרה ש\u0003התיזה ברשות הרבים והזיקה ברשות היחיד.\u0004 והקשה לו ר' ירמיה: \u0003והאמרת\u0004 \u0005[והרי אמרת]:\u0006 \u0003עקירה אין כאן הנחה יש כאן\u0004 ואין זה משנה היכן הזיקה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003הדרי\u0004 \u0005[חוזר אני]\u0006 \u0003בי,\u0004 שהרי הברייתא מוכיחה על כל פנים שבמקרה זה היא משלמת על הנזקים שהזיקה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ר' ירמיה ממה ששנינו במשנתנו: \u0003דרסה על הכלי ושברתו, ונפל השבר על כלי אחר ושברו\u0004 — \u0003על הראשון משלם נזק שלם, ועל האחרון משלם חצי נזק. ותני עלה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005עליה]\u0006 על קטע זה: \u0003במה דברים אמורים\u0004 — שהיה הדבר \u0003ברשות הניזק, אבל\u0004 אם היה \u0003ברשות הרבים\u0004 — \u0003על הראשון פטורה\u0004 (כדין רגל) \u0003ועל האחרון חייבת. מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר שהיה המקרה כך: \u0003התיזה ברשות הרבים, והזיקה ברשות הרבים?\u0004 ומשמע שעל נזק צרורות משלמת אפילו ברשות הרבים!","אמר לו ר' זירא: \u0003לא,\u0004 אפשר לפרש שמדובר כאן במקרה ש\u0003התיזה ברשות הרבים והזיקה ברשות היחיד.\u0004 וחזר והקשה לו ר' ירמיה: \u0003והאמרת\u0004 \u0005[והרי אמרת]\u0006 \u0003עקירה אין כאן הנחה יש כאן\u0004 ואין זה משנה היכן הזיקה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הדרי\u0004 \u0005[חוזר אני]\u0006 \u0003בי\u0004 מדברי אלה, כפי שכבר חזר בו בגלל הברייתא האחרת.","על סברתו של ר' זירא, חזר ושאלו ר' ירמיה: \u0003איני\u0004 \u0005[וכי כן הוא]\u0006 שדין צרורות ברשות הרבים כדין רגל, ופטור?"],["\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: אין חצי נזק חלוק לא לרשות היחיד ולא לרשות הרבים,\u0004 \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 נפרש שכלל זה אמור גם בחצי נזק צרורות, שאם \u0003התיזה ברשות הרבים והזיקה ברשות הרבים\u0004 חייבת כברשות היחיד? אמר לו ר' זירא: \u0003לא,\u0004 מדובר כאן ש\u0003התיזה ברשות הרבים והזיקה ברשות היחיד.\u0004","וחזר והקשה לו ר' ירמיה: \u0003והאמרת\u0004 \u0005[והרי אמרת]:\u0006 \u0003עקירה אין כאן הנחה יש כאן? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הדרי\u0004 \u0005[חוזר אני]\u0006 \u0003בי\u0004 מאותה סברה. \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 הסבר אחר: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' יוחנן\u0004 שאין חילוק בין רשות היחיד ורשות הרבים בחצי נזק, אמר זאת רק \u0003אקרן\u0004 \u0005[על\u0006 נזקי \u0005קרן],\u0006 ולא על חצי נזק של צרורות, שפטורה ברשות הרבים, כדין רגל.","מסופר: \u0003יתיב\u0004 \u0005[ישבו]\u0006 \u0003ר' יהודה נשיאה\u0004 \u0005[הנשיא]\u0006 \u0003ור' אושעיא\u0004 \u0003אקילעא\u0004 \u0005[באהלו]\u0006 של \u0003ר' יהודה\u0004 הנשיא, \u0003נפק מילתא מבינייהו\u0004 \u0005[יצא דבר מביניהם],\u0006 כלומר, כשישבו שם עורר אחד מהם בעיה זו: \u0003כשכשה\u0004 הבהמה \u0003בזנבה\u0004 וגרמה נזק על ידי כך, \u0003מהו? אמר ליה\u0004 \u0005[לו]\u0006 \u0003אידך\u0004 \u0005[האחר]:\u0006 \u0003וכי יאחזנה בזנבה וילך?!\u0004 ודאי אינו צריך הבעלים לשומרה עד כדי כך, ודבר זה דרכה הוא, ופטור. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003קרן נמי נימא\u0004 \u0005[גם כן נאמר]\u0006 סברה זו: \u0003וכי יאחזנה בקרן וילך?!\u0004 ובכל זאת דינו שהוא אחראי על נזקיה!","ודוחים: \u0003הכי השתא\u0004 \u0005[וכי כך אפשר להשוות]?!\u0006 \u0003קרן לאו אורחיה\u0004 \u0005[אין\u0006 זה \u0005דרכו]\u0006 להזיק בזדון, ולכן חייב הבעלים להשגיח עליו שלא יגח, \u0003הא אורחיה\u0004 \u0005[זו,\u0006 כישכוש הזנב, הוא \u0005דרכו]\u0006 של כל בהמה, ואי אפשר לחייב את הבעלים להשגיח עליה בכך.","ושואלים: \u0003וכי מאחר דאורחיה מאי מבעיא ליה\u0004 \u0005[שדרכה\u0006 היא זו, \u0005מה\u0006 אם כן \u0005נסתפק לו]?\u0006 שברור שדבר שהוא כדרכו אין חייב בו. ומשיבים: \u0003כשכוש יתירא\u0004 (יתר) מן הרגיל הוא \u0003מבעיא ליה\u0004 \u0005[נשאל לו]:\u0006 האם אומרים אנו שאף זה נכנס בכלל הדברים שעושה הבהמה כדרכה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב עינא\u0004 שאלה זו: \u0003כשכשה\u0004 בהמה \u0003באמתה\u0004 (באבר המין שלה) \u0003מהו\u0004 הדין? \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 \u0003מידי דהוה אקרן\u0004 \u0005[כשם שהדבר הוא בקרן],\u0006 \u0003קרן לאו יצרא קתקיף לה\u0004 \u0005[האם לא היצר\u0006 הוא ש\u0005תקף אותה]\u0006 ומשום כך הזיקה, \u0003הכא נמי לא שנא\u0004 \u0005[כאן גם כן אינו שונה],\u0006 שהרי יצר הוא שתקף אותה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 נחלק ונאמר כי בנזק \u0003קרן\u0004 \u0003כוונתו\u0004 הוא \u0003להזיק, הא\u0004 \u0005[זו]\u0006 אף שמחמת יצר הוא \u0003אין כוונתה להזיק\u0004 על ידי כך. לשאלה זו לא נמצאה תשובה ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו במשנה: \u0003התרנגולין מועדין להלך כדרכן ולשבר,\u0004 ואם היה דליל (חבל, או דבר אחר) קשור ברגליהם והזיק על ידי כך — משלם חצי נזק. \u0003אמר רב הונא: לא שנו\u0004 שמשלם חצי נזק \u0003אלא שנקשר\u0004 הדליל ברגל התרנגול \u0003מאליו, אבל\u0004 אם \u0003קשרו אדם\u0004 — \u0003חייב\u0004 לשלם נזק שלם.","ושואלים: אם \u0003נקשר מאליו, מאן\u0004 \u0005[מי\u0006 הוא זה\u0005]\u0006 ש\u0003חייב? אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003בעל הדליל\u0004 ישלם, משום שדליל זה גרם לנזק, נברר \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה הדבר]?\u0006 \u0003אי דאצנעיה\u0004 \u0005[אם שהצניע אותו]\u0006 בעל הדליל את הדליל, והתרנגול הוציא אותו ונקשר בו — \u0003אנוס הוא\u0004 בעל הדליל, וצריך להיות פטור מתשלומים. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא אצנעיה\u0004 \u0005[הצניע אותו]\u0006 והניחו במקום שיכול להיקשר ברגלי בעלי חיים — \u0003פושע\u0004 (רשלן) \u0003הוא,\u0004 ואין צריך לומר שחייב כאילו קשרו!","\u0003אלא\u0004 נאמר שהצניעו, ואם נקשר הדליל מאליו \u0003חייב בעל\u0004 ה\u0003תרנגול,\u0004 ואולם גם על כך יש לשאול: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה],\u0006 מדוע אומרים אנו, שאת \u0003כוליה\u0004 \u0005[כל]\u0006 ה\u0003נזק לא\u0004 ישלם — משום \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ו\u0003כי יפתח איש בור\"\u0004 (שמות כא, לג), ומשמע — \u0003ולא\u0004 שה\u0003שור\u0004 פותח \u0003בור,\u0004 ואם נפתח בור על ידי שורו — אין בעל השור חייב עליו. ואולם אם כן \u0003חצי נזק נמי\u0004 \u0005[גם כן]\u0006 נאמר: \u0003\"איש בור\"\u0004 — \u0003ולא שור בור,\u0004 ואם התרנגול גרר את הדליל ולאחר שנח הוזק בו דבר מה, מדוע יהיה בעליו חייב כלל?","\u0003אלא\u0004 יש לומר: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 צריכים לפרש אותה \u0003ב\u0004מקרה \u0003דאדייה אדויי\u0004 \u0005[שטילטלו]\u0006 התרנגול את הדליל וגרם נזק על ידי כך, וכיון שלא עשה את הנזק בגופו משלם רק חצי נזק כדין צרורות. \u0003וכי אתמר\u0004 \u0005[וכאשר נאמרו]\u0006 דברי \u0003רב הונא\u0004 — \u0003בעלמא אתמר\u0004 \u0005[\u0006\u0005בכלל נאמרו]\u0006 ואינם מתייחסים לדין שבמשנה. אלא אמר את ההלכה כך: \u0003דליל\u0004 שהיה של \u0003הפקר,\u0004 ונקשר ברגלי העוף, \u0003אמר רב הונא:\u0004 אם \u0003נקשר\u0004 הדליל \u0003מאליו\u0004 — \u0003פטור\u0004 בעל התרנגול, \u0003קשרו אדם\u0004 — \u0003חייב\u0004 הקושר.","ושואלים: \u0003משום מאי\u0004 \u0005[מה]\u0006 \u0003חייב?\u0004 איזה אב נזיקין עשה שיתחייב עליו? \u0003אמר רב הונא בר מנוח:\u0004 חייב \u0003משום בורו המתגלגל ברגלי אדם וברגלי בהמה,\u0004 שכשם שיש בור המצוי במקומו ומזיק לנתקלים בו, יש גם בור = תקלה, שאינו קבוע במקומו, אלא נע ממקום למקום, ואף על זה חייב משום בור.","\u0003כיצד,\u0004 באיזה אופן, \u0003השן מועדת\u0004 — \u0003לאכול את הראוי לה,\u0004 ולענין זה הבהמה מועדת תמיד. כיצד, \u0003הבהמה מועדת לאכול פירות וירקות\u0004 שהוא מאכל הראוי לה, ואם \u0003אכלה כסות או כלים\u0004 — \u0003משלם חצי נזק,\u0004 שכיון שאין זה מאכל הראוי לה — אינה מועדת לכך. \u0003במה דברים אמורים\u0004 שמשלם נזק שלם על מה שאכלה בהמתו — כשאכלה \u0003ברשות הניזק, אבל ברשות הרבים\u0004 — \u0003פטור. ו\u0004בכל זאת","\u0003אם נהנית\u0004 הבהמה באכילתה — \u0003משלמת מה שנהנית,\u0004 אבל לא משלמת את כל דמי הנזק.","\u0003כיצד,\u0004 באיזה מקרה, \u0003משלמת מה שנהנית?\u0004 אם \u0003אכלה מתוך הרחבה\u0004 שהיו פירות וירקות מונחים ברחבה שלפני החנויות, שהיא מקום הרבים, ואכלתם — הרי זו \u0003משלמת מה שנהנית.\u0004 אכלה \u0003מצדי הרחבה\u0004 שאינו מקום לרבים — \u0003משלמת מה שהזיקה\u0004 שהינו כרשות הניזק. וכן, אם אכלה \u0003מפתח החנות\u0004 — \u0003משלמת מה שנהנית\u0004 לפי שהוא מקום ציבורי, אכלה \u0003מתוך החנות\u0004 — \u0003משלמת מה שהזיקה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003השן מועדת לאכול את הראוי לה, כיצד? בהמה שנכנסה לחצר הניזק ואכלה אוכלין הראויין לה, ו\u0004כן אם \u0003שתתה משקין הראויין לה\u0004 — \u0003משלם\u0004 הבעלים \u0003נזק שלם\u0004 על מה שאכלה ושתתה. \u0003וכן חיה\u0004 של אדם \u0003שנכנסה לחצר הניזק וטרפה בהמה ואכלה בשר\u0004 — הרי זה \u0003משלם נזק שלם.\u0004","\u0003ופרה שאכלה שעורין\u0004 אף על פי שאינו כרגיל מאכל פרה, \u0003ו\u0004כן אם \u0003חמור שאכל כרשינן\u0004 שכרגיל נותנים אותם אותם לפרה ולא לחמור, \u0003וכלב שליקק את השמן, וחזיר שאכל חתיכה של בשר\u0004 — בכל אלה \u0003משלמין נזק שלם,\u0004 שאמנם אין אלה רגילים לאכול מאכל זה, אבל מכל מקום הוא מאכל הראוי להם, ואינו נקרא שינוי, ומשלם נזק שלם. \u0003אמר רב פפא: השתא דאמרת\u0004 \u0005[עכשיו שאתה אומר]\u0006 כפי שאמרנו כאן ש\u0003כל מידי דלאו אורחיה\u0004 \u0005[דבר שאין\u0006 זה \u0005דרכו\u0006 הרגילה\u0005]\u0006 \u0003ו\u0004הבהמה \u0003אכלה ליה\u0004 \u0005[אוכלת אותו]\u0006 \u0003על ידי הדחק שמיה\u0004 \u0005[שמו\u0006 הריהו נחשב\u0005]\u0006 \u0003אכילה\u0004 רגילה, אם כן, \u0003האי שונרא\u0004 \u0005[חתול]\u0006 ש\u0003אכל תמרי\u0004 \u0005[תמרים]\u0006 \u0003וחמרא דאכיל ביניתא\u0004 \u0005[וחמור שאכל דגים]\u0006 — \u0003משלם נזק שלם,\u0004 שאף על פי שאין דרכם לאכול דברים אלו, כיון שעל ידי הדחק אוכלים אותם — אין זו נקראת שינוי, אלא אכילה הראויה, ומשלם נזק שלם.","מסופר: \u0003ההוא חמרא דאכל נהמא\u0004 \u0005[חמור אחד שאכל לחם]\u0006 \u0003ו\u0004תוך כדי אכילה \u0003פלסיה לסלא\u0004 \u0005[שבר את הסל]\u0006 שבו היה הלחם, \u0003חייביה\u0004 \u0005[חייב אותו]\u0006 \u0003רב יהודה לשלם נזק שלם אנהמא\u0004 \u0005[על הלחם\u0006 שאכל\u0005],\u0006 \u0003ואסלא\u0004 \u0005[ועל הסל\u0006 שהזיק\u0005]\u0006 רק \u0003חצי נזק.\u0004 ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003כיון דאורחיה למיכל נהמא, אורחיה נמי לפלוסי סלא\u0004 \u0005[כיון שדרכו לאכול לחם, דרכו גם כן לשבור\u0006 את \u0005הסל],\u0006 שכדי להגיע ללחם שובר הוא את הסל ויהיה חייב נזק שלם גם על הסל! ומשיבים: שם מדובר שקודם \u0003אכל\u0004 החמור מן הלחם \u0003והדר פליס\u0004 \u0005[ואחר כך שבר]\u0006 את הסל, ודבר זה מורה על כוונה להזיק, ואין חייב עליו נזק שלם.","ושואלים: \u0003ופת אורחיה\u0004 \u0005[דרכו]\u0006 של חמור \u0003הוא\u0004 לאכול? \u0003ורמינהו\u0004 \u0005[ומשליכים\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא: \u0003אכלה פת ובשר ותבשיל\u0004 — \u0003משלם חצי נזק, מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003בבהמה,\u0004 משמע שבהמה האוכלת פת אין זה מדרכה, ואין זו אכילתה הראויה לה! ודוחים: \u0003לא,\u0004 מדובר כאן \u0003בחיה,\u0004 שאין דרכה לאכול לחם, אבל בהמה דרכה בכך.","ושואלים: אם מדובר כאן ב\u0003חיה,\u0004 הרי \u0003בשר אורחיה\u0004 \u0005[דרכה]\u0006 \u0003הוא\u0004 לאכול, ומדוע אומרים אנו שאין זה דרכה? ומשיבים: מדובר בבשר \u0003דמטוי\u0004 \u0005[\u0006כ\u0005שצלוי]\u0006 ובשר צלוי אין דרכה של חיה לאכול. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 כאן מדובר לא בחיה טורפת, אלא \u0003בטביא\u0004 \u0005[בצבי]\u0006 שאין דרכו לאכול בשר ופת. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם\u0004 מדובר \u0003בבהמה, ו\u0004מדובר כאן כשאכלה \u0003בפתורא\u0004 \u0005[בשולחן]\u0006 ודבר זה אין דרכה של בהמה לעשות."],["מסופר: \u0003ההוא ברחא דחזא ליפתא אפומא דדנא\u0004 \u0005[תיש אחד ראה לפת על פי חבית\u0006 חרס\u0005],\u0006 \u0003סריך סליק, אכלה לליפתא ותבריה לדנא\u0004 \u0005[טיפס\u0006 ו\u0005עלה, אכל את הלפת ושבר את החבית].\u0006 \u0003חייביה\u0004 \u0005[חייב אותו]\u0006 \u0003רבא,\u0004 את בעל התיש, \u0003אליפתא ואדנא\u0004 \u0005[על הלפת ועל הכלי]\u0006 בתשלומי \u0003נזק שלם.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 חייבו בתשלום נזק שלם גם על הכלי? והרי אין זה דרכו! — \u0003כיון דאורחיה למיכל ליפתא, אורחיה נמי לסרוכי ולמסלק\u0004 \u0005[שדרכו לאכול\u0006 את \u0005הלפת, דרכו גם כן לטפס ולעלות]\u0006 על מנת לאוכלה, ולכן גם שבירת הכלי בכלל נזקי השן היא.","\u0003אמר אילפא: בהמה\u0004 שהיתה \u0003ברשות הרבים ופשטה צוארה ואכלה מ\u0004ירק שהיה \u0003על גבי\u0004 (על גבה של) \u0003חברתה\u0004 שעמדה גם כן שם — \u0003חייבת, מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003גבי חברתה כחצר הניזק דמי\u0004 \u0005[נחשב],\u0006 ולכן חייב גם שם על נזקי השן.","ומציעים: \u0003לימא\u0004 \u0005[האם נאמר]\u0006 ש\u0003מסייע ליה\u0004 \u0005[לו]\u0006 ממה ששנינו בברייתא: \u0003היתה קופתו\u0004 (סלו) של אדם שהיה עומד ברשות הרבים \u0003מופשלת לאחוריו\u0004 ובתוכה דבר מאכל, \u0003ופשטה\u0004 הבהמה \u0003צוארה ואכלה ממנו\u0004 — \u0003חייבת.\u0004 ומשיבים: משם אין ראיה, כי אפשר לפרש ששם מדובר \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003רבא\u0004 בענין אחר — \u0003בקופצת, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 באוכלת מן הקופה מדובר \u0003ב\u0004מקרה שהיתה הבהמה \u0003קופצת,\u0004 וכיון שהיה זה שינוי ודאי חייב אף ברשות הרבים, ואולם חצי נזק, ולא נזק שלם כנזקי שן.","ושואלים: \u0003והיכא איתמר\u0004 \u0005[והיכן נאמר]\u0006 דבר זה שאמר \u0003רבא\u0004 מעיקרו? ומשיבים: \u0003אהא\u0004 \u0005[על זה]\u0006 ש\u0003אמר ר' אושעיא: בהמה ברשות הרבים,\u0004 אם \u0003הלכה ואכלה\u0004 — \u0003פטורה,\u0004 אם \u0003עמדה ואכלה\u0004 — \u0003חייבת.\u0004 ותהו על כך: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003הלכה\u0004 שחייבת \u0003דאורחיה\u0004 \u0005[שדרכה]\u0006 \u0003הוא?\u0004 אולם אם \u0003עמדה נמי אורחיה\u0004 \u0005[גם כן דרכה]\u0006 \u0003הוא! אמר רבא:\u0004 מה שאמרו \"עומדת\" מדובר \u0003בקופצת\u0004 ואוכלת,","שאין זה דרכה. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא: מתגלגל\u0004 ואוכל \u0003מהו\u0004 דינו? \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003כגון דקיימא\u0004 \u0005[שעומד]\u0006 \u0003עמיר\u0004 (אלומת תבואה) \u0003ברשות היחיד, וקא\u0004 \u0005[והוא]\u0006 \u0003מתגלגל ואתי\u0004 \u0005[ובא]\u0006 על ידי הבהמה \u0003מרשות היחיד לרשות הרבים\u0004 ושם אכלתו הבהמה, \u0003מאי\u0004 \u0005[מה]\u0006 הדין? האם יש לדונו כאן כדין שן ברשות היחיד ויהיה חייב, או כדין שן ברשות הרבים וייפטר?","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' חייא: משוי\u0004 (משא) ש\u0003מקצתו בפנים\u0004 ברשות הבעלים \u0003ומקצתו בחוץ\u0004 ברשות הרבים, \u0003אכלה בפנים\u0004 — \u0003חייבת,\u0004 שהוא רשות הניזק, \u0003אכלה בחוץ\u0004 — \u0003פטורה,\u0004 שהיא שן ברשות הרבים. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר אף כאן, ש\u0003מתגלגל ואתי\u0004 \u0005[ובא]\u0006 והולכים אנו אחר המקום בו היתה האכילה? ומשיבים: \u0003לא, אימא\u0004 \u0005[אמור]\u0006 כך: \u0003אכלה, על מה ש\u0004היה \u0003בפנים\u0004 — \u0003חייבת\u0004 אף אם נתגלגל החוצה, \u0003על מה שבחוץ\u0004 מתחילה — \u0003פטורה.\u0004","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 תירוץ אחר: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' חייא,\u0004 מה שאמר היה זה \u0003בפתילה דאספסתא\u0004 \u0005[בחבילה\u0006 ארוכה \u0005של אספסת]\u0006 שמקצתה בפנים ומקצתה בחוץ מתחילתה, ואינה מתגלגלת.","שנינו במשנה: \u0003אכלה\u0004 הבהמה \u0003כסות\u0004 או כלים — משלם בעליה חצי נזק, וממשיכה המשנה: במה דברים אמורים — ברשות הניזק, אבל ברשות הרבים פטור.","ושואלים: \u0003אהייא\u0004 \u0005[על איזה]\u0006 מקרה אמרו שהיא פטורה? \u0003אמר רב: אכולהו\u0004 \u0005[על כולם],\u0006 שברשות הרבים פטורה גם על אכילת כסות וכלים, אף שהוא דבר בלתי רגיל, וצריך היה לדונו משום קרן, שחייבת כרגיל אף ברשות הרבים. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 דבר\u0005]?\u0006 \u0003כל המשנה,\u0004 כלומר, שעשה דבר שאינו רגיל, \u0003ובא אחר ושינה בו\u0004 והזיקו — הרי זה \u0003פטור.\u0004 ואף כאן, מי שהניח כסות וכלים ברשות הרבים עשה דבר משונה, ולכן אף שהבהמה עשתה גם היא דבר משונה ואכלה אותם — אין חייבת עליהם.","\u0003ושמואל אמר: לא שנו\u0004 במשנה שפטור ברשות הרבים \u0003אלא\u0004 שאכלה \u0003פירות וירקות,\u0004 כדין שן ברשות הרבים, \u0003אבל\u0004 אם אכלה \u0003כסות וכלים\u0004 ברשות הרבים — \u0003חייבת\u0004 לשלם חצי נזק, שכיון שהוא משונה הריהו כקרן וחייב כדין קרן ברשות הרבים.","\u0003וכן אמר ריש לקיש\u0004 כדברי רב, שמה שנאמר במשנה שפטורה ברשות הרבים \u0003אכולהו\u0004 \u0005[על כולם]\u0006 נאמר. ומעירים: \u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003ריש לקיש לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר ריש לקיש:\u0004 היו \u0003שתי פרות ברשות הרבים, אחת רבוצה ואחת מהלכת, בעטה\u0004 הפרה ה\u0003מהלכת ברבוצה\u0004 — \u0003פטורה,\u0004 בעטה ה\u0003רבוצה במהלכת\u0004 — \u0003חייבת.\u0004 משמע שהוא סבור שכיון שדרך הפרה להלך ברשות הרבים, וזו רבצה, אפילו אם שינתה השניה ובעטה — פטורה.","\u0003ור' יוחנן אמר\u0004 כדברי שמואל בפירוש המשנה: \u0003לא שנו\u0004 שפטורה ברשות הרבים \u0003אלא\u0004 אם אכלה \u0003פירות וירקות, אבל כסות וכלים\u0004 — \u0003חייבת\u0004 לשלם חצי נזק גם ברשות הרבים.","ושואלים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 ש\u0003ר' יוחנן לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את דברי \u0003ריש לקיש אפילו בשתי פרות?\u0004 ודוחים: \u0003לא, לעולם\u0004 אפשר לומר כי \u0003אית ליה\u0004 \u0005[יש לו,\u0006 מקבל את דבריו\u0005],\u0006 אלא שהוא מחלק בין המקרים: \u0003כסות, עבדי אינשי דמנחי גלימי ומתפחי\u0004 \u0005[עשויים אנשים להניח גלימתם\u0006 ברשות הרבים \u0005ולנוח],\u0006 ולכן אין זה נחשב כשינוי, \u0003אבל בהמה לאו אורחה\u0004 \u0005[אין\u0006 זו \u0005דרכה]\u0006 שתהא רובצת ברשות הרבים, וכיון שבהמה זו עשתה שינוי — אין חיוב על האחרת ששינתה ובעטה בה.","שנינו במשנה: \u0003ואם נהנית\u0004 הבהמה — אף שפטורה מתשלומי הנזק שגרמה, מכל מקום \u0003משלמת\u0004 מה שנהנית. ושואלים: \u0003וכמה\u0004 הוא חלק זה שמשלמת? \u0003רבה אמר:\u0004 משלם על כל דבר שאכלה בהמתו רק \u0003דמי עמיר\u0004 (קש). שיכול בעליה לומר: אני הייתי מאכיל את בהמתי קש, ומה שנהנתה בדברים אחרים, צריך לחשב רק לפי דמי הקש שחסכתי על ידי כך. \u0003רבא אמר:\u0004 אם אכלה שעורים משלם \u0003דמי שעורים,\u0004 כלומר, ממין שאכלה, אבל \u0003ב\u0004מחיר ה\u0003זול\u0004 ביותר שבשוק.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבה, תניא כוותיה\u0004 \u0005[\u0006ו\u0005שנויה\u0006 ברייתא אחרת \u0005כשיטתו]\u0006 של \u0003רבא.\u0004 \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבה,\u0004 \u0003ר' שמעון בן יוחי אומר: אין משלמת אלא דמי עמיר בלבד.\u0004","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא:\u0004 \u0003אם נהנית\u0004 — \u0003משלמת מה שנהנית, כיצד? אכלה קב או קביים\u0004 (שני קבים) של תבואה \u0003אין אומרים תשלם דמיהן\u0004 של קב או קביים שאכלה, \u0003אלא אומדין כמה,\u0004 כלומר, באיזה סכום \u0003אדם רוצה להאכיל לבהמתו דבר הראוי לה, אף על פי שאינו רגיל\u0004 שתאכל אותו. ואם אכלה שעורים, למרות שאינה רגילה בכך — משלם עבור שעורים במחיר הזול שלהם. \u0003לפיכך,\u0004 כיון שאם \u0003אכלה\u0004 הפרה \u0003חטין, או\u0004 שאר \u0003דבר הרע לה\u0004 שלא היה רוצה להאכילה כלל, אם היה זה ברשות הרבים הרי \u0003פטורה\u0004 לגמרי.","בקשר להלכה זו במשנה, שאם נהנית משלם מה שנהנית (כפי שיבואר להלן) מספרים: \u0003אמר ליה\u0004 \u0005[לו]\u0006 פעם \u0003רב חסדא לרמי בר חמא: לא הוית גבן באורתא בתחומא\u0004 \u0005[היית עימנו בערב בתוך התחום],\u0006 \u0003דאיבעיא לן מילי מעלייתא\u0004 \u0005[ש\u0006כן \u0005נשאלו לנו דברים מעולים].\u0006 \u0003אמר\u0004 לו רמי בר חמא: \u0003מאי מילי מעלייתא\u0004 \u0005[מהם\u0006 אותם \u0005דברים מעולים]\u0006 שעסקתם בהם? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 השאלה היתה: \u0003הדר בחצר חבירו שלא מדעתו\u0004 (מרצונו), האם \u0003צריך להעלות\u0004 (לשלם) \u0003לו שכר\u0004 עבור מה שדר בחצירו \u0003או אין צריך?\u0004","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 שמדובר \u0003בחצר\u0004 ש\u0003לא קיימא לאגרא\u0004 \u0005[עומדת להשכרה]\u0006 ואם לא היה אדם זה גר שם היה בעליה משאירה ריקה, \u0003וגברא\u0004 \u0005[והאדם]\u0006 הדר בחצר הוא גם כן אדם ש\u0003לא עביד למיגר\u0004 \u0005[היה עשוי לשכור\u0006 חצר\u0005],\u0006 שיש לו אפשרויות אחרות של מגורים בחינם, אם כן הרי זה מקרה של \u0003זה\u0004 (הדייר) \u0003לא נהנה וזה\u0004 (הבעלים) \u0003לא חסר,\u0004 ובמקרה זה ודאי שאין לו לשלם. \u0003אלא\u0004 תאמר שמדובר \u0003בחצר דקיימא לאגרא\u0004 \u0005[העומדת להשכרה]\u0006 \u0003וגברא דעביד למיגר\u0004 \u0005[ואדם שעשוי לשכור\u0006 חצר\u0005],\u0006 אם כן \u0003זה\u0004 הדייר \u0003נהנה, וזה\u0004 בעל החצר \u0003חסר,\u0004 ובמקרה זה ודאי חייב לשלם!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 שאלה זו אלא \u0003בחצר\u0004 ש\u0003לא קיימא לאגרא\u0004 \u0005[עומדת\u0006 בדרך כלל \u0005להשכרה]\u0006 \u0003וגברא דעביד למיגר\u0004 \u0005[ואדם העשוי\u0006 וצריך היה \u0005לשכור],\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 יהיה דינו? וצדדי השאלה: האם \u0003מצי אמר ליה\u0004 \u0005[יכול לומר לו]\u0006 הדייר לבעל החצר: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003חסרתיך\u0004 ומה הפסדת בכך? הרי אתה לא הפסדת דבר, כיון שלא היתה חצרך עומדת להשכרה. \u0003או דלמא מצי אמר\u0004 \u0005[שמא יכול לומר]\u0006 בעל החצר לדייר:"],["\u0003הא איתהנית\u0004 \u0005[הרי נהנית]\u0006 מרכושי, שהרווחת על ידי כך את מה שהיית צריך לשלם עבור שכירת חצר?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רמי בר חמא: בעיה זו אינה בעיה חדשה, אלא \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003היא,\u0004 שבמשנה יש כבר תשובה לשאלה זו. שאל אותו רב חסדא: \u0003הי מתניתין\u0004 \u0005[איזו,\u0006 היכן, ב\u0005משנתנו]\u0006 היא נמצאת? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רמי בר חמא: \u0003לכי תשמש לי\u0004 \u0005[כאשר תשרת אותי]\u0006 במשהו, אומר לך היכן נמצא הדבר במשנה. \u0003שקל סודריה כרך ליה\u0004 \u0005[לקח\u0006 רב חסדא את \u0005סודרו\u0006 של רמי בר חמא ו\u0005כרך אותו]\u0006 שיהא זה כדרך שימוש. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רמי בר חמא, זו היא המשנה (משנתנו): \u0003אם נהנית משלמת מה שנהנית,\u0004 משמע שבעל הבהמה משלם עבור הנאתה בכל מקרה. ואף הדר בחצר עליו לשלם על הנאתו.","\u0003אמר רבא: כמה לא חלי\u0004 \u0005[חושש]\u0006 \u0003ולא מרגיש גברא דמריה סייעיה\u0004 \u0005[אדם שאדוניו,\u0006 הקדוש ברוך הוא, \u0005מסייע לו]\u0006 שיתקבלו דבריו. \u0003דאף על גב דלא דמי למתניתין קבלה מיניה\u0004 \u0005[שאף על פי שאין\u0006 השאלה \u0005דומה למשנתנו קבלה\u0006 רב חסדא \u0005ממנו,\u0006 מרמי בר חמא\u0005],\u0006 כי \u0003האי\u0004 \u0005[זה]\u0006 במשנתנו הוא מקרה של \u0003זה נהנה וזה חסר,\u0004 שהרי כאשר אוכלת הבהמה את הפירות מחסרת היא מן הפירות, \u0003ו\u0004אילו \u0003האי\u0004 \u0005[זה],\u0006 הדר בחצר שאינה עומדת להשכרה, \u0003זה נהנה וזה לא חסר הוא.\u0004","ושואלים: \u0003ורמי בר חמא\u0004 עצמו, כיצד השווה דברים שאינם דומים? ומסבירים: לדעתו \u0003סתם פירות\u0004 המונחים \u0003ברשות הרבים אפקורי מפקר להו\u0004 \u0005[מפקיר אותם]\u0006 בעליהם ואינו סבור שיוכל עוד ליהנות מהם, ולכן כאשר אכלתם בהמה אין זה נחשב לו כמי שחסר, ועל כן אפשר לדמות זאת לבעיית זה נהנה וזה לא חסר בדייר הגר בחצר.","מכל מקום מנסים להביא ראיה נוספת, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003המקיף\u0004 את \u0003חבירו משלש רוחותיו,\u0004 שיש לו שדות משלושה צדדים של שדה חבירו, \u0003וגדר את\u0004 \u0003הראשונה ואת השניה ואת השלישית\u0004 — \u0003אין מחייבין אותו,\u0004 את בעל השדה הפנימית להשתתף בתשלום עבור הגידור, למרות ששדהו גדורה בשלושה צדדים, שכן הוא יכול לומר שאינו נהנה מגידור זה כיון שעדיין צד אחד בשדהו פרוץ. ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם הקיפו שדות המקיף את שדה הניקף לגמרי, וגדר גם את הרוח ה\u0003רביעית\u0004 — \u0003מחייבין אותו,\u0004 את בעל השדה הפנימית לשלם.","\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003זה נהנה וזה לא חסר\u0004 — \u0003חייב,\u0004 שהרי הדר בפנימית נהנה, והמקיף לא חסר, שהרי בין כה וכה גידר את שדותיו, ובכל זאת חייב! ודוחים: \u0003שאני התם דאמר ליה\u0004 \u0005[שונה שם\u0006 המצב, \u0005ש\u0006כן \u0005יכול לומר לו\u0006 המקיף למוקף\u0005]:\u0006 \u0003את\u0004 \u0005[אתה]\u0006 \u0003גרמת לי הקיפא יתירא\u0004 \u0005[הקפה מרובה],\u0006 שהרי לולא השדה שלך שם לא הייתי צריך לגדור בין השדות שלי, ואם כן אתה הוא שגרמת לי את ההוצאה הנוספת, והרי זה דומה קצת ל\"זה נהנה וזה חסר\" שדינו של זה שנהנה לשלם.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה שנאמר באותה משנה, \u0003אמר ר' יוסי: אם עמד ניקף,\u0004 כלומר, בעל הקרקע שהיתה מוקפת \u0003וגדר את\u0004 המחיצה \u0003הרביעית\u0004 בעצמו — \u0003מגלגלין עליו את הכל,\u0004 לשלם גם עבור גידור המחיצות הקודמות, שהרי הוכיח במעשהו שהוא מעונין בגידור. ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא משום\u0005]\u0006 ש\u0003גדר ניקף,\u0004 שהוא עצמו עשה את הגדר, \u0003הא\u0004 \u0005[הרי]\u0006 אם היה גודר אותה \u0003מקיף\u0004 — היה הניקף \u0003פטור,\u0004","\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003זה נהנה וזה לא חסר\u0004 — \u0003פטור!\u0004 ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 \u0003דאמר ליה\u0004 \u0005[שיכול\u0006 הניקף \u0005לומר לו,\u0006 למקיף\u0005]:\u0006 \u0003לדידי סגי\u0004 \u0005[לי\u0006 עצמי \u0005די]\u0006 \u0003לי בנטירא בר זוזא\u0004 \u0005[בשמירה בת דינר\u0006 אחד\u0005],\u0006 כלומר, במחיצה כלשהי, ואינני מעונין בעצמי במחיצה חזקה ויקרה כזו שאתה בנית.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במשנה אחרת: \u0003הבית והעלייה\u0004 (קומה שניה) \u0003של שנים\u0004 שלאחד שייכת הקומה התחתונה ולאחר שייכת העלייה, \u0003שנפלו,\u0004 וצריך לבנות הכל מחדש, \u0003אמר בעל העלייה\u0004 \u0003לבעל הבית לבנות\u0004 את הבית, על מנת שהוא יוכל לבנות את העלייה שעל גבי הבית, \u0003והוא אינו רוצה\u0004 — \u0003הרי בעל העלייה בונה בית ויושב בה,\u0004 בבית, \u0003עד שיתן לו\u0004 בעל הבית \u0003יציאותיו\u0004 (הוצאותיו) שהוציא על בנין הבית, ורק אז יוצא ובונה לעצמו את העלייה.","ונדייק: \u0003יציאותיו הוא דמחייב ליה\u0004 \u0005[שמחויב לו]\u0006 \u0003בעל הבית\u0004 לשלם, \u0003הא\u0004 \u0005[הרי]\u0006 את \u0003שכרו,\u0004 שכר הדירה עבור מה שהשתמש בינתיים בבית — \u0003לא\u0004 מנכה לו בעל העלייה מחשבון ההוצאות. \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003זה נהנה וזה לא חסר\u0004 — \u0003פטור,\u0004 שהרי בעל העלייה נהנה מן הדירה, ובעל הבית אינו חסר, שהרי אומר שאינו זקוק לבית זה! ודוחים: \u0003שאני התם דביתא\u0004 \u0005[שונה שם שהבית]\u0006 \u0003לעלייה משתעבד,\u0004 שהרי הקומה התחתונה עשויה היתה לשמש בסיס לעליונה, ולכן חייב בעל הבית לתת לו מקום דירה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בברייתא באותו ענין, \u0003ר' יהודה אומר: אף זה הדר בחצר חבירו שלא מדעתו\u0004 — \u0003צריך להעלות לו שכר. שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003זה נהנה וזה לא חסר\u0004 — \u0003חייב!\u0004 ודוחים: משם אין להביא ראיה גמורה למקרה שאנו דנים בו, כי \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 שאפשר לטעון שיש לבעל החצר חסרון \u0003משום שחרוריתא דאשייתא\u0004 \u0005[השחרת הקירות],\u0006 שאדם המשתמש בבית גורם להשחיר את קירות הבית, והרי איפוא בעל הבית חסר. ואילו שאלתנו היתה באופן של זה נהנה וזה לא חסר. שאלה זו לא נפתרה איפוא.","\u0003שלחוה\u0004 את הבעיה הזו אל \u0003בי\u0004 \u0005[בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' אמי\u0004 לשאול מה דעתו בענין הדר בחצר חבירו שאינה עומדת להשכרה, \u0003אמר\u0004 ר' אמי: \u0003וכי מה עשה לו\u0004 דייר זה, \u0003ומה חסרו, ומה הזיקו?\u0004 ולדעתו אם מישהו נהנה בלי שהאחר יפסיד דבר — אינו משלם לו. \u0003ר' חייא בר אבא אמר\u0004 כאשר נשאל שאלה זו: \u0003נתיישב\u0004 (נחשוב) \u0003בדבר.\u0004 \u0003הדר\u0004 \u0005[חזרו]\u0006 ו\u0003שלחוה\u0004 לשאלה זו \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' חייא בר אבא.\u0004 \u0003אמר: כוליה האי שלחו\u0004 \u0005[כל כך שולחים]\u0006 \u0003לי ואזלי\u0004 \u0005[והולכים],\u0006 \u0003אילו אשכחי\u0004 \u0005[אם הייתי מוצא]\u0006 \u0003בה טעמא\u0004 \u0005[טעם,\u0006 תשובה מספקת\u0005]\u0006 וכי \u0003לא שלחנא להו\u0004 \u0005[הייתי שולח להם]?\u0006 אלא כיון שלא עניתי משמע שלא מצאתי עדיין תשובה לדבר.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שחלקו אמוראים בנושא זה, \u0003רב כהנא אמר\u0004 בשם \u0003ר' יוחנן: אינו צריך להעלות לו שכר,\u0004 ואילו \u0003ר' אבהו אמר\u0004 בשם \u0003ר' יוחנן: צריך להעלות לו שכר.\u0004","\u0003אמר רב פפא: הא\u0004 \u0005[\u0006מסורת הלכה \u0005זו]\u0006 של \u0003ר' אבהו\u0004 בשם ר' יוחנן \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בפירוש אתמר\u0004 \u0005[נאמרה]\u0006 \u0003אלא מכללא אתמר\u0004 \u0005[מכלל\u0006 הדברים \u0005נאמרה],\u0006 שרק מכלל (מתוך) דברים שאמר ר' יוחנן הסיק ר' אבהו מסקנה זו. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 גזבר של הקדש ש\u0003נטל\u0004 לעצמו \u0003אבן או קורה של הקדש\u0004 — \u0003הרי זה לא מעל,\u0004 שעצם נטילת האבן או הקורה על ידי הגזבר אינה נחשבת הוצאה מרשות הקדש, שהרי הגזבר מחזיק תמיד ברכוש זה.","\u0003נתנה\u0004 הגזבר \u0003לחבירו\u0004 במתנה — \u0003הוא,\u0004 הגזבר, \u0003מעל\u0004 משום שהוציאה מרשות הקדש, \u0003וחבירו לא מעל\u0004 לפי שעדיין לא השתמש בה. \u0003בנאה\u0004 הגזבר עצמו \u0003לתוך ביתו\u0004 — \u0003הרי זה לא מעל, עד\u0004 \u0003שידור תחתיה\u0004 כדי \u0003שוה פרוטה,\u0004 שכיון שנהנה ממנה בממון שיש לו ערך — מעל.","\u0003ואמר שמואל: והוא שהניחה על פי ארובה.\u0004 שאם היה מניח את האבן בתוך אבני הבנין הרי עצם הבניה היתה כבר מעילה, משום שעושה שינוי באבן, אולם כאשר מניח את האבן במקום שאפשר להחזירה, כל עוד לא דר תחתיה — אין זו קרויה מעילה.","\u0003ויתיב\u0004 \u0005[וישב]\u0006 \u0003ר' אבהו קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן וקאמר משמיה\u0004 \u0005[ואמר משמו]\u0006 של \u0003שמואל:\u0004 \u0003זאת אומרת, הדר בחצר חבירו שלא מדעתו\u0004 (מרצונו ורשותו) של חבירו — \u0003צריך להעלות\u0004 (לשלם) \u0003לו שכר,\u0004 שהרי אותו גזבר שדר תחת הקורה של ההקדש לא חיסר דבר מן הקורה, ואולם כיון שנהנה ממנה — הרי זה מעל. \u0003ושתק ליה\u0004 \u0005[לו]\u0006 ר' יוחנן.","\u0003איהו\u0004 \u0005[הוא]\u0006 ר' אבהו \u0003סבר מדשתיק\u0004 \u0005[מ\u0006מה \u0005ש\u0006הוא \u0005שותק]\u0006 משמע ש\u0003מודה ליה\u0004 \u0005[לו]\u0006 למסקנה זו, ולכן אמר אחר כך את הדברים בשם ר' יוחנן. \u0003ולא היא,\u0004 אין הדבר כן, ומה ששתק ר' יוחנן היה מפני ש\u0003אשגוחי לא אשגח ביה\u0004 \u0005[השגיח בו]\u0006 בר' אבהו לסתור את דבריו. ור' יוחנן סבור (כפי שרב כהנא אמר בשמו) שדייר שלא מדעת שאינו מחסר את הבעלים אינו צריך להעלות לו שכר.","וטעמו של דבר שגזבר ההקדש נידון כמועל על הנאה זו הוא \u0003כ\u0004דברי \u0003רבה,\u0004 שכן \u0003אמר רבה: הקדש\u0004 שנהנה ממנו \u0003שלא מדעת\u0004"],["\u0003כ\u0004מעשה שנעשה ב\u0003הדיוט\u0004 (בחולין) \u0003מדעת דמי\u0004 \u0005[נחשב],\u0006 כלומר, כאילו ידע חבירו ולא הסכים שייכנס לרשותו. כי ההקדש שייך לקדוש ברוך הוא, ואצלו אין שייך לומר שלא מדעת, ולכן כל הנהנה מן ההקדש — הרי הוא מועל, ואין להסיק מכאן לגבי דברים אחרים.","\u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא בר זבדא למרי בר מר: בעי מיניה\u0004 \u0005[שאל אותו]\u0006 את \u0003רב הונא: הדר בחצר חבירו שלא מדעתו, צריך להעלות לו שכר, או לא? אדהכי\u0004 \u0005[בינתיים]\u0006 \u0003נח נפשיה\u0004 \u0005[נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003רב הונא\u0004 לפני שהספיק לענות על השאלה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בר\u0004 \u0005[בן]\u0006 \u0003רב הונא\u0004 בתשובה לשאלה זו: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר אבא מרי\u0004 \u0005[מורי]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב:\u0004 \u0003אינו צריך להעלות לו שכר, והשוכר בית מראובן מעלה שכר לשמעון.\u0004 ותוהים: \u0003שמעון מאי עבידתיה\u0004 \u0005[מה מעשהו],\u0006 מה עניינו של שמעון כאן? ומסבירים, \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך היתה כוונתו: אם \u0003נמצא\u0004 ש\u0003הבית\u0004 ששכר מראובן באמת אינו שייך לו, אלא \u0003של שמעון\u0004 הוא — הדייר \u0003מעלה לו שכר\u0004 לשמעון.","ותוהים: \u0003תרתי\u0004 \u0005[שתים]?!\u0006 שתי הלכות סותרות זו את זו הוא אומר?! שהרי מצד אחד הוא אומר שהדר שלא מדעת הבעלים אינו חייב להעלות לו שכר, ומצד שני הוא אומר שאם התברר שבעל הבית היה אחר, והוא גר בחצר שלא מדעתו — חייב להעלות לו שכר! ומשיבים: \u0003הא\u0004 \u0005[זו],\u0006 ההלכה השניה שמעלה לו שכר, מדברת בחצר \u0003דקיימא לאגרא\u0004 \u0005[שעומדת להשכרה],\u0006 \u0003הא\u0004 \u0005[\u0006ו\u0005זו],\u0006 ההלכה שנאמר בה שאינו מעלה לו שכר, עוסקת בחצר \u0003דלא קיימא לאגרא\u0004 \u0005[\u0006\u0005שאינה עומדת להשכרה].\u0006","ומעירים: באופן דומה \u0003אתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 על ידי אמורא אחר, \u0003אמר ר' חייא בר אבין אמר רב, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' חייא בר אבין אמר רב הונא: הדר בחצר חבירו שלא מדעתו\u0004 — \u0003אינו צריך להעלות לו שכר, והשוכר בית מבני העיר מעלה שכר לבעלים.\u0004 ושואלים: \u0003בעלים מאי עבידתייהו\u0004 \u0005[מה מעשיהם],\u0006 כלומר, מה עניינם כאן? הלא מדובר בשוכר מבני העיר, כלומר, מנכסי העיר! ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 אם \u0003נמצאו לו\u0004 לבית \u0003בעלים,\u0004 שאינו שייך לבני העיר — השוכרים \u0003מעלין להן\u0004 לבעלים \u0003שכר.\u0004","ואף כאן יש לתמוה: \u0003תרתי\u0004 \u0005[שתים]\u0006 שתי הלכות סותרות זו את זו?! ומשיבים: \u0003הא\u0004 \u0005[זו],\u0006 ההלכה השניה עוסקת בחצר \u0003דקיימא לאגרא\u0004 \u0005[שעומדת להשכרה],\u0006 וכיון שכך נמצא שהבעלים מפסידים על ידי הדייר אם אינו משלם, \u0003הא\u0004 \u0005[זו],\u0006 ההלכה הראשונה מדברת בחצר \u0003דלא קיימא לאגרא\u0004 \u0005[שאינה עומדת להשכרה],\u0006 וכאן זה נהנה וזה לא חסר.","\u0003אמר רב סחורה אמר רב הונא אמר רב: הדר בחצר חבירו שלא מדעתו\u0004 — \u0003אין צריך להעלות לו שכר, משום שנאמר: \"ושאיה יוכת שער\"\u0004 (ישעיה כד, יב), כלומר, השממה מכתתת=שוברת את שערי הבתים, שבית שאינו מיושב מתמוטט, ולכן הדר בבית עושה על ידי כך טובה גם לבעל הבית, בכך שהוא שומר את הבית מהרס. \u0003אמר מר בר רב אשי: לדידי חזי ליה\u0004 \u0005[אני ראיתי אותו]\u0006 את \"שאיה\" זה, \u0003ומנגח כי תורא\u0004 \u0005[ונוגח\u0006 הוא כמו שור]. \u0003רב יוסף אמר: ביתא מיתבא\u0004 \u0005[בית מיושב]\u0006 מבני אדם — \u0003יתיב\u0004 \u0005[מיושב,\u0006 מתוקן ושמור הוא\u0005],\u0006 ובית שאין אנשים יושבים בו — אין דואגים לו.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 אם זה הטעם או זה? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 במקרה שאותו מקום בו נכנס הדייר \u0003קא משתמש ביה\u0004 \u0005[משתמש בו\u0006 בעל הבית\u0005]\u0006 \u0003בציבי ותיבנא\u0004 \u0005[בעצים ותבן]\u0006 שמאחסן שם, שאמנם שממה אין כאן, אבל מצד שני אין דיירים יושבים במקום ואין בודקים ומתקנים את קילקוליו, ולפי הטעם השני הדר בו אינו צריך לשלם דמי שכירות לבעלים.","מסופר: \u0003ההוא גברא\u0004 \u0005[אדם אחד]\u0006 ש\u0003בנה אפדנא אקילקלתא דיתמי\u0004 \u0005[ארמון על אשפה\u0006 שהיתה שייכת \u0005ליתומים].\u0006 \u0003אגביה\u0004 \u0005[גבה]\u0006 \u0003רב נחמן לאפדניה מיניה\u0004 \u0005[את ארמונו ממנו],\u0006 כלומר, החרים ממנו את הבנין, משום שלא שילם לבעלים. ושואלים: \u0003לימא קסבר\u0004 \u0005[האם לומר\u0006 ש\u0005סבור]\u0006 \u0003רב נחמן\u0004 כי \u0003הדר בחצר חבירו שלא מדעתו צריך להעלות לו שכר?\u0004 ודוחים: לא, אין זאת הוכחה, לפי שכאן היה מקרה מיוחד, \u0003ההוא מעיקרא קרמנאי הוו דיירי ביה\u0004 \u0005[באותו\u0006 מקום \u0005בתחילה\u0006 בני שבטים \u0005נודדים היו מתגוררים בו]\u0006 \u0003ויהבי להו ליתמי\u0004 \u0005[והיו נותנים ליתומים]\u0006 \u0003דבר מועט\u0004 עבור השימוש במקום, וכשבא אותו האיש ובנה את המקום פינה משם את הקרמנאים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן לבונה הארמון: \u0003זיל פייסינהו ליתמי\u0004 \u0005[לך פייס אותם, את היתומים]\u0006 ותן להם מה שהיו רגילים לקבל, \u0003ולא אשגח\u0004 \u0005[השגיח]\u0006 בו ולא עשה זאת, על כן \u0003אגביה\u0004 \u0005[הגבה]\u0006 \u0003רב נחמן לאפדניה מיניה\u0004 \u0005[את ארמונו ממנו].\u0006","שנינו במשנה: \u0003כיצד משלמת מה שנהנית\u0004 — אם אכלה מתוך הרחבה, שהיא רשות הרבים — משלמת מה שנהנית. אכלה מצידי הרחבה — משלמים הבעלים כל מה שהזיקה, כאילו הזיקה ברשות הניזק. \u0003אמר רב:\u0004 מה שאמרו שמשלם כל מה שהזיקה, מדובר \u0003במחזרת,\u0004 כלומר, שהבהמה עצמה עומדת ברחבה ומפנה את ראשה הצידה ואוכלת שם. \u0003ושמואל אמר: אפילו מחזרת נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור\u0004 לפי שהבהמה עצמה מצויה ברשות הרבים.","ושואלים: \u0003ול\u0004דעת \u0003שמואל היכי משכחת לה דמחייב\u0004 \u0005[איך מוצא אתה\u0006 אפשרות שיתקיים דין המשנה \u0005שמתחייב]\u0006 נזק שלם על מה שאוכלת בהמה בצידי הרחבה? ומשיבים: \u0003כגון דשבקתה לרחבה ואזלה וקמה\u0004 \u0005[שהניחה\u0006 הבהמה \u0005את הרחבה\u0006 לגמרי \u0005והלכה ועמדה]\u0006 \u0003בצידי רחבה,\u0004 שבמקרה כזה בוודאי משלם כל מה שהזיקה, שהרי זה ברשות הניזק.","\u0003ואיכא דמתני להא שמעתא באפי נפשה\u0004 \u0005[ויש ששונים את השמועה,\u0006 המחלוקת \u0005הזו בפני עצמה]\u0006 ולא כפירוש למשנתנו. \u0003מחזרת\u0004 ראשה לצידי הרחבה — \u0003רב אמר: חייבת, ושמואל אמר: פטורה.\u0004 ושאלו: \u0003ול\u0004דעת \u0003שמואל\u0004 מה ששנינו במשנה ש\u0003משלמת מה שהזיקה\u0004 בצידי הרחבה \u0003היכי משכחת לה דמחייבא\u0004 \u0005[כיצד מוצא אתה אותה שמחויב לשלם]?\u0006 ומשיבים: \u0003כגון דשבקה לרחבה ואזלה וקמה \u0004 \u0005[שהניחה את הרחבה והלכה ועמדה]\u0006 \u0003בצידי רחבה.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב נחמן בר יצחק:\u0004 מה ששנינו במשנה שאם אכלה \u0003מפתח החנות\u0004 — \u0003משלמת מה שנהנית, היכי משכחת לה\u0004 \u0005[היכן מוצא אתה אותה]\u0006 — \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שמדובר כאן \u0003במחזרת\u0004 ומפנה ראשה מרשות הרבים הצידה לפתח החנות, \u0003וקאמר\u0004 \u0005[ואמר]\u0006 \u0003(מר\u0004 \u0005[החכם]\u0006\u0003)\u0004 במשנה: משלמת \u0003מה שנהנית,\u0004 משמע \u0003מה שנהנית\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 משלמת, ואולם \u0003מה שהזיקה\u0004 — \u0003לא!\u0004","\u0003הוא מותיב לה\u0004 \u0005[\u0006היה \u0005מקשה\u0006 קושיה \u0005זו]\u0006 \u0003והוא\u0004 עצמו \u0003מפרק לה\u0004 \u0005[\u0006היה \u0005מתרץ אותה]:\u0006 מדובר כאן באופן מסויים \u0003דקיימא\u0004 \u0005[שעומדת]\u0006 החנות \u0003בקרן זוית\u0004 ולכן מגיעה הבהמה לפתח החנות בלי שתצטרך להפנות את ראשה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 את הדברים בגירסה שונה: כאשר הבהמה \u0003מחזרת\u0004 את ראשה לצידי הרחבה \u0003כולי עלמא לא פליגי דחייבת\u0004 \u0005[הכל אינם חולקים ש\u0006היא \u0005חייבת]\u0006 לשלם מה שהזיקה. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003ב\u0004מקרה ש\u0003מקצה מקום מרשותו לרשות הרבים,\u0004 שאותו אדם לא השתמש בכל קרקעו הפרטית, אלא השאיר חלק פנוי ומשתמשים בו הרבים, ובמקום זה הזיקה הבהמה.","ונחלקו לגבי מקום זה, אם דינו לענין נזיקין כרשות הרבים או כרשות היחיד, \u0003והכי אתמר\u0004 \u0005[וכך נאמר],\u0006 כלומר, בכך נחלקו, \u0003אמר רב: לא שנו\u0004 במשנתנו שחייבת \u0003אלא מחזרת\u0004 ראשה לצידי הרחבה, שאין זה כרשות הרבים, \u0003אבל מקצה מקום מרשותו לרשות הרבים\u0004 — \u0003פטורה,\u0004 שהרי בפועל מקום זה הוא רשות הרבים. \u0003ושמואל אמר: אפילו מקצה מקום מרשותו לרשות הרבים\u0004 הרי זו \u0003חייבת,\u0004 כי מקום זה נחשב עדיין כרשותו שלו.","ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי \u0003ב\u0004שאלה של \u0003בור ברשותו קמפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005];\u0006 \u0003רב\u0004 ש\u0003אמר פטור\u0004 על מה שאכלה הבהמה במקום שהוקצה לרבים \u0003קסבר\u0004 \u0005[סבור]\u0006 שאם אדם עושה \u0003בור\u0004 או שאר דבר המזיק \u0003ב\u0004תוך \u0003רשותו\u0004 שלו ואחר כך מפקיר את רשותו — הרי הוא \u0003חייב\u0004 על הנזקים שנגרמו, שהוא סבור כי כיון שהפקיר רשותו לאחר זמן, נעשה כחופר בור ברשות הרבים. ולפיכך אדם זה שהניח את פירותיו ברשותו ואחר כך הקצה מקום זה לרשות הרבים, אינו זכאי לתשלום כלשהו מבעל הפרה, שהוא אחראי לכל מה שנגרם.","\u0003ושמואל\u0004 ש\u0003אמר חייב\u0004 על מה שהזיקה הבהמה במקום שהוקצה לרבים \u0003קסבר\u0004 \u0005[סבור]\u0006 כי \u0003בור\u0004 שחפר \u0003ברשותו\u0004 אף על פי שאחר כך הפקיר רשותו — \u0003פטור,\u0004 הואיל ועשה מה שעשה ברשות, ולפיכך חייב בעל הפרה לשלם לו על הנזק שגרם לפירותיו?","ודוחים: מכאן אין להוכיח, \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב: לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך:\u0004"],["\u0003בעלמא\u0004 \u0005[ב\u0006דרך \u0005כלל]\u0006 על נזקי \u0003בור ברשותו\u0004 — \u0003פטור, ושאני הכא\u0004 \u0005[ושונה\u0006 המקרה \u0005כאן]\u0006 \u0003דאמר\u0004 \u0005[שיכול לומר]\u0006 בעל הבהמה לבעל הפירות: \u0003לאו כל כמינך דמקרבת להו\u0004 \u0005[אין ביכלתך\u0006 \u0005לקרב אותם],\u0006 את \u0003פירותך לרשות הרבים ומחייבת להו לתוראי\u0004 \u0005[ולחייב את שורי]\u0006 על ידי כך.","\u0003ו\u0004מצד שני \u0003שמואל אמר: בעלמא\u0004 \u0005[ב\u0006דרך \u0005כלל]\u0006 \u0003בור ברשותו\u0004 — \u0003חייב,\u0004 אלא \u0003דבשלמא\u0004 \u0005[שנניח]\u0006 ב\u0003בור איכא למימר לאו אדעתיה\u0004 \u0005[יש\u0006 מקום \u0005לומר\u0006 ש\u0005לא\u0006 עלה \u0005על דעתו]\u0006 של הניזק שהבור נמצא שם והוא עשוי להזיק, ולכן חיייב בעל הבור, \u0003אלא פירות\u0004 השטוחים על פני הקרקע \u0003מי איכא למימר לאו אדעתיה\u0004 \u0005[האם יש\u0006 מקום \u0005לומר\u0006 ש\u0005אין\u0006 זה \u0005לדעתו]\u0006 של השור? \u0003הא חזי להו\u0004 \u0005[הלא רואה הוא אותם]!\u0006","ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 שמחלוקת זו בענין \u0003מחזרת\u0004 הבהמה ראשה \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא,\u0004 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003אכלה מתוך הרחבה\u0004 — \u0003משלמת מה שנהנית,\u0004 אכלה \u0003מצידי הרחבה\u0004 — \u0003משלמת מה שהזיקה,\u0004 אלו \u0003דברי ר' מאיר ור' יהודה.\u0004 ואילו \u0003ר' יוסי ור' אלעזר אומרים: אין דרכה\u0004 של הבהמה \u0003לאכול\u0004 ברשות הרבים \u0003אלא להלך,\u0004 ולכן היא חייבת.","תחילה אנו מבינים כי גם דברי ר' יוסי מתייחסים לאוכלת מצידי רחבה, ואם כן נמצא לכאורה כי דעת \u0003ר' יוסי היינו\u0004 \u0005[הריהי]\u0006 כדעתו של ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 ר' מאיר, שחייבת על מה שאכלה בצידי רחבה, שאין דרכה לאכול אלא להלך. \u0003אלא\u0004 כיון שיש מחלוקת בדבר, צריך לפרש כי בענין \u0003מחזרת איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 מחלוקת. כיצד? — ה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]\u0006 ש\u0003מחזרת נמי\u0004 \u0005[גם כן]\u0006 \u0003משלם\u0004 רק \u0003מה שנהנית, ור' יוסי סבר: משלמת מה שהזיקה.\u0004","ודוחים: \u0003לא,\u0004 אפשר לומר \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 בדין \u0003מחזרת\u0004 הלכה \u0003אי\u0004 \u0005[או]\u0006 \u0003כרב אי\u0004 \u0005[או]\u0006 \u0003כשמואל,\u0004 כלומר, יכול אתה לומר הן לכאן והן לכאן. \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה מה בא ללמדנו הפסוק \u0003\"ובער בשדה אחר\"\u0004 (שמות כב, ד) \u0003קא מיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005];\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' מאיר, \u0005סבור]:\u0006 \u0003\"ובער בשדה אחר\"\u0004 בא למעט — \u0003ולא\u0004 מחייב על כך \u0003ברשות הרבים, ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יוסי, \u0005סבור]:\u0006 \u0003\"ובער בשדה אחר\"\u0004 בא למעט — \u0003ולא ברשות המזיק,\u0004 אבל ברשות הרבים חייב בנזקי שן.","ותוהים: \u0003ברשות המזיק\u0004 מה חידוש בדבר שפטורה? \u0003לימא\u0004 \u0005[יאמר]\u0006 בעל הבהמה: \u0003פירך\u0004 \u0005[פירותיך]\u0006 \u0003ברשותי מאי בעי\u0004 \u0005[מה\u0006 הם \u0005מבקשים,\u0006 עושים שם\u0005],\u0006 ובוודאי אין הוא חייב על נזקים שנגרמו להם! \u0003אלא\u0004 יש לומר שביחס להלכות של \u0003אילפא ור' אושעיא איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 שאם הבהמה לא הלכה כדרכה אלא שאכלה מעל גבי צוואר חברתה וכיוצא בזה, האם דינה כאוכלת ברשות הרבים, או כיון שאין זה דרכה לעשות כן — חייבת.","\u0003הכלב והגדי שקפצו מראש הגג ושברו\u0004 בתוך כך \u0003את הכלים\u0004 — \u0003משלם נזק שלם\u0004 עליהם \u0003מפני שהן מועדין\u0004 לקפוץ. \u0003הכלב שנטל חררה\u0004 (פת הנאפת על גבי גחלים) והיו גחלים עמה, \u0003והלך לגדיש\u0004 לאכול אותה שם, \u0003אכל\u0004 את \u0003החררה ו\u0004בתוך כך \u0003הדליק\u0004 את \u0003הגדיש. על החררה\u0004 שאכל — \u0003משלם נזק שלם,\u0004 שהוא כדרכו, \u0003ועל הגדיש\u0004 — \u0003משלם\u0004 רק \u0003חצי נזק.\u0004","מדייקים מן המשנה: \u0003טעמא\u0004 \u0005[הטעם]\u0006 לחיובו בנזק שלם הוא דווקא משום שבעלי החיים שלו \u0003קפצו\u0004 מראש הגג, \u0003הא\u0004 \u0005[הרי]\u0006 מכאן אם \u0003נפלו\u0004 משם באונס — \u0003פטור,\u0004 למרות שהיה לו לשומרם שלא יעלו על הגג ויקפצו משם. \u0003אלמא קסבר\u0004 \u0005[מכאן שסבור]\u0006 תנא זה כי דבר ש\u0003תחלתו בפשיעה\u0004 ברשלנות או בזדון \u0003וסופו באונס\u0004 — \u0003פטור,\u0004 שהרי מיד שעלו לראש הגג היו יכולים לשבור את הכלים, ורשלנות היתה מצדו להניח להם לעלות לשם, ועם זאת כיון שבסוף לא קפצו אלא נפלו באונס הריהו פטור.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 בדיוק הזה: \u0003הכלב והגדי שקפצו מראש הגג ושברו את הכלים\u0004 — \u0003משלם נזק שלם. נפלו\u0004 משם — \u0003פטורין.\u0004 ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 שכל דבר ש\u0003תחלתו בפשיעה וסופו באונס\u0004 — \u0003פטור\u0004 עליו, כיון שבסופו של דבר לא נגרם הנזק בגלל פשיעתו. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שעל דבר כגון זה \u0003חייב, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ולכאורה יש מכאן הוכחה כנגדו!","ומשיבים: מדובר במקרה מסויים \u0003כגון דמקרבי\u0004 \u0005[שקרובים]\u0006 ה\u0003כלים לגבי\u0004 \u0005[אצל]\u0006 ה\u0003כותל,\u0004 \u0003דכי קפצי\u0004 \u0005[שכאשר היו קופצים]\u0006 מהגג \u0003ב\u0004דרך של \u0003קפיצה לא\u0004 היו \u0003נפלי עלייהו\u0004 \u0005[נופלים עליהם],\u0006 כיון שבקפיצה מתרחק הקופץ קצת ממקום הקפיצה, \u0003ו\u0004אם כן \u0003אפילו תחלתו בפשיעה ליכא\u0004 \u0005[אין כאן],\u0006 וכיון שרק נפילתם היא שגרמה לשבירת הכלים, הרי זה דבר שכולו אונס.","\u0003אמר רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא:\u0004 \u0003פעמים שאפילו נפלו נמי\u0004 \u0005[גם כן]\u0006 \u0003חייב\u0004 לשלם, \u0003משכחת לה\u0004 \u0005[מוצא אתה\u0006 אפשרות כגון \u0005זו]\u0006 \u0003ב\u0004שהיה זה \u0003כותל רעוע.\u0004 ושואלים: \u0003מאי ניהו\u0004 \u0005[מה הוא\u0006 הטעם לכך\u0005]\u0006 — \u0003דאבעי ליה לאסוקי דעתא דנפיל ארחי\u0004 \u0005[שהיה צריך להעלות על דעתו שיפלו לבנים]\u0006 מן הכותל וישברו את הכלים? ואולם \u0003סוף סוף\u0004 (בסופו של דבר) \u0003לא נפל ארחי\u0004 \u0005[נפלו לבנים]\u0006 אלא \u0003ונפול אינהו\u0004 \u0005[נפלו הם],\u0006 ואם כן הרי מקרה של \u0003תחלתו בפשיעה וסופו באונס הוא,\u0004 ואין זה חייב לדעת הכל! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 ההלכה אלא \u0003ב\u0004מקרה שהיה זה \u0003כותל צר,\u0004 שהיה ברור שאם יקפצו עליו יפלו משם, ולכן חייב עליהם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003הכלב והגדי שדלגו ממטה למעלה\u0004 והזיקו שם — \u0003פטורין,\u0004 לפי שאין דרכם לקפוץ בדרך זו. אבל אם דילגו \u0003מלמעלה למטה\u0004 — \u0003חייבין,\u0004 שכך דרכם לקפוץ. ואילו \u0003אדם ותרנגול שדלגו, בין\u0004 דילגו \u0003מלמעלה למטה בין מלמטה למעלה\u0004 — \u0003חייבין.\u0004"],["ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 האומרת להיפך: \u0003הכלב והגדי שדילגו, בין מלמעלה למטה בין מלמטה למעלה\u0004 — \u0003פטורין! תרגמא\u0004 \u0005[הסביר]\u0006 \u0003רב פפא:\u0004 מדובר באופן \u0003דאפיך מיפך\u0004 \u0005[שהפכו]\u0006 את דרך קפיצתם. כיצד? — \u0003כלבא בזקירא\u0004 \u0005[כלב בקפיצה\u0006 אחת\u0005]\u0006 \u0003וגדיא בסריכא\u0004 \u0005[והגדי בטיפוס],\u0006 שדבר זה אינו כדרכם, ומשונה היא. ושואלים: \u0003אי הכי, אמאי\u0004 \u0005[אם כך, מדוע]\u0006 \u0003פטורים?\u0004 שמכל מקום גרמו לנזק! ומשיבים: אין הכוונה פטורים לגמרי, אלא \u0003פטור מנזק שלם, וחייבין בחצי נזק,\u0004 כדינו של כל נזק משונה, שנדון כנזק קרן.","נאמר במשנה ש\u0003הכלב שנטל\u0004 חררה וגחלים עמה ואכל את החררה והדליק על ידי כך את הגדיש — משלם בעליו עבור החררה שאכל נזק שלם, ועבור נזקי הדליקה בגדיש חצי נזק.","ובענין זה של חיוב על נזקי אש מביאים: \u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים, \u0003ר' יוחנן אמר: אשו,\u0004 כלומר, חיובו של אדם לשלם עבור נזקים שגרמה אש שלו, הוא \u0003משום חציו,\u0004 שנחשב כאילו היה יורה חץ אל מקום אחר, וכן הוא הנזק שנגרם במקום אחר על ידי האש שהבעיר במקומו. \u0003וריש לקיש אמר:\u0004 אדם חייב על נזקי \u0003אשו משום ממונו,\u0004 כעל שאר דברים שהם ממונו שחייב אם גרמו נזק.","ומבררים את שיטותיהם, ושואלים: \u0003וריש לקיש מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כר' יוחנן?\u0004 ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004: אינה דומה אש לחציו, שכן \u0003חציו מכחו קאזלי\u0004 \u0005[הולכים],\u0006 שהרי החץ נורה מפני כוחו של היורה. \u0003האי\u0004 \u0005[זו]\u0006 האש \u0003לא מכחו קאזיל\u0004 \u0005[הולכת],\u0006 אלא הרוח היא המוליכה אותה, ומכוחו רק נוצרה האש במקומה. ושואלים מן הצד האחר: \u0003ור' יוחנן מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כריש לקיש?\u0004 ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך:\u0004 אינה דומה אשו לממונו, שכן \u0003ממונא אית ביה ממשא\u0004 \u0005[ממון\u0006 שהזיק \u0005יש בו ממש]\u0006 ואילו \u0003הא לית ביה ממשא\u0004 \u0005[זו,\u0006 האש, \u0005אין בה ממש]\u0006 ואין לומר שהאש שייכת לו כשאר דברים שהם רכושו.","ומנסים להביא ראיה ממה ששנינו במשנתנו, \u0003תנן\u0004 \u0005[שנינו]:\u0006 \u0003הכלב שנטל חררה וכו'\u0004 משלם על הגדיש חצי נזק. \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003אשו משום חציו\u0004 אם כן האש הזו \u0003חציו\u0004 (כוחו) של ה\u0003כלב הוא\u0004 —","ולכן חייב הבעלים לשלם על מה שגרם הכלב, ומשלם חצי נזק כדין צרורות, שאף הם כוחו. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003אשו משום ממונו\u0004 הלא \u0003האי\u0004 \u0005[זאת]\u0006 ה\u0003אש\u0004 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003ממונו\u0004 של \u0003בעל\u0004 ה\u0003כלב הוא\u0004 אלא של בעל החררה, ומשום מה יהיה חייב בעל הכלב?","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 \u0003ריש לקיש: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 לא שנטל את החררה והניחה כמות שהיא, אלא \u0003דאדייה אדויי\u0004 \u0005[שטלטלה\u0006 ממקום למקום\u0005]\u0006 וכך יש להבין את דין המשנה: \u0003על חררה\u0004 שאכל — \u0003משלם נזק שלם, ועל\u0004 הנזק שנגרם ב\u0003מקום\u0004 המסויים בו השליך הכלב את ה\u0003גחלת\u0004 — \u0003משלם חצי נזק\u0004 כמו על צרורות, \u0003ו\u0004אולם \u0003על\u0004 ה\u0003גדיש כולה פטור\u0004 שהרי חיוב אש הוא משום ממונו, ואש זו אינה ממונו של בעל הכלב.","\u0003ור' יוחנן\u0004 אינו צריך לפרש דווקא באופן זה, אלא במקרה רגיל: \u0003דאנחה אנוחי\u0004 \u0005[שהניחה]\u0006 את החררה בגדיש על מנת לאוכלה, ולכן \u0003על חררה ועל מקום גחלת משלם נזק שלם,\u0004 שכן נזק זה הוא בכלל נזקי אכילה של הכלב, \u0003ועל הגדיש משלם חצי נזק,\u0004 שלדעתו עיקר חיוב האש הוא משום שהיא נחשבת ככוחו, והרי זה כדין צרורות.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו במשנה: \u0003גמל\u0004 שהיה \u0003טעון פשתן ועבר ברשות הרבים, נכנסה פשתנו לתוך החנות ודלקו\u0004 (נדלקה) \u0003בנרו של חנווני והדליק את הבירה\u0004 (הבית) על ידי הפשתן — \u0003בעל\u0004 ה\u0003גמל חייב.\u0004 ואולם אם \u0003הניח חנווני נרו מבחוץ\u0004 — \u0003חנווני חייב. ר' יהודה אומר: בנר חנוכה\u0004 שמצוה להניחו בחוץ — \u0003פטור\u0004 החנווני.","ומעתה, בהלכה הראשונה, שחייב בעל הגמל בנזקי האש, יש לשאול: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003אשו משום חציו\u0004 יכול אתה לומר כי אש זו \u0003חציו\u0004 של ה\u0003גמל הוא,\u0004 ולכן חייב בעליו. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 אשו \u0003משום ממונו\u0004 — \u0003האי\u0004 \u0005[זו]\u0006 ה\u0003אש לאו\u0004 \u0005[לא]\u0006 \u0003ממונא\u0004 \u0005[הממון]\u0006 של \u0003בעל\u0004 ה\u0003גמל הוא!\u0004 ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך ריש לקיש: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003במסכסכת כל הבירה כולה,\u0004 לא שנגעה האש במקום אחר ומשם התפשטה הלאה, אלא שהגמל העביר את הפשתן הבוער ממקום למקום והדליק, והרי זה כמו הכלב שהניח את הגחלת בכל מקום ומקום.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של משנה זו: \u0003אם הניח חנווני נרו מבחוץ\u0004 — \u0003חנווני חייב. ואי\u0004 \u0005[ואם]\u0006 \u0003במסכסכת\u0004 מדובר — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003חייב\u0004 החנווני? הרי האש שלו היתה רק במקום אחד, והגמל הוא שהעבירה ממקום למקום! ומשיבים: כאן מדובר \u0003בשעמדה\u0004 וסכסכה, שעמד הגמל במקומו ולא הלך ממקום למקום, והפשתן שעל גביו היה מרובה מאד, כך שהצית באופן ישיר את הבירה כולה.","ושואלים: אם \u0003עמדה וסכסכה,\u0004 שלא הלך הגמל ממקום למקום, אלא החבילה היא זו שהדליקה את כל הבירה כולה, \u0003כל שכן\u0004 שה\u0003חנווני פטור ובעל גמל חייב,\u0004 שמוטל עליו להוציא את גמלו מן המקום! \u0003אמר רב הונא בר מנוח משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב איקא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שעמדה\u0004 הבהמה \u0003להטיל מימיה\u0004 ותוך כדי כך הציתה את האש בכל הבירה, ובעליה אנוס בענין זה, שאינו יכול להזיזה ממקומה."],["\u0003רישא\u0004 \u0005[\u0006במקרה ה\u0005ראשון]\u0006 \u0003בעל\u0004 ה\u0003גמל חייב,\u0004 כיון ש\u0003לא איבעי ליה\u0004 \u0005[צריך היה]\u0006 לעשות כדרך שעשה ו\u0003לאפושי\u0004 \u0005[להרבות]\u0006 \u0003בטעינה\u0004 של פשתן על גמלו עד כדי שיכנס הפשתן לחנות, ולכן האשמה לדליקה תלויה בו. \u0003סיפא\u0004 \u0005[\u0006ב\u0005סוף]\u0006 ה\u0003חנווני חייב,\u0004 כיון ש\u0003לא איבעי ליה לאנוחי\u0004 \u0005[היה צריך להניח]\u0006 את \u0003נרו מאבראי\u0004 \u0005[מבחוץ].\u0006","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003המדליק את הגדיש, והיה גדי כפות\u0004 (קשור) \u0003לו\u0004 סמוך לגדיש, \u0003ו\u0004כן \u0003עבד סמוך לו\u0004 לגדיש, \u0003ונשרף עמו\u0004 הגדי והעבד — \u0003חייב\u0004 לשלם על הגדיש ועל הגדי (ואולם על העבד פטור, שכן צריך היה העבד לברוח מפני האש). ואולם אם היה \u0003עבד כפות לו\u0004 באופן שלא יכול היה לברוח מהאש, \u0003וגדי סמוך לו ונשרף עמו\u0004 — \u0003פטור\u0004 על הגדי והגדיש.","ומעתה נברר, \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003אשו משום חציו\u0004 — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003פטור\u0004 על הגדיש במקרה השני, שהרי זה כאילו הוא הרג את העבד בחיציו ונתחייב מיתה על כך, ומי שנתחייב בעונש מיתה אין מענישים אותו גם בעונש ממון. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003אשו משום ממונו אמאי\u0004 \u0005[מדוע]\u0006 \u0003פטור? אילו קטל תוריה עבדא, הכי נמי דלא מיחייב\u0004 \u0005[אילו היה הורג שורו\u0006 שהוא ממונו \u0005עבד, כך גם כן שלא היה מתחייב]\u0006 בתשלום נזקים שגרם בתוך כדי כך?","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 \u0003ר' שמעון בן לקיש: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כשהצית\u0004 את האש ממש \u0003בגופו של עבד,\u0004 ולכן הוא חייב מיתה ככל הורג עבד, \u0003דקם ליה בדרבה מיניה\u0004 \u0005[שעומד לו,\u0006 די לו, \u0005ב\u0006עונש \u0005הגדול ממנו]\u0006 של מיתה, ואין מענישים גם אותו בעונש ממון.","ומקשים: \u0003אי הכי, מאי למימרא\u0004 \u0005[אם כך, מה\u0006 בא זה \u0005לומר],\u0006 מה חידוש משמיענו בזה? שהרי ממש רוצח הוא, ורוצח פטור מתשלומים! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא למקרה כגון זה: \u0003בגדי דחד\u0004 \u0005[של\u0006 אדם \u0005אחד]\u0006 \u0003ועבד דחד\u0004 \u0005[של\u0006 אדם \u0005אחד],\u0006 שהיינו אומרים שכיון שהוא מתחייב ממון לאדם אחר שאינו בעל העבד — יצטרך לשלם לבעל הגדי מה שהזיק לו, למרות שהוא חייב מיתה על הריגת העבד. על כן השמיע לנו שכיון שעל אותה פעולה עצמה התחייב עונש מוות — שוב אין אנו מחייבים אותו ממון כלל.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003השולח את הבעירה ביד חרש שוטה וקטן,\u0004 שכל אלה אין בהם דעת — \u0003פטור מדיני אדם,\u0004 שאין מחייבים אותו בבית דין על כך, \u0003ו\u0004אולם \u0003חייב בדיני שמים,\u0004 שמכל מקום יש לו אחריות על כך, וראוי לו לשלם.","ומעתה, \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003אשו משום חציו\u0004 — \u0003חציו\u0004 של \u0003חרש\u0004 שוטה וקטן \u0003הוא\u0004 ולכן פטור המשלח אותם. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003אשו משום ממונו, אילו מסר שורו לחרש שוטה וקטן הכי נמי\u0004 \u0005[כך גם כן]\u0006 הדין ש\u0003לא מיחייב\u0004 \u0005[יתחייב]?!\u0006 והרי שנינו במפורש שחייב (לעיל בבא קמא י,א)!","ומשיבים: \u0003הא אתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר על כך]\u0006 ש\u0003אמר ריש לקיש משמיה\u0004 \u0005[משמו]\u0006 של \u0003חזקיה: לא שנו\u0004 שפטור \u0003אלא\u0004 רק \u0003כשמסר לו\u0004 לשוטה \u0003גחלת ו\u0004השוטה \u0003ליבה\u0004 אותה ונעשתה דליקה, \u0003אבל\u0004 אם \u0003מסר לו שלהבת\u0004 דולקת — \u0003חייב. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 משום ש\u0003ברי היזקא\u0004 \u0005[ברור\u0006 כאן \u0005הנזק]\u0006 והרי זה כאילו היה מוסר לו שור נוגח. ואם כן, אף אם חיוב אש משום ממון הוא — חייב.","\u0003ור' יוחנן אמר: אפילו\u0004 מסר \u0003שלהבת\u0004 — \u0003פטור, קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003צבתא\u0004 \u0005[חברתו]\u0006 של ה\u0003חרש קא גרים\u0004 \u0005[היא\u0006 ש\u0005גורמת]\u0006 לדליקה, שמפני שטותו לא נזהר כראוי, ו\u0003לא מיחייב\u0004 \u0005[מתחייב]\u0006 המשלח אלא \u0003עד\u0004 ש\u0003מסר ליה\u0004 \u0005[לו]\u0006 \u0003גווזא סילתא ושרגא\u0004 \u0005[עץ, עצים דקים\u0006 שמציתים בהם אש, \u0005ונר\u0006 בוער\u0005]\u0006 שאז ברור הנזק, והרי זה כאילו הוא עשאו בעצמו. עד כאן הובאו ראיות שונות במחלוקת ר' יוחנן וריש לקיש.","\u0003אמר רבא: קרא ומתניתא מסייע ליה\u0004 \u0005[הכתוב והברייתא מסייעים לו]\u0006 \u0003לר' יוחנן.\u0004 \u0003קרא\u0004 \u0005[הכתוב]\u0006 — שכן אמר הכתוב \u0003\"כי תצא אש\"\u0004 (שמות כב, ה), משמע \u0003תצא מעצמה,\u0004 ונאמר \u0003\"ישלם המבער את הבערה\", שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003אשו משום חציו\u0004 שאנו מתייחסים אל האיש כאילו הוא עצמו הבעיר את הבעירה, ומשום כך מחייבים אותו בתשלום נזקיה, והרי זו ראיה מן הכתוב.","\u0003מתניתא\u0004 \u0005[\u0006מן \u0005הברייתא]\u0006 מנין — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על פסוק זה: \u0003פתח הכתוב\u0004"],["\u0003בנזקי ממונו,\u0004 שהרי נאמר \"כי תצא אש\" משמע שאחריותו על האש כמו על שאר דברים שהם ממונו שיוצאים ומזיקים, \u0003וסיים בנזקי גופו\u0004 שהרי הוא קורא לו \"מבעיר\", \u0003לומר לך:\u0004 חייב על \u0003אשו משום חציו.\u0004","\u0003אמר רבא: קשיא ליה\u0004 \u0005[היה קשה לו]\u0006 \u0003לאביי: למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003אשו משום חציו,\u0004 דין \u0003טמון באש\u0004 שדבר שהיה טמון ומכוסה בתוך דבר אחר, ונשרף באש \u0003דפטר רחמנא\u0004 \u0005[שפוטרת התורה]\u0006 מלשלם, \u0003היכי משכחת לה\u0004 \u0005[כיצד אתה מוצא אותה],\u0006 שהרי הפוגע בחץ חייב בין בגלוי בין בטמון!","\u0003וניחא ליה\u0004 \u0005[ונוח לו]\u0006 כלומר, תירץ אביי את הדבר באופן זה: פטור זה של טמון באש נמצא במקרה \u0003כגון שנפלה דליקה לאותו חצר\u0004 בחצר שלו, \u0003ו\u0004בינתיים \u0003נפלה גדר\u0004 שהיתה בין חצר זו לחצר אחרת \u0003שלא מחמת דליקה, והלכה\u0004 האש \u0003והדליקה והזיקה בחצר אחרת. דהתם\u0004 \u0005[ששם]\u0006 במקרה זה \u0003כלו ליה\u0004 \u0005[לו]\u0006 \u0003חציו,\u0004 שאש זו שהדליק בראשונה היתה מוגבלת רק לחצר האחת, וכוחו אינו אלא באותה חצר, והאש שיצאה לחצר האחרת אינה יכולה להיחשב כחיציו של אותו אדם, ומשום כך פטור על מה שהיה טמון ונשרף באש בחצר האחרת.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 לא רק לענין דבר טמון הוא פטור, אלא גם \u0003לענין\u0004 דבר ה\u0003גלוי\u0004 באש \u0003נמי\u0004 \u0005[גם כן]\u0006 ייפטר, שכן \u0003כלו ליה\u0004 \u0005[לו]\u0006 \u0003חציו,\u0004 ולא יהיה חייב כלל על הנזק שנגרם כתוצאה מהאש בחצר השניה!","\u0003אלא\u0004 יש לומר \u0003למאן דאית ליה\u0004 \u0005[ל\u0006דעת \u0005מי שיש לו,\u0006 שסבור\u0005]\u0006 שטעם חיוב האש הוא \u0003משום חציו\u0004 — \u0003אית ליה נמי\u0004 \u0005[יש לו גם כן]\u0006 הטעם שחייב עליה \u0003משום ממונו.\u0004 ולפיכך יתכן מקרה שפטור בטמון ולמרות זאת חייב בגלוי, \u0003וכגון שהיה לו\u0004 פנאי \u0003לגודרה,\u0004 את הגדר שנפלה מחמת דבר אחר, \u0003ולא גדרה,\u0004 שלדרך זו יש לו אחריות ממונית על האש, \u0003דהתם\u0004 \u0005[ששם]\u0006 הרי זה כאילו \u0003שורו הוא ולא טפח באפיה\u0004 \u0005[היכה בפניו]\u0006 שלא ייצא מן הרפת, שחייב על נזקיו. ומצד שני, אש זו אינה נחשבת לחיציו, שהרי לא מחמתה נפלה הגדר, ומשום כך פטור על הטמון.","ושואלים: לפי מסקנה זו, \u0003וכי מאחר דמאן דאית ליה\u0004 \u0005[שמי שיש לו,\u0006 שמחזיק\u0005]\u0006 בשיטה שאישו \u0003משום חציו אית ליה נמי\u0004 \u0005[יש לו,\u0006 סבור \u0005גם כן]\u0006 שחייב עליו \u0003משום ממונו,\u0004 אם כן \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין ר' יוחנן וריש לקיש הלכה למעשה?","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לענין \u0003לחייבו בארבעה דברים,\u0004 שאם הזיקה האש אדם, הרי נוסף לתשלום הנזק שגרם, חייב לדעת ר' יוחנן לשלם שאר דברים (צער, ריפוי, שבת ובושת) כשאר נזקים שחייב אדם לשלם אם הוא עצמו גורם נזק לאדם אחר, כיון שלדעת ר' יוחנן בנזק אש הרי זה כאילו הוא עצמו ירה בו חץ והזיקו.","נאמר במשנה ש\u0003על החררה\u0004 שאכל הכלב \u0003משלם\u0004 נזק שלם ועל הגדיש שנשרף משלם חצי נזק. ומסבירים: \u0003מאן\u0004 \u0005[מי]\u0006 הוא זה ש\u0003חייב\u0004 לשלם — \u0003בעל\u0004 ה\u0003כלב.\u0004 ושואלים: \u0003וליחייב נמי\u0004 \u0005[ושיתחייב גם כן]\u0006 \u0003בעל\u0004 ה\u0003גחלת,\u0004 שהרי גם לו חלק באשמה, כיון שלא שמר על גחלתו וגרם על ידה לתקלה! ומשיבים: כאן מדובר \u0003בששימר גחלתו\u0004 שמירה ראויה.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 אכן מדובר כאן \u0003כששימר גחלתו\u0004 — \u0003מאי בעי\u0004 \u0005[מה רוצה,\u0006 מה עושה\u0005]\u0006 ה\u0003כלב התם\u0004 \u0005[שם]?\u0006 ואם הכלב הגיע לשם ודאי לא שימר בעל הגחלת את גחלתו כראוי! ומשיבים: מדובר כאן \u0003בשחתר\u0004 (חפר) הכלב תחת הגדר ונכנס ולקח את החררה והגחלת. \u0003אמר ר' מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב כהנא: זאת אומרת סתם דלתות חתורות הן אצל כלב,\u0004 שאם היינו אומרים שחתירת הכלב היא דבר בלתי מצוי — לא היה חייב עליו בעליו נזק שלם. אלא בהכרח יש לומר שכלב עשוי לחתור תחת הדלתות, ומוטל היה על בעליו לקושרו.","ושואלים: ש\u0003אכלה\u0004 את החררה \u0003היכא\u0004 \u0005[היכן]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003אכלה בגדיש דעלמא\u0004 \u0005[סתם]\u0006 השייך לאדם אחר שאינו בעל החררה. אם כן גם משום שן לא יהיה חייב, \u0003הא בעינן\u0004 \u0005[הרי צריכים אנו]\u0006 כדי לחייבו בנזקי שן שיתקיים הכתוב \u0003\"ובער בשדה אחר\"\u0004 (שמות כב, ד) שיהא נזק השן נעשה בחצר הניזק, \u0003וליכא\u0004 \u0005[ואין]\u0006 הדבר כך במקרה זה! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה ש\u0003אכלה בגדיש\u0004 של \u0003בעל\u0004 ה\u0003חררה\u0004 עצמו, ולכן חייב עליה משום שאכלה ברשות הניזק.","ומציעים: \u0003תפשוט\u0004 \u0005[תפתור]\u0006 מכאן ותוכיח ש\u0003פי פרה\u0004"],["\u0003כחצר הניזק,\u0004 כלומר, כמו המקום שבו היא אוכלת, \u0003דמי\u0004 \u0005[נחשב].\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003כחצר המזיק\u0004 הוא \u0003דמי\u0004 \u0005[נחשב]\u0006 \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 בעל הכלב לניזק: \u0003מאי בעי רפתך בפומא דכלבאי\u0004 \u0005[מה רוצה,\u0006 מה עושה \u0005הלחם שלך בפי הכלב שלי]\u0006 שהוא רשותי ואיני חייב על נזק שנעשה בתוך רשותי.","ומעירים: והצורך בדיוק זה הוא משום \u0003דאיבעיא להו\u0004 \u0005[שנשאלה להם\u0006 לחכמים\u0005]\u0006 שאלה זו: \u0003פי\u0004 ה\u0003פרה\u0004 עצמו, האם \u0003כחצר הניזק דמי\u0004 \u0005[נחשב]\u0006 \u0003או כחצר המזיק דמי\u0004 \u0005[נחשב]?\u0006","ותוהים: \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 שפי פרה \u0003כחצר המזיק דמי\u0004 \u0005[נחשב],\u0006 אם כן \u0003שן דחייב רחמנא היכי משכחת לה\u0004 \u0005[שחייבה התורה כיצד אתה מוצא אותה]?\u0006 שהרי נזקי שן משלם רק על נזק שנעשה בחצר הניזק, ואם פי המזיק נחשב כרשותו של בעליו, נמצא שתמיד השן אוכלת ברשות המזיק!","\u0003אמר רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב כהנא:\u0004 אפשר גם באופן זה לתאר נזקי שן שיהא חייב בהם, \u0003כגון שנתחככה\u0004 הפרה \u0003בכותל להנאתה\u0004 ושברתו, \u0003ו\u0004כן אם \u0003טנפה\u0004 פרה \u0003פירות להנאתה\u0004 וקלקלה אותם, שהרי כל דבר שעושה בעל חיים לשם הנאתו הוא בגדר \"שן\", ויהא חייב עליו כיון שלא נכנס בפיו.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 תשובה זו \u0003מר זוטרא: והא בעינא\u0004 \u0005[והרי צריכים אנו]\u0006 בחיוב נזקי שן שיתקיים הכתוב \u0003\"כאשר יבער הגלל עד תמו\"\u0004 (מלכים א יד, י), שיהא זה נזק שמכלה הכל, \u0003ו\u0004כאן \u0003ליכא\u0004 \u0005[אין],\u0006 שהרי אבני הכותל שנשבר וכן הפירות שטונפו עדיין קיימים! \u0003רבינא אמר:\u0004 גם באופן זה, שהתחככה הפרה בכותל, אפשר שיהא נזק גמור המכלה הכל, כגון \u0003דשף צלמי\u0004 \u0005[ששיפשפה\u0006 ממנו \u0005את הצורות]\u0006 שהיו מצויירות בו. \u0003רב אשי אמר: דפסעי פסועי\u0004 \u0005[שמעכה]\u0006 את הפירות שהתגלגלה עליהם, ועל ידי כך כילתה אותם לגמרי. ואם כן, נשארה איפוא השאלה ביחס להגדרה של פי פרה.","ורוצים להציע \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה ששנינו: \u0003שיסה בו,\u0004 בחבירו, \u0003את הכלב, שיסה בו את הנחש\u0004 — \u0003פטור. מאן\u0004 \u0005[מי]\u0006 \u0003פטור\u0004 — \u0003משסה פטור, וחייב בעל\u0004 ה\u0003כלב. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 שפי הבהמה \u0003כחצר המזיק דמי\u0004 \u0005[נחשב],\u0006 \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 בעל הכלב לניזק: \u0003מאי בעי\u0004 \u0005[מה רוצה,\u0006 מה עושה\u0005]\u0006 \u0003ידך בפומיה דכלבאי\u0004 \u0005[בפיו של הכלב שלי]\u0006 שהוא רשותי?","ומתרצים: יש להבין אחרת את המשנה, \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003פטור אף משסה,\u0004 שהמשסה פטור מאחר שאין הכלב שלו, ובעל הכלב פטור לפי שמה שנעשה בפי כלבו הריהו כנעשה בחצירו. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שכאן מדובר \u0003דאפקיה לניביה וסרטיה\u0004 \u0005[שהוציא\u0006 הכלב את \u0005ניביו,\u0006 שיניו הגדולות, \u0005ושרטו]\u0006 ולא הכניס ידו בפיו, ואין זה איפוא בתוך חצר המזיק.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003השיך בו\u0004 בחבירו \u0003את הנחש,\u0004 שקירב את שיני הנחש לגוף חבירו, והרגו, \u0003ר' יהודה מחייב וחכמים פוטרים.\u0004","\u0003ואמר רב אחא בר יעקב\u0004 בהסבר מחלוקתם: \u0003כשתימצי\u0004 \u0005[כשתרצה\u0006 ותדייק בדבר\u0005]\u0006 תוכל \u0003לומר\u0004 כי \u0003לדברי ר' יהודה\u0004 — \u0003ארס נחש בין שיניו הוא עומד,\u0004 שאין הנחש עושה פעולה רצונית בהכשת הארס, אלא הוא נפעל בידי המכיש, \u0003לפיכך\u0004 האדם שהשתמש בנחש להכשה הרי הוא כ\u0003מכיש\u0004 (כמכה) חבירו \u0003בסייף\u0004 וחייב, \u0003והנחש\u0004 עצמו \u0003פטור\u0004 שהרי לא עשה מעצמו דבר. ו\u0003לדברי חכמים, ארס נחש\u0004 — \u0003מעצמו מקיא\u0004 אותו הנחש, ו\u0003לפיכך נחש בסקילה\u0004 כשאר חיה שהרגה אדם, \u0003ו\u0004האדם ה\u0003מכיש\u0004 על ידו \u0003פטור\u0004 ממיתת בית דין.","\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003פי פרה כחצר המזיק דמי\u0004 \u0005[נחשב],\u0006 \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 בעל הנחש לניזוק: \u0003מאי בעי\u0004 \u0005[מה רוצה,\u0006 מה עושה\u0005]\u0006 \u0003ידך בפומא דחיוואי\u0004 \u0005[בפי הנחש שלי]?\u0006 ומשיבים: \u0003לענין קטלא\u0004 \u0005[\u0006חיוב \u0005מיתה]\u0006 \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 טענה זו, כי בין בחצר המזיק ובין בחצר הניזק תמיד ההורג חייב.","\u0003ומנא תימרא\u0004 \u0005[ומנין תאמר]\u0006 שכן הוא — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הנכנס לחצר בעל הבית שלא ברשות, ונגחו שורו של בעל הבית, ומת\u0004 האיש — \u0003השור בסקילה, ובעלים פטורים מן הכופר.\u0004","ונברר: \u0003בעלים פטורין מן הכופר מאי טעמא\u0004 \u0005[מה טעם]\u0006 — \u0003דאמר ליה\u0004 \u0005[שאומר לו]:\u0006 \u0003ברשותי מאי בעית\u0004 \u0005[מה אתה רוצה]?\u0006 אם כן, לענין \u0003שורו נמי\u0004 \u0005[גם כן]\u0006 \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 בעל השור: \u0003מאי בעית\u0004 \u0005[מה אתה רוצה]\u0006 \u0003ברשותי,\u0004 וכיון שבאת שלא ברשות, כל האחריות עליך! \u0003אלא\u0004 חייבים לומר כי \u0003לענין קטלא לא אמרינן\u0004 \u0005[מיתה אין אנו אומרים]\u0006 טענה זו, ואין להוכיח מכאן לענין נזיקין שפי פרה נחשב כחצר הניזק.","מסופר: \u0003הנהו עיזי דבי תרבו דהוו מפסדי ליה\u0004 \u0005[אותן העזים של בית\u0006 משפחת \u0005תרבו שהיו מפסידים לו]\u0006 \u0003לרב יוסף\u0004 את נכסיו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף \u0003לאביי: זיל אימא להו למרייהו\u0004 \u0005[לך אמור להם לבעליהם]\u0006 \u0003דליצנעינהו\u0004 \u0005[שישמרו\u0006 ברשותם\u0005]\u0006 את העזים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי לרב יוסף: \u0003אמאי איזיל\u0004 \u0005[למה אלך]?\u0006 \u0003דאי אזילנא\u0004 \u0005[שאם אלך]\u0006 ואומר לו זאת \u0003אמרי\u0004 \u0005[יאמרו]\u0006 \u0003לי: לגדור מר גדירא בארעיה\u0004 \u0005[יגדור אדוני גדר בקרקעו]\u0006 ולא יוכלו העזים לבוא לרשותו.","על טענה זו שואלים: \u0003ואי גדר\u0004 \u0005[ואם גודר]\u0006 אדם בהכרח כדי להישמר משן בהמות, ואם לא גדר אין הבעלים חייבים בנזק, אם כן \u0003שן דחייב רחמנא\u0004 \u0005[שחייבה התורה]\u0006 על הנזק שנגרם לו \u0003היכי משכחת לה\u0004 \u0005[איך תמצא אותה]?\u0006 שאם צריך הניזק לגדור את שדהו שוב אין הבהמות הזרות יכולות להיכנס שם! ומשיבים: \u0003כשחתרה\u0004 הבהמה תחת הגדר. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003דנפיל גודא בליליא\u0004 \u0005[שנפלה הגדר בלילה]\u0006 ולא יכול היה בעל הגדר להספיק לבנותה לפני שנגרם הנזק.","ובענין נזקי שן של עזים, מסופר: \u0003מכריז\u0004 היה \u0003רב יוסף ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רבה: דסלקין לעילא ודנחתין לתחתאה\u0004 \u0005[העולים למעלה והיורדים למטה],\u0006 כלומר, הבאים מבבל לארץ ישראל (\"עולים\") ומביאים אתם מתורת בבל, והבאים מארץ ישראל לבבל (\"יורדים\") ומביאים אתם מתורת ארץ ישראל, כולם מסכימים להלכה זו: \u0003הני עיזי דשוקא דמפסדי\u0004 \u0005[אותם עזים\u0006 השוהות \u0005בשוק\u0006 עד שישחטון ובינתיים \u0005הן גורמות הפסד],\u0006 \u0003מתרינן במרייהו תרי ותלתא זמנין\u0004 \u0005[מתרים אנו בבעליהן שתים ושלוש פעמים],\u0006 \u0003אי ציית\u0004 \u0005[אם מציית]\u0006 לנו ושומר את בהמתו מלהזיק — הרי \u0003ציית\u0004 \u0005[מציית]\u0006 הוא, ואין אנו אומרים לו דבר. \u0003ואי\u0004 \u0005[ואם]\u0006 הוא \u0003לא\u0004 מציית — \u0003אמרין ליה\u0004 \u0005[אומרים אנו לו]:\u0006 \u0003תיב אמסחתא וקבל זוזך\u0004 \u0005[שב על\u0006 יד \u0005האטליז וקבל\u0006 את \u0005מעותיך],\u0006 כלומר, שחט את העזים מיד, שכיון שכוונתך לשוחטן אין אתה רשאי להשהות נזק זה אצלך.","\u0003איזהו תם ואיזו מועד? מועד\u0004 — \u0003כל שהעידו בו שלשה ימים\u0004 שנגח בכל יום. \u0003ו\u0004שב דינו להיות \u0003תם\u0004 — \u0003משיחזור בו\u0004 ולא יגח \u0003שלשה ימים,\u0004 אלו \u0003דברי ר' יהודה, ר' מאיר אומר: מועד\u0004 — כל \u0003שהעידו בו שלשה פעמים\u0004 בלי קשר למספר הימים שנגח בהם. \u0003ו\u0004שב דינו להיות \u0003תם\u0004 בדרך זו: \u0003כל שיהו התינוקות\u0004 (הילדים) \u0003ממשמשין בו\u0004 ומשחקים בו \u0003ואינו נוגח.\u0004","שואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 במשנתנו, ששור מועד הוא זה שנגח בשלושה ימים? על מה סומך הוא את דבריו? \u0003אמר אביי:\u0004 נאמר בתורה \"כי שור נגח הוא מתמול שלשום ולא ישמרנו בעליו\" (שמות כא, לו), וכך הוא דיוקו של הכתוב: \u0003\"תמל\"\u0004 — \u0003חד\u0004 \u0005[\u0006פעם \u0005אחת],\u0006 \u0003\"מתמל\"\u0004 (מלפני אתמול) — \u0003תרי\u0004 \u0005[שנים],\u0006 \u0003\"שלשם\"\u0004 — \u0003תלתא\u0004 \u0005[שלושה],\u0006 \u0003\"ולא ישמרנו בעליו\"\u0004 — \u0003אתאן\u0004 \u0005[באנו,\u0006 הגענו\u0005]\u0006 \u0003לנגיחה רביעית\u0004 שבה הוא מועד.","ואילו \u0003רבא אמר: \"תמל\" \"מתמל\"\u0004 אין דורשים לשתי דרשות, אלא הכוונה היא ליום \u0003חד\u0004 \u0005[אחד],\u0006 \u0003\"שלשם\"\u0004 הוא \u0003תרי\u0004 \u0005[שני\u0006 ימים\u0005],\u0006 \u0003\"ולא ישמרנו\"\u0004 פירושו \u0003האידנא\u0004 \u0005[עכשיו]\u0006 בנגיחה השלישית, ואז הוא \u0003חייב.\u0004","ושואלים: \u0003ור' מאיר\u0004 שאינו תולה את ההעדה בימים אלא במספר הפעמים שנגח, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' מאיר:\u0004"],["אם \u0003ריחק נגיחותיו,\u0004 שנגח שלוש פעמים במשך שלושה ימים זה אחר זה — הריהו \u0003חייב\u0004 כמועד, \u0003קירב נגיחותיו\u0004 שנגח שלוש פעמים במשך פחות משלושה ימים — \u0003לא כל שכן\u0004 שיהיה כן? \u0003אמרו ליה\u0004 \u0005[לו]\u0006 לר' מאיר, הרי פירכה לקל וחומר זה: \u0003זבה תוכיח, ש\u0004אם \u0003ריחקה ראיותיה,\u0004 כלומר, אם רואה זוב במשך שלושה ימים זה אחר זה — הרי היא \u0003טמאה,\u0004 ואולם אם \u0003קירבה ראיותיה,\u0004 וכגון שרואה זוב שלוש פעמים באותו יום — עדיין היא \u0003טהורה!\u0004","\u0003אמר להן:\u0004 מכאן אין ראיה, \u0003הרי הוא\u0004 הכתוב \u0003אומר\u0004 בדין זב: \u0003\"וזאת תהיה טמאתו בזובו\"\u0004 (ויקרא טו, ג), \"זאת\" היא הדגשה מיוחדת, שבענין זה יש ללכת לפי לשון הכתוב כלשונה, \u0003תלה הכתוב את\u0004 טומאת \u0003הזב\u0004 שיהא הגבר נחשב לזב \u0003ב\u0004מספר ה\u0003ראיות\u0004 שראה זיבה, \u0003ואת\u0004 טומאת \u0003הזבה\u0004 תלה הכתוב \u0003ב\u0004מספר ה\u0003ימים\u0004 שרואה (\"ימים רבים\", ויקרא כה). אבל לענין שור הנוגח עומד הקל וחומר בעינו.","ושואלים לעצם הענין: \u0003ממאי דהאי\u0004 \u0005[מנין שזה]\u0006 הביטוי הממעט \u0003\"וזאת\", למעוטי\u0004 \u0005[למעט]\u0006 \u0003זבה מראיות\u0004 הוא בא? \u0003אימא\u0004 \u0005[אמור]\u0006 שבא \u0003למעוטי זב מימים,\u0004 שזב יהיה דווקא זה שרואה שלוש ראיות ביום אחד ולא בשלושה ימים! ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 פסוק אחר \u0003\"והזב את זובו לזכר ולנקבה\"\u0004 (ויקרא, לג), הרי בפסוק זה \u0003מקיש\u0004 (משווה) טומאת זיבה של \u0003זכר ל\u0004זו של \u0003נקבה,\u0004 ללמדנו: \u0003מה נקבה בימים\u0004 — \u0003אף זכר בימים.\u0004","ומקשים: \u0003ולקיש\u0004 \u0005[ושישווה]\u0006 להיפך, שבא הכתוב להשוות \u0003נקבה לזכר,\u0004 ונאמר כך: \u0003מה זכר\u0004 מיטמא \u0003בראיות\u0004 אף אם הן ביום אחד — \u0003אף נקבה\u0004 טומאתה תלויה \u0003בראיות!\u0004 ומשיבים: \u0003הא מיעט רחמנא\u0004 \u0005[הרי מיעטה התורה]\u0006 אפשרות זו במלה \"\u0003וזאת\u0004\".","ושואלים: \u0003ומה ראית\u0004 לומר שהמיעוט מכוון למעט נקבות מראיות, ולא למעט זבים מימים? ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 הדבר, כי כאשר \u0003קאי\u0004 \u0005[עומד,\u0006 עוסק\u0005]\u0006 הכתוב \u0003ב\u0004עניני \u0003ראיות\u0004 — \u0003ממעט\u0004 הוא \u0003ראיות,\u0004 אבל האם יכול אתה לומר כי כאשר \u0003קאי\u0004 \u0005[עומד,\u0006 עוסק\u0005]\u0006 \u0003ב\u0004ענין \u0003ראיות\u0004 שעל ידי זה יהא \u0003ממעט ימים?!\u0004 שהמיעוט \"וזאת\" נאמר בהלכות הזב שהוזכרו בו ראיות, ולא ימים.","ושוב לענין הגדרת תם ומועד, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003איזהו מועד\u0004 — \u0003כל שהעידו בו\u0004 שנגח ב\u0003שלשה ימים, ו\u0004שב דינו להיות \u0003תם\u0004 — בזמן \u0003שיהו התינוקות ממשמשין בו ואינו נוגח,\u0004 אלו \u0003דברי ר' יוסי. ר' שמעון אומר: מועד\u0004 — \u0003כל שהעידו בו שלש פעמים, ולא אמרו שלשה ימים\u0004 — \u0003אלא לחזרה בלבד,\u0004 כלומר, שאם לא נגח שלושה ימים הרי הוא חוזר ונעשה תם. שתי השיטות הנוספות הללו מצרפות בתוכן מדברי ר' יהודה ומדברי ר' מאיר שבמשנתנו.","\u0003אמר רב נחמן אמר רב אדא בר אהבה: הלכה כר' יהודה במועד\u0004 שהוא כל שהעידו בו שלושה ימים, \u0003שהרי ר' יוסי מודה לו, והלכה כר' מאיר בתם,\u0004 כלומר, שחוזר לתמותו משיהו תינוקות ממשמשים בו ואינו נוגח, \u0003שהרי ר' יוסי מודה לו\u0004 בענין זה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: ולימא מר\u0004 \u0005[ושיאמר אדוני]\u0006 להיפך, \u0003הלכה כר' מאיר במועד, שהרי ר' שמעון מודה לו, והלכה כר' יהודה בתם, שהרי ר' שמעון מודה לו! אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן לרבא: \u0003אנא\u0004 \u0005[אני]\u0006 \u0003כר' יוסי סבירא לי\u0004 \u0005[סבור אני]\u0006 ואני פוסק לגמרי כפי שיטתו, ש\u0003ר' יוסי נימוקו\u0004 (טעמו וסברתו) \u0003עמו\u0004 ולכן ראוי לפסוק כשיטתו בכל מקום.","\u0003אבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003\"שלשה ימים\" דקתני\u0004 \u0005[ששנה]\u0006 במשנה בשיטתו של ר' יהודה, ששור נעשה מועד אם העידו בו שלושה ימים, האם הם נדרשים כדי \u0003לייעודי תורא\u0004 \u0005[לעשות\u0006 את \u0005השור מועד]\u0006 \u0003או לייעודי גברא\u0004 \u0005[להעיד\u0006 ב\u0005איש]\u0006 שנגח שורו, לומר לו שישמור על שורו?","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכאן,\u0006 מה ההבדל\u0005]\u0006 אם כך או כך הוא? ומשיבים: במקרה \u0003דאתו תלתא כיתי סהדי בחד יומא\u0004 \u0005[שבאו שלוש כיתות עדים ביום אחד]\u0006 לבית דין, וכל אחת מעידה על נגיחה ביום אחר, \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שעדותם היא כדי \u0003לייעודי תורא\u0004 \u0005[לעשות\u0006 את \u0005השור מועד],\u0006 לברר לנו שהוא רגיל בנגיחה — אם כן הרי הוא \u0003מייעד\u0004 \u0005[נעשה מועד]\u0006 בעדותם. \u0003ואי אמרת\u0004 \u0005[ו\u0006אולם \u0005אם אומר אתה]\u0006 שעדותם היא כדי \u0003לייעודי גברא\u0004 \u0005[להעיד\u0006 ב\u0005איש]\u0006 — הריהו \u0003לא מייעד\u0004 \u0005[נעשה מועד]\u0006 בכך, כיון שלא העידו בו בשלושה ימים, אלא ביום אחד בלבד, שכן \u0003מימר אמר\u0004 \u0005[יכול הוא לומר]:\u0006 רק \u0003השתא\u0004 \u0005[עכשיו\u0006 היום\u0005]\u0006 \u0003הוא דקמסהדו\u0004 \u0005[שמעידים]\u0006 \u0003בי\u0004 בפעם ראשונה, ואינו מועד עד שיתרו בו שלושה ימים. ואם כן \u0003מאי\u0004 \u0005[מה]\u0006 הפתרון לשאלה זו?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003אין השור נעשה מועד עד שיעידו בו בפני בעלים ובפני בית דין. העידו בו בפני בית דין ושלא בפני בעלים,\u0004 או \u0003בפני בעלים ושלא בפני בית דין\u0004 — \u0003אינו נעשה מועד עד שיעידו בו בפני בית דין ובפני בעלים.\u0004","ועוד בהלכות אלו: \u0003העידוהו שנים\u0004 עדים \u0003ב\u0004אשר לנגיחה \u0003ראשונה, ושנים ב\u0004אשר לנגיחה \u0003שניה, ושנים ב\u0004אשר לנגיחה \u0003שלישית\u0004 — \u0003הרי כאן שלש עדיות\u0004 נפרדות, \u0003ו\u0004אולם \u0003הן\u0004 נחשבות \u0003עדות אחת ל\u0004ענין \u0003הזמה,\u0004 שאם יתברר שקבוצה אחת של עדים משקרת הרי כל העדות כולה פסולה, והשור עדיין תם.","לפיכך, \u0003נמצאת\u0004 \u0003כת ראשונה זוממת\u0004 — \u0003הרי\u0004 נותרו \u0003כאן שתי עדיות\u0004 שהעידו שנגח, ומשלם עליהן חצי נזק. \u0003והוא\u0004 בעל השור \u0003פטור\u0004 מלשלם נזק שלם. \u0003והן\u0004 העדים הזוממים \u0003פטורים\u0004 מלשלם לבעלים מה שהיה צריך לשלם עבור נגיחה של מועד, כדין עדים זוממים, שהרי הם לא העידו אלא על הנגיחה הראשונה, ובעדות זו עצמה לא היה נעשה שור מועד. וכן אם \u0003נמצאת\u0004 גם \u0003כת שניה זוממת\u0004 — \u0003הרי כאן עדות אחת\u0004 השלישית, \u0003והוא\u0004 הבעלים \u0003פטור\u0004 מנזק שלם, \u0003והן\u0004 העדים הזוממים \u0003פטורים\u0004 מלשלם לו נזק שלם.","\u0003נמצאת\u0004 גם \u0003כת שלישית זוממת\u0004 — כל העדים \u0003כולן חייבין,\u0004 שהכת השלישית מתחייבת בתשלום עבור חצי נזק הנגיחה השלישית שרצו לחייבו, ושלוש הכתות מתחלקות ביניהן בתשלום חצי הנזק הנוסף שרצו לחייבו כשור מועד. \u0003ועל זה נאמר \"ועשיתם לו כאשר זמם\u0004 לעשות לאחיו","\u0003\"\u0004(דברים יט, יט). עד כאן לשון הברייתא, ומעתה נברר: \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהעדות היא כדי \u0003לייעודי תורא\u0004 \u0005[לעשות\u0006 את \u0005השור מועד]\u0006 — \u0003שפיר\u0004 \u0005[יפה]\u0006 ומובן הדין, שהרי לשיטה זו מדובר שבאים כולם להעיד ביום אחד, ובוודאי יודעים הם זה בעדותו של זה, ולכן אחראים גם העדים הראשונים לעדות השקרית של האחרונים, שהם כשותפים בכוונה לעשות את השור מועד, אף שהם עצמם העידו אמת."],["\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהעדים באים כדי \u0003לייעודי גברא\u0004 \u0005[להעיד,\u0006 ב\u0005איש],\u0006 בבעל השור, ובאים יום לאחר יום, \u0003לימרו הנך קמאי\u0004 \u0005[שיאמרו אלה\u0006 העדים \u0005הראשונים]:\u0006 \u0003אנן מי הוה ידעינן דבתר תלתא יומי אתו הני ומייעדי ליה\u0004 \u0005[אנו האם היינו יודעים שאחרי שלושה ימים יבואו אלה\u0006 העדים \u0005ויעשו אותו מועד]?\u0006 אלא ודאי מדובר בשבאו שלוש קבוצות העדים בבת אחת, ואם כן ההעדאה באה לייעד את השור!","\u0003אמר רב אשי: אמריתה לשמעתא קמיה\u0004 \u0005[אמרתי את השמועה,\u0006 הדיון הזה, \u0005בפני]\u0006 \u0003רב כהנא,\u0004 \u0003ואמר לי\u0004 כתשובה להוכחה זו: \u0003ולייעודי תורא מי ניחא\u0004 \u0005[ו\u0006אם נאמר ש\u0005לייעד\u0006 את \u0005השור\u0006 באה ההעדאה, \u0005האם\u0006 זה \u0005נוח]?\u0006 שאף אם באו כל העדים ביום אחד \u0003ולימרו הנך בתראי\u0004 \u0005[ויאמרו אלה האחרונים]:\u0006 \u0003אנן מנא ידעינן\u0004 \u0005[אנו מנין אנו יודעים]\u0006 ש\u0003כל דקאי בי דינא לאסהודי בתורא קאתו\u0004 \u0005[שעומד בבית הדין להעיד בשור\u0006 הוא \u0005בא]?\u0006 \u0003אנן לחיובי גברא פלגא נזקא אתינן\u0004 \u0005[אנו לחייב\u0006 את \u0005האיש\u0006 ב\u0005חצי נזק באנו],\u0006 כלומר, העדנו ששורו נגח שור אחר, ולא ידענו שבאו כבר עדים אחרים ועדותנו מחייבת אותו בנזק שלם!","ומשיבים: צריכים לומר שמדובר כשאנו רואים \u0003דקמרמזי רמוזי\u0004 \u0005[שמרמזים רמיזות]\u0006 זה לזה, שברור שיודעים הם זה בעדותו של זה, ולשם כך באו. \u0003רב אשי אמר: כשבאו רצופים\u0004 מיד בזה אחר זה, וברור שהם יודעים על העדויות הראשונות.","\u0003רבינא אמר:\u0004 כאן מדובר \u0003במכירין\u0004 העדים את \u0003בעל השור\u0004 ששורו נגח \u0003ואין מכירין את השור\u0004 עצמו, שמוכח מכך שבאים לעשותו מועד. שכיון שאין מכירים איזה שור נגח לא היו יכולים לחייב את בעליו בחצי נזק, שהרי תשלום זה גובים רק מגופו של השור. ומכאן שידעו זה מזה, ובאו לחייב את הבעלים בנזק שלם, שהוא משתלם ממיטב הנכסים של הבעלים.","ושואלים: כיון שאין מכירים את השור, \u0003היכי מייעדי ליה\u0004 \u0005[כיצד יכולים לעשות אותו מועד]?\u0006 ומשיבים: \u0003דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]\u0006 לבעל השור: \u0003תורא נגחנא אית\u0004 \u0005[שור נגחן יש]\u0006 \u0003לך בבקרך,\u0004 \u0003אבעי לך לנטורי לכוליה בקרא\u0004 \u0005[צריך אתה לשמור את כל הבקר].\u0006","\u0003אבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003המשסה\u0004 את \u0003כלבו של חבירו בחבירו\u0004 אחר והזיקו, \u0003מהו\u0004 הדין? \u0003משסה ודאי פטור,\u0004 שהרי הוא לא עשה מעשה, ולא רכושו עשה מעשה, \u0003בעל\u0004 ה\u0003כלב מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כי \u0003מצי אמר ליה\u0004 \u0005[יכול לומר לו]\u0006 בעל הכלב לניזק: \u0003אנא מאי עבידנא ליה\u0004 \u0005[אני מה עשיתי לו]\u0006 לכלב? \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אמרינן ליה\u0004 \u0005[אומרים אנו לו]:\u0006 \u0003כיון דידעת\u0004 \u0005[שיודע אתה]\u0006 \u0003בכלבך דמשסי ליה ומשתסי\u0004 \u0005[שמשסים אותו ו\u0006הוא \u0005משתסה]\u0006 \u0003לא אבעי לך לאשהוייה\u0004 \u0005[היית צריך להשהותו\u0006 אצלך\u0005],\u0006 וכיון שהשארת את הכלב ברשותך חייב אתה בנזקים שנגרמו על ידו.","\u0003אמר ר' זירא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במשנתנו: \u0003ו\u0004מתי חוזר השור להיות \u0003תם\u0004 — \u0003שיהו התינוקות ממשמשין בו ואינו נוגח.\u0004 ואפשר לדייק מכאן כי \u0003הא\u0004 \u0005[הרי]\u0006 אם היה \u0003נוגח\u0004 כאשר התינוקות ממשמשים בו — \u0003חייב\u0004 בעליו בתשלום הנזק. והרי שור הנוגח מתוך שהתינוקות ממשמשים בו הריהו כנוגח על ידי שיסוי, ובכל זאת אומרים אנו שחייב! \u0003אמר אביי: מי קתני\u0004 \u0005[האם שנה\u0006 שם\u0005]:\u0006 אם \u0003נגח חייב? דלמא\u0004 \u0005[שמא]\u0006 כך צריך לדייק, להיפך: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003נגח\u0004 — \u0003לא הוי\u0004 \u0005[אינו נהיה\u0006 נעשה\u0005]\u0006 \u0003תם\u0004 ועדיין נשאר בחזקת מועד, \u0003ו\u0004אולם \u0003בההיא\u0004 \u0005[באותה]\u0006 \u0003נגיחה\u0004 שנגח לאחר ששיסו אותו התינוקות — \u0003לא מחייב\u0004 \u0005[חייב]\u0006 משום ששיסוהו. ואם כן אין להוכיח מכאן.","ומנסים להוכיח ממקור אחר, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003שיסה בו את הכלב, שיסה בו נחש\u0004 — \u0003פטור. מאי לאו\u0004 \u0005[האם אין\u0006 הכוונה\u0005]\u0006 \u0003פטור\u0004 ה\u0003משסה, וחייב בעל\u0004 ה\u0003כלב?\u0004 ודוחים: \u0003לא, אימא\u0004 \u0005[אמור]:\u0006 \u0003פטור אף משסה\u0004 ולא רק בעל הכלב.","\u0003אמר רבא: אם תמצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\u0004 ש\u0003המשסה כלבו של חבירו בחבירו\u0004 — \u0003חייב, שיסהו הוא בעצמו,\u0004 כלומר, שאותו אדם עצמו הרגיז את הכלב, והכלב נשך אותו — \u0003פטור. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — זה הכלל: \u0003כל המשנה,\u0004 שעושה מעשה שאינו ראוי, \u0003ובא אחר ושינה בו\u0004 אף הוא והזיקו — \u0003פטור\u0004 המזיק. וכיון שהאיש שינה ושיסה את הכלב, הרי מה שמזיק הכלב אחר כך — אין בעליו חייב עליו, אף שסתם נשיכה של כלב שינוי הוא וחייב בעליו על כך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא: איתמר משמיה\u0004 \u0005[נאמר משמו]\u0006 של \u0003ריש לקיש כוותיך\u0004 \u0005[כשיטתך],\u0006 שהמשנה ובא אחר ושינה והזיקו — פטור. ש\u0003אמר ריש לקיש: שתי פרות\u0004 שהיו \u0003ברשות הרבים, אחת רבוצה\u0004 ברחוב \u0003ואחת מהלכת, ובעטה מהלכת ברבוצה\u0004 — \u0003פטורה,\u0004 בעטה \u0003רבוצה במהלכת\u0004 — \u0003חייבת.\u0004 וטעמו של דבר — כי כיון שהרביצה היא שינוי, שהרי אין ראוי לפרה להיות רבוצה ברשות הרבים, הרי גם אם השניה בעטה בה, שאף הוא שינוי — פטורה עליה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לרב פפא: אין זה כשיטתי, כיון ש\u0003אנא בההיא חיובי מחייבנא\u0004 \u0005[אני\u0006 דווקא \u0005באותו\u0006 מקרה שפוטר ריש לקיש \u0005מחייב אני],\u0006 משום שלדעתי \u0003אמרינן ליה\u0004 \u0005[אומרים אנו לו]\u0006 לבעל הפרה המזיקה: \u0003כי אית\u0004 \u0005[כאשר יש]\u0006 \u0003לך רשותא\u0004 \u0005[רשות]\u0006 ברשות הרבים, הרי זה \u0003לסגויי\u0004 \u0005[לדרוך]\u0006 \u0003עלי,\u0004 שאם היתה הפרה המהלכת עולה על הפרה הרובצת היה מותר לך, אבל \u0003לבעוטי\u0004 \u0005[לבעוט]\u0006 \u0003בי לית\u0004 \u0005[אין]\u0006 \u0003לך רשותא\u0004 \u0005[רשות]\u0006 ואם כן אין דעתו של רבא כדעת ריש לקיש לגמרי.","\u0003שור המזיק ברשות הניזק\u0004 ששנינו במשנה לעיל (בבא קמא טו,ב) שבכלל המועדים הוא, \u0003כיצד?\u0004 אם \u0003נגח, נגף\u0004 (דחף), \u0003נשך, רבץ, בעט.\u0004 עשה זאת השור \u0003ברשות הרבים\u0004 — הרי זה \u0003משלם חצי נזק\u0004 אם תם הוא. \u0003ברשות הניזק\u0004 — \u0003ר' טרפון אומר:\u0004 משלם \u0003נזק שלם. וחכמים אומרים:\u0004 משלם רק \u0003חצי נזק\u0004 כבכל נזקי קרן.","\u0003אמר להם ר' טרפון\u0004 לחכמים: \u0003ומה במקום שהקל על השן ועל הרגל, ברשות הרבים, שהוא פטור\u0004 על נזקיהם — \u0003החמיר עליהן\u0004 אם היו \u0003ברשות הניזק לשלם נזק שלם, מקום שהחמיר על הקרן, ברשות הרבים, לשלם חצי נזק\u0004 בכל מקרה, \u0003אינו דין שנחמיר עליו\u0004 שאם היה הדבר \u0003ברשות הניזק לשלם נזק שלם?\u0004","\u0003אמרו לו\u0004 חכמים לר' טרפון: אף על פי שקל וחומר הוא, בכל אופן \u0003דיו לבא מן הדין להיות כנדון.\u0004 כלומר, דבר הנלמד מקל וחומר אינו יכול להיות יותר מהדבר שממנו הוא למד, ויש איפוא לומר, \u0003מה ברשות הרבים\u0004 משלם \u0003חצי נזק\u0004 — \u0003אף ברשות הניזק\u0004 אינו משלם אלא \u0003חצי נזק.\u0004","\u0003אמר להם\u0004 ר' טרפון: אם כן, \u0003אף אני\u0004"],["\u0003לא אדון קרן מקרן\u0004 שתוכלו לפרוך את הקל וחומר, מטעם \"דיו\" אלא \u0003אני אדון קרן מרגל,\u0004 ואומר כך: \u0003ומה במקום שהקל על השן ועל הרגל,\u0004 שפטור \u0003ברשות הרבים\u0004 — \u0003החמיר בקרן\u0004 שמשלם עליה גם שם, \u0003מקום שהחמיר על השן ועל הרגל, ברשות הניזק\u0004 שמשלם נזק שלם — \u0003אינו דין שנחמיר בקרן\u0004 שישלם הכל?","\u0003אמרו לו:\u0004 אף כאן \u0003דיו לבא מן הדין להיות כנדון, מה ברשות הרבים\u0004 משלם על קרן \u0003חצי נזק\u0004, \u0003אף ברשות הניזק\u0004 — \u0003חצי נזק,\u0004 שהרי סוף סוף אתה סומך על ההלכה שעל הקרן משלם חצי נזק.","ושואלים: \u0003ו\u0004כי \u0003ר' טרפון לית ליה\u0004 \u0005[אין לו\u0006 אינו מקבל\u0005]\u0006 את הכלל של \u0003דיו?\u0004 \u0003והא\u0004 \u0005[והרי]\u0006 כלל זה של \u0003דיו דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003הוא! דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מה שאמרו חכמים שהתורה נדרשת \u0003מדין\u0004 (דרך הלימוד) של \u0003קל וחומר, כיצד\u0004 הוא? לאחר שנזף ה' במרים אחות משה נאמר \u0003\"ויאמר ה' אל משה: ואביה ירק ירק בפניה הלא תכלם שבעת ימים,\u0004 תסגר שבעת ימים מחוץ למחנה\u0003\"\u0004 (במדבר יב, יד), כלומר, אילו אביה היה נוזף בה היתה בנידוי ובהסגר שבעה ימים. ולכאורה, \u0003קל וחומר לשכינה,\u0004 שאם השכינה נוזפת באדם, כפי שעשה הקדוש ברוך הוא למרים — ראוי לו שיהא מנודה לפחות \u0003ארבעה עשר יום. אלא דיו לבא מן הדין להיות כנדון\u0004 ולכן היתה מרים מנודה רק שבעה ימים, כנאמר שם \"ותסגר מרים מחוץ למחנה שבעת ימים\" (במדבר י״ב:ט״ו). ואם כן, איך אפשר לומר שר' טרפון אינו מקבל כלל זה?","ומשיבים: \u0003כי לית ליה\u0004 \u0005[כאשר אין לו]\u0006 לר' טרפון \u0003דיו,\u0004 הרי זה \u0003היכא דמפריך\u0004 \u0005[היכן שנשבר]\u0006 לגמרי ה\u0003קל וחומר,\u0004 שאם משתמשים בכלל של \"דיו\" בטל הקל וחומר, אבל \u0003היכא דלא מפריך\u0004 \u0005[היכן שאינו נשבר]\u0006 ה\u0003קל וחומר\u0004 — \u0003אית ליה\u0004 \u0005[יש לו]\u0006 \u0003דיו.\u0004 ומסבירים: \u0003התם\u0004 \u0005[שם]\u0006 אצל מרים \u0003שבעה\u0004 הימים הראויים לנדות את הנזוף על ידי ה\u0003שכינה לא כתיבי\u0004 \u0005[כתובים],\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 ה\u0003קל וחומר\u0004 ו\u0003אייתי\u0004 \u0005[הביא\u0006 והוסיף ולימד\u0005]\u0006 על \u0003ארבסר\u0004 \u0005[ארבעה עשר]\u0006 יום, \u0003אתא\u0004 \u0005[בא]\u0006 \u0003דיו אפיק\u0004 \u0005[\u0006ו\u0005הוציא]\u0006 \u0003שבעה\u0004 מארבעה עשר יום אלה, \u0003ואוקי\u0004 \u0005[והעמיד]\u0006 את הקל וחומר על \u0003שבעה\u0004 ימים, ואם כן למדים אנו מקל וחומר זה את עצם ההסגר שבעה ימים, שאינו כתוב.","\u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003חצי נזק\u0004 \u0003כתיב\u0004 \u0005[כתוב]\u0006 במפורש בתורה, \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003קל וחומר ואייתי\u0004 \u0005[והביא\u0006 והוסיף\u0005]\u0006 \u0003חצי נזק אחרינא\u0004 \u0005[אחר]\u0006 \u0003ונעשה נזק שלם.\u0004 ואולם \u0003אי דרשת\u0004 \u0005[אם דורש אתה]\u0006 כאן את דין \u0003דיו אפריך ליה\u0004 \u0005[נשבר לו]\u0006 \u0003קל וחומר\u0004 לגמרי, שאין למדים ממנו דבר חדש שלא ידענוהו מקודם, שהרי ממילא משלם חצי נזק!","\u0003ו\u0004מן הצד השני \u0003רבנן\u0004 \u0005[וחכמים]\u0006 מה הם משיבים לדבר זה? — לדעתם \u0003שבעה\u0004 הימים של \u0003שכינה\u0004 גם כן \u0003כתיבי\u0004 \u0005[כתובים],\u0006 שכן נאמר \u0003\"תסגר שבעת ימים\"\u0004 (במדבר טו), ונמצא שגם במקום שנפרך לגמרי הקל וחומר אומרים דיו.","\u0003ור' טרפון\u0004 מה הוא אומר? — \u0003ההוא\u0004 \u0005[אותו\u0006 כתוב\u0005]\u0006 \u0003\"תסגר\"\u0004 בא ללמדנו \u0003דדרשינן\u0004 \u0005[שאנו דורשים]\u0006 \u0003דיו הוא.\u0004","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים על כך? — לדעתם \u0003כתיב קרא אחרינא\u0004 \u0005[כתוב פסוק אחר]\u0006 \u0003\"ותסגר מרים\u0004 מחוץ למחנה שבעת ימים\u0003\"\u0004 (במדבר י״ב:ט״ו). \u0003ור' טרפון\u0004 מה אומר הוא על כך? \u0003ההוא\u0004 \u0005[אותו\u0006 כתוב\u0005]\u0006 מלמד ש\u0003אפילו בעלמא\u0004 \u0005[בכלל]\u0006 ולא רק במקרה זה \u0003דרשינן\u0004 \u0005[דורשים אנו]\u0006 את הכלל של \u0003דיו. ולא תאמר\u0004 כי \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003משום כבודו של משה\u0004 לא נתמצה עומק הדין עם אחותו, \u0003אבל בעלמא\u0004 \u0005[בדרך כלל]\u0006 \u0003לא\u0004 ואין דורשים דיו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שמשתמשים בכלל של דיו בכל מקרה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי:\u0004 וכי עקרון זה של \"דיו\" מוסכם על הכל? \u0003והא האי תנא\u0004 \u0005[והרי\u0006 יש \u0005תנא זה]\u0006 ש\u0003לא דריש\u0004 \u0005[דורש]\u0006 \u0003דיו\u0004 כלל, \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003לא מפריך\u0004 \u0005[נשבר]\u0006 ה\u0003קל וחומר\u0004 מעיקרו! \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003קרי\u0004 (שכבת זרע) \u0003ב\u0004מי שהוא \u0003זב מניין\u0004 שהוא מטמא, בין בטומאת מגע ובין בטומאת משא, כמו הזיבה עצמה? — \u0003ודין\u0004 (קל וחומר) \u0003הוא: מה\u0004 רוק שהוא \u0003טהור ב\u0004שעה שיוצא מאדם \u0003טהור,\u0004 הריהו \u0003טמא ב\u0004שעה שיוצא מן ה\u0003טמא\u0004 מן הזב, שמפורש בתורה שרוקו של הזב טמא. דבר שהוא \u0003טמא בטהור,\u0004 כלומר, קרי, שאף בטהור מטמא הקרי — \u0003אינו דין שיהא טמא בטמא\u0004 ומטמא בזב כטומאת הזב עצמו?","\u0003וקא מייתי לה\u0004 \u0005[והוא מביא אותו\u0006 ולומד ממנו\u0005]\u0006 מקל וחומר זה הלכה זו \u0003בין ל\u0004טומאת \u0003מגע בין ל\u0004טומאת \u0003משא\u0004 שבזב. \u0003ו\u0004אם משתמשים ב\"דיו\", \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003נימא\u0004 \u0005[נאמר\u0006 כך\u0005]:\u0006 \u0003אהני\u0004 \u0005[הועיל]\u0006 \u0003קל וחומר ל\u0004ענין טומאת \u0003מגע\u0004 בקרי של הזב, \u0003אהני\u0004 \u0005[הועיל]\u0006 \u0003דיו לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 טומאת \u0003משא!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003למגע לא אצטריך\u0004 \u0005[הוצרך]\u0006 \u0003קל וחומר,\u0004 שהרי \u0003לא גרע\u0004 \u0005[גרוע,\u0006 פחות\u0005]\u0006 הזב \u0003מגברא\u0004 \u0005[מאיש]\u0006 \u0003טהור,\u0004 שהרי אף בטהור יש בקרי טומאת מגע, ואם כן לא בא הקל וחומר אלא לענין טומאת משא, ואין כאן מקום ל\"דיו\" — על כך יש להשיב כי מכל מקום \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 ללמוד אף למגע, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003\"מקרה לילה\"\u0004 (דברים כג, יא) \u0003כתיב\u0004 \u0005[נאמר],\u0006 ונלמד מכאן שטמא רק \u0003מי שקריו\u0004 (שמקרה שקרה לו) הוא \u0003גורם לו\u0004 שיצא הזרע, \u0003יצא\u0004 זב \u0003זה, שאין קריו גורם לו אלא דבר אחר\u0004 (מחלת הזיבה) \u0003גרם לו,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 מלמדנו הקל וחומר שהקרי מטמא אף אצל הזב.","השיב לו אביי: \u0003מידי\u0004 \u0005[וכי]\u0006 \u0003\"\u0004מקרה לילה \u0003ולא דבר אחר\" כתיב\u0004 \u0005[נאמר]\u0006 בו? הרי הגדרה וצמצום זה לא נאמרו בכתוב. ונמצא שאנו יודעים שקרי מטמא במגע מכתוב מפורש, והואיל ואין כאן מקום כלל ל\"דיו\", ממילא אין להוכיח מכאן שאין משתמשים בו.","ואגב שהובא ענין זה, מבררים: \u0003ומאן\u0004 \u0005[ומיהו]\u0006 אותו \u0003תנא\u0004 ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 שאומר ש\u0003שכבת זרע של זב מטמא במשא?\u0004 הלא אין זה \u0003לא\u0004 כדעת \u0003ר' אליעזר ולא\u0004 כדעת \u0003ר' יהושע. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שכבת זרע של זב מטמא במגע ואין מטמא במשא,\u0004 אלו \u0003דברי ר' אליעזר. ור' יהושע אומר: אף מטמא במשא, לפי שאי אפשר\u0004 שתצא מזב שכבת זרע \u0003בלא צחצוחי\u0004 (טיפות קטנות של) \u0003זיבה.\u0004","ונדייק: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' יהושע התם\u0004 \u0005[שם]\u0006 שמטמא במשא \u0003אלא\u0004 מפני הטעם \u0003שאי אפשר בלא צחצוחי זיבה, הא לאו הכי\u0004 \u0005[הרי\u0006 אם ב\u0005לא כך]\u0006 — \u0003לא,\u0004 שמצד עצמו אין הקרי של זב מטמא במשא אף לר' יהושע! \u0003אלא\u0004 יש לומר כי \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003תנא הוא\u0004 שסבור כן, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 ברשימת הטומאות: \u0003למעלה מהן\u0004 מטומאות שרץ ושכבת זרע וטמא מת, הנמנות שם קודם,"],["\u0003זובו של זב, ורוקו\u0004 של זב, \u0003ושכבת זרעו, ומימי רגליו\u0004 של הזב, \u0003ו\u0004כן \u0003דם הנדה\u0004 — כל אלה \u0003מטמאין בין במגע בין במשא.\u0004","ודוחים: \u0003ודלמא הכי נמי\u0004 \u0005[ושמא כאן גם כן]\u0006 הטעם הוא כדברי ר' יהושע \u0003לפי שאי אפשר\u0004 לקרי \u0003בלא צחצוחי זיבה,\u0004 ולא שמטמא במשא מצד עצמו! ודוחים: \u0003אם כן\u0004 שהקרי טמא רק משום צחצוחי זיבה \u0003לתנייה גבי\u0004 \u0005[שישנה אותו אצל\u0006 ליד\u0005]\u0006 \u0003זובו, מאי שנא\u0004 \u0005[מה שונה,\u0006 מה טעם\u0005]\u0006 \u0003דקתני לה גבי\u0004 \u0005[ש\u0006הוא \u0005שונה אותו אצל]\u0006 \u0003רוקו, אלא משום דאתי\u0004 \u0005[שבא,\u0006 שנלמד הדבר\u0005]\u0006 בקל וחומר \u0003מרוקו\u0004 כפי שנאמר בעמוד הקודם.","וחוזרים לעיקר הסוגיה, בענין \"דיו\". \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא: והא האי\u0004 \u0005[זה]\u0006 ה\u0003תנא\u0004 ש\u0003לא דריש\u0004 \u0005[דורש]\u0006 \u0003דיו ואף על גב\u0004 ש\u0003לא מפריך\u0004 \u0005[נשבר]\u0006 ה\u0003קל וחומר\u0004 על ידי כך! \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מפץ\u0004 (מחצלת גסה) שמקבלת טומאה \u0003ב\u0004טומאת \u0003מת מניין?\u0004 — \u0003ודין\u0004 (קל וחומר) \u0003הוא: ומה פכין\u0004 (כלי חרס) \u0003קטנים\u0004 שאי אפשר להכניס אצבע לתוכם, \u0003ש\u0004הם \u0003טהורים ב\u0004טומאת ה\u0003זב,\u0004 מכל מקום \u0003מטמא במת,\u0004 שכל כלי פתוח טמא באוהל המת, \u0003מפץ שמטמא בזב\u0004 — \u0003אינו דין שיטמא במת?\u0004","\u0003וקמייתי לה\u0004 \u0005[ו\u0006הוא \u0005מביא אותה,\u0006 לומד מכאן\u0005]\u0006 \u0003בין לטומאת ערב\u0004 שנטמא בו ביום עד הערב כמו אם היה נטמא מזב, \u0003בין לטומאת שבעה\u0004 ימים, ככלי שנטמא במת. \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 נאמר כך? \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003אהני\u0004 \u0005[הועיל]\u0006 \u0003קל וחומר ל\u0004ענין \u0003טומאת ערב, ואהני\u0004 \u0005[והועיל]\u0006 \u0003דיו לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003טומאת שבעה\u0004 שאינה מצויה בדבר שנטמא בטומאת משכב הזב! הרי שתנא זה אינו דורש \"דיו\".","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא לרב אחא: \u0003כבר רמא ניהליה\u0004 \u0005[הקשה לו]\u0006 קושיה זו \u0003רב נחמן בר זכריה לאביי, ואמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 בתשובה: ה\u0003תנא\u0004 הזה אינו לומד מזב, אלא \u0003ממפץ בשרץ מייתי לה\u0004 \u0005[מביא,\u0006 לומד \u0005אותה],\u0006 \u0003והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003מפץ\u0004 שמיטמא \u0003ב\u0004טומאת \u0003שרץ מניין? ודין הוא: ומה פכין קטנים שטהורים בזב\u0004 — \u0003טמאין בשרץ, מפץ שטמא בזב\u0004 — \u0003אינו דין שיהא טמא בשרץ?\u0004","\u0003אלא מפץ במת מניין\u0004 שמיטמא — משום שנלמד מגזירה שווה, \u0003נאמר \"בגד\u0004 או \u0003עור\"\u0004 (ויקרא יא, לב) \u0003ב\u0004טומאת \u0003שרץ, ונאמר \"בגד ו\u0004כל כלי \u0003עור\"\u0004 (במדבר לא, כ) \u0003ב\u0004טומאת \u0003מת, מה \"בגד\" ו\"עור\" האמור בשרץ\u0004 — \u0003מפץ טמא בו\u0004 כפי שלמדנו מקל וחומר מזב, \u0003אף \"בגד\" ו\"עור\" האמור במת\u0004 — \u0003מפץ טמא בו.\u0004","ומעירים שבהכרח לומר ש\"בגד ועור\" הריהו בגדר \u0003מופנה,\u0004 כלומר, ביטוי שאינו צריך לגופו אלא בא ללמדנו גזירה שווה זו, \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא מופנה\u0004 הוא, \u0003איכא למפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך]\u0006 את ההשוואה ולומר: \u0003מה לשרץ\u0004 — \u0003שכן מטמא בכעדשה, תאמר במת שאין מטמא בכעדשה אלא בכזית,\u0004 ונמצא שטומאת שרץ יש בה צד חמור ולא ניתן היה ללמוד גזירה שווה אלא אם כתוב זה מופנה לכך.","\u0003לאיי אפנויי מופנה\u0004 \u0005[ובאמת\u0006 יש לומר כי \u0005מופנה\u0006 הוא\u0005],\u0006 ומנין שהוא מופנה: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003שרץ אתקש\u0004 \u0005[הוקש]\u0006 \u0003לשכבת זרע, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"או איש אשר תצא\u0004 ממנו שכבת זרע\u0003\"\u0004 (ויקרא כב, ד), \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 נאמר \u0003\"או איש אשר יגע בכל שרץ\"\u0004 (ויקרא פסוק ה), \u0003וכתיב ביה\u0004 \u0005[ונאמר בו]\u0006 \u0003ב\u0004טומאת \u0003שכבת זרע \"וכל בגד וכל עור אשר יהיה עליו שכבת זרע\"\u0004 (ויקרא טו, יז).","אם כן \u0003\"בגד ועור\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003ב\u0004טומאת \u0003שרץ למה לי?\u0004 הרי אפשר ללמוד אותו על ידי ההיקש משכבת זרע! \u0003שמע מינה לאפנויי\u0004 \u0005[למד מכאן\u0006 כי בא הדבר \u0005להפנות]\u0006 כתוב זה שהוא מיותר לצורך גזירה שווה.","ושואלים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 הלא \u0003מופנה\u0004 רק \u0003מצד אחד הוא\u0004 ש\"בגד ועור\" האמור בדין שרץ מיותר, אבל \"בגד ועור\" האמור בטומאת מת אינו מיותר! \u0003הניחא למאן דאמר\u0004 \u0005[זה\u0006 אמנם \u0005נוח ל\u0006שיטת \u0005מי שאומר]\u0006 אם היתה גזירה שווה \u0003מופנה מצד אחד\u0004 שרק כתוב אחד מופנה — \u0003למידין\u0004 גזירה שווה זו \u0003ואין משיבין\u0004 (מקשים) — \u0003שפיר\u0004 \u0005[יפה],\u0006 \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 שגזירה שווה כזו אמנם \u0003למידין ו\u0004אולם אם יש מקום לדבר, גם \u0003משיבין\u0004 מקשים על ההשוואה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי ראינו שיש צד חמור בשרץ מבמת!","ומתרצים: \"בגד ועור\" האמור ב\u0003מת נמי אפנויי מופנה\u0004 \u0005[גם כן מופנה\u0006 הוא\u0005],\u0006 כיצד? \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003מת אתקש\u0004 \u0005[הושווה]\u0006 \u0003לשכבת זרע, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"והנוגע בכל טמא נפש או איש אשר תצא ממנו\u0004 שכבת זרע\u0003\"\u0004 (ויקרא כב, ד), \u0003וכתיב ביה\u0004 \u0005[ונאמר בו]\u0006 \u0003בשכבת זרע \"וכל בגד וכל עור אשר יהיה עליו שכבת זרע\"\u0004 (ויקרא טו, יז), אם כן \u0003\"בגד ועור\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003במת\u0004 \u0003למה לי? שמע מינה לאפנויי\u0004 \u0005[למד מכאן\u0006 שבא הדבר \u0005להפנות]\u0006 את הכתוב כדי ללמוד ממנו בגזירה שווה, \u0003והוי\u0004 \u0005[והריהו]\u0006 אם כן \u0003מופנה משני צדדין\u0004 ובמקרה זה ודאי למדים גזירה שווה ואין משיבים עליה.","ומקשים מצד אחר: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]:\u0006 \u0003דון מינה ואוקי באתרא\u0004 \u0005[למד ממנה והעמידה במקומה],\u0006 שדבר שנלמד בגזירה שווה לומדים אותו רק באותו פרט שנאמרה בו הגזירה שווה, ואין משווים את הנושאים מעבר לכך, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]:\u0006 \u0003דון מינה ומינה\u0004 \u0005[למד ממנה וממנה],\u0006 שאם יש גזירה שווה בין עניינים, הריהם למדים זה מזה בכל ענייניהם, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שלפי זה כשם שבטומאת שרץ הטומאה של מפץ היא רק לטומאת ערב, אף טומאת מפץ במת תהיה רק טומאת ערב!","בתשובה לכך \u0003אמר רבא:\u0004 אף לשיטה זו יש בכך גזירת כתוב מיוחדת, \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"וכבסתם בגדיכם ביום השביעי\"\u0004 (במדבר לא, כד), ללמדנו: \u0003כל טמאות שאתם מטמאין במת\u0004 — \u0003לא יהו פחותין משבעה,\u0004 ואם כן, כיון שלמדנו בו דין טומאה במת — הרי דינו כשאר הטומאות בטומאות מת.","עד כאן דנו בענין דרך הלימוד ב\"דיו\", ומעתה חוזרים אנו אל הדיון בעיקרי הדעות במשנה בענין נזקי קרן. ושואלים: \u0003ותהא שן ורגל חייב ברשות הרבים,\u0004 ונלמד הדבר \u0003מקל וחומר,\u0004 ובאופן זה: \u0003ומה קרן, שברשות הניזק אינו משלם אלא חצי נזק\u0004 כדברי חכמים, \u0003ברשות הרבים\u0004 — \u0003חייבת, שן ורגל, שברשות הניזק משלם נזק שלם\u0004 והרי זה חמור בהשוואה לקרן — \u0003אינו דין שברשות הרבים\u0004 יהא \u0003חייב\u0004 לשלם?","ודוחים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין שן ורגל \u0003\"ובער בשדה אחר\"\u0004 (שמות כב, ד), כלומר, חיובו דווקא בשדה הניזק \u0003ולא ברשות הרבים.\u0004"]]};
